window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-cardiologia-car-2"]={"block":"medcurso:medcurso-cardiologia-car-2","label":"Medcurso · CAR 2","count":427,"questions":[{"id":"medcurso-cardiologia-car-2-345435","number":"345435","sourceNumber":"345435","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A insuficiência cardíaca (IC) é uma síndrome clínica caracterizada pela incapacidade do\ncoração de atuar adequadamente como bomba, quer seja por déficit de contração e/ou de\nrelaxamento, comprometendo o funcionamento do organismo, e quando não tratada\nadequadamente, reduzindo a qualidade de vida e a sobrevida. Um paciente com IC classe II, é\naquele em que:","options":{"A":"Ainda tem ausência de sintomas, é considerado assintomático e teve seu diagnóstico ao acaso\nna investigação diagnóstica de outras doenças\ncardíacas.","B":"Realiza atividades físicas menos intensas que as habituais que já são o suficiente para causar\nsintomas.","C":"Apresenta limitação física importante, porém confortável apenas no repouso com sintomas\nmoderados.","D":"As atividades físicas habituais causam sintomas; há limitação leve e sintomas leves."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-345449","number":"345449","sourceNumber":"345449","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Mulher de 73 anos com história de dispneia aos esforços vai à consulta médica. A\nradiografia do tórax revelou hipertensão venosa pulmonar. Encontra-se em uso de anticoagulante\noral, betabloqueador e diurético de alça, porém refere cansaço e dispneia. No exame apresenta\nritmo cardíaco irregular e frequência ventricular de 104 bpm, pressão arterial de 160/80 mmHg; há\ndistensão venosa jugular e edema dos membros inferiores, mas não foram encontrados sopros,\nterceira bulha ou ruídos adventícios pulmonares à ausculta. A radiografia do tórax revelou\nhipertensão venosa pulmonar e o ecocardiograma apresentou fração de ejeção de 65%, ventrículo\nesquerdo com diâmetro normal e hipertrofia concêntrica, e aumento do átrio esquerdo. Sobre essa\npaciente, podemos afirmar que apresenta:","options":{"A":"Insuficiência cardíaca; independentemente do tipo de disfunção ventricular, deve ser mantida a\nterapêutica atual.","B":"Insuficiência cardíaca com fração de ejeção preservada; a dose de diuréticos deve ser\naumentada, a pressão arterial sistêmica\najustada com medicação e mantida a anticoagulação oral.","C":"Insuficiência cardíaca com fração de ejeção reduzida; a hipertensão arterial deve ser melhor\ncontrolada com medicamentos e as doses de diurético e anticoagulante devem ser mantidas.","D":"Insuficiência cardíaca com fração de ejeção reduzida; deve ser realizado o controle da pressão\narterial com medicamentos, o diurético deve ser aumentado e deve ser acrescentada medicação\ninotrópica positiva, além de mantida a anticoagulação."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-345454","number":"345454","sourceNumber":"345454","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 52 anos, portador de Hipertensão Arterial Sistêmica (HAS) há 5 anos, veio\nà consulta de rotina. Faz uso regular de\ncaptopril (25 mg, de 8/8 horas). A pressão arterial\nverificada no consultório era de 170 x 110 mmHg. Nos controles realizados em casa, foram\nobservados sempre níveis elevados, semelhantes ao da consulta atual. Qual a conduta mais\nadequada?","options":{"A":"Associar um antagonista do receptor de angiotensina II ao esquema em uso.","B":"Associar um diurético trazídico ao esquema em uso.","C":"Realizar investigação de HAS resistente.","D":"Indicar realização de Monitorização Ambulatorial de Pressão Arterial (MAPA)."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-345471","number":"345471","sourceNumber":"345471","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um homem de 58 anos de idade, obeso, hipertenso, dislipdêmico e tabagista dá\nentrada na sala de emergência com queixa de\ndispneia, iniciada há cerca de uma hora. Após colher\nsua história, o médico toma ciência de infarto agudo do miocárdio sofrido há cerca de 6 meses, que\nnecessitou angioplastias e foi abordado em internação prolongada, devido à grande área cardíaca\natingida. Na verificação de sinais, o paciente apresentava TA 194x124 mmHg, FC 110 bpm, Tax\n36,4ºC, Sat.O2 87%. Notável piora do padrão ventilatório, com asculta contendo crepitantes até o\nalto dos 2/3 inferiores de ambos os pulmões com alguns bolhosos. Colhidos exames para análise,\nmedicado, o paciente foi recuperando o padrão ventilatório, assim como obteve redução da\ndispneia. Oximetria demonstrou melhora, chegando a 95% em ar ambiente. Após estabilização, o\npaciente explicitou que diariamente tem algum nível de dispneia, mas naquele dia teria piorado\nmuito. Considerando o caso clínico, assinale a alternativa que contém a conduta e as medidas que\no médico deve tomar na avaliação do caso:","options":{"A":"O provável quadro clínico é de infarto agudo do miocárdio. A melhora clínica foi mediada pela\nadministração de nitrato sublingual e betabloqueadores. A provável causa do novo IAM foi o prévio\ne dificuldades de tratamento, com contribuição de provável cardiopatia isquêmica.","B":"O provável quadro clínico é de Tromboembolismo Pulmonar (TEP). A melhora clínica foi\nmediada pela administração de Enoxaparina. A provável causa do TEP foi o IAM prévio.","C":"O provável quadro clínico é de insuficiência cardíaca descompensada. A melhora clínica foi\nmediada pela administração de nitrato sublingual e betabloqueadores, além de Enoxaparina.","D":"O provável quadro clínico é de insuficiência cardíaca descompensada. A melhora clínica foi\nmediada pela administração de diuréticos de alça, além de provável medicação vasodilatadora e\nadministração de O2. A provável causa da insuficiência cardíaca foi o IAM prévio, com contribuição\nde cardiopatia isquêmica crônica."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-345496","number":"345496","sourceNumber":"345496","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Considere que um menino de 9 anos de idade, compareceu a uma Unidade Básica de\nSaúde para consulta de rotina anual. Mãe\nrefere que criança vem apresentando roncos noturnos,\nsono agitado e episódios de pausa respiratória. Ela informa que o filho é agitado, desatento e\ndorme em sala de aula. Antecedente pessoal: rinite controlada com higiene nasal e profilaxia\nambiental. Exame físico: hipertrofia de amígdalas grau III, hipertrofia de cornetos nasais e\nrespiração oral. O diagnóstico e a conduta são, respectivamente:","options":{"A":"Transtorno, déficit de atenção e hiperatividade e cloridrato de metilfenidato.","B":"Refluxo gastroesofágico e pHmetria.","C":"Síndrome da apnéia obstrutiva do sono e polissonografia.","D":"Hipertrofia de adenoides e radiograma de cavum."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-343842","number":"343842","sourceNumber":"343842","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Senhora de 62 anos, 60 kg de peso corporal, hipertensa em uso de losartana 50 mg/dia\n\n+ hidroclorotiazida 25 mg/dia, chega a unidade de Pronto Socorro encaminhada por colega para\navaliação de emergência devido exame laboratorial de rotina (Sódio sérico de 122 mEq/L; VR: 135 -\n145 mEq/l), sem outras queixas. Qual a sua conduta para o caso?","options":{"A":"SF 3% - 30 ml/hora EV nas primeiras 3 horas e solicitar novo Sódio sérico.","B":"SF 3% - 60 ml/hora EV nas primeiras 3 horas e solicitar novo Sódio sérico.","C":"Suspender hidroclorotiazida, orientar restrição de líquidos, furosemida via oral e repetir sódio\nsérico ambulatorialmente.","D":"Hidratar com SF 0,9% e reavaliar sódio sérico ambulatorialmente."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-343851","number":"343851","sourceNumber":"343851","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual dos pacientes abaixo apresenta uma emergência hipertensiva?","options":{"A":"Senhora de 65 anos, obesa, hipertensa e diabética há 20 anos, vai visitar a mãe na UTI e fica\nmuito emocionada, apresenta tontura e é levada ao PS, onde se constata PA=210x120 mmHg; o\nrestante do exame físico com exceção da obesidade é normal.","B":"Jovem de 12 anos refere que há 15 dias teve impetigo, ontem acordou com as pálpebras\nedemaciadas e hoje não conseguiu praticar educação física por dispnéia. Ao exame físico\nobservaram-se PA=160x100 mmHg, pulmões livres, fundo de olho normal.","C":"Senhor de 72 anos, revascularizado do miocárdio há dois anos, refere dor retroestemal há 3\nhoras. Seu exame físico revela PA=210x130\nmmHg e o pulso: diminuídos em membros superiores\ne não palpáveis em membros inferiores.","D":"Senhora de 48 anos, portadora de estenose aórtica devido ao cardite reumática, refere tontura\nrotatória e vômitos desde hoje cedo, PA=180x105 mmHg."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-283286","number":"283286","sourceNumber":"283286","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Mulher de 60 anos de idade, hipertensa, diabética e dislipidêmica em acompanhamento\nambulatorial em uso de metformina 850 mg\n2x ao dia, sinvastatina 20 mg/dia, AAS 100 mg/dia,\nlosartana 50 mg/dia, hidroclorotiazida 25 mg/dia e anlodipino 5 mg/dia. Refere que tem apresentado\nedema em membros inferiores e crise recorrente de gota. Quais medicamentos seriam\nresponsáveis respectivamente pelo edema e pela gota?","options":{"A":"Sinvastatina e losartana.","B":"Losartana e metformina.","C":"Anlodipino e hidroclorotiazida.","D":"Anlodipino e losartana."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-251858","number":"251858","sourceNumber":"251858","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale o efeito colateral mais comumente encontrado com o uso de inibidores da\nECA:","options":{"A":"Hipotensão arterial.","B":"Hiperpotassemia.","C":"Tosse.","D":"Disfunção renal."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-247145","number":"247145","sourceNumber":"247145","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual o elemento fisiopatológico mais importante na síndrome cardio-renal em pacientes\ncom insuficiência cardíaca aguda descompensada?","options":{"A":"Síndrome de baixo débito cardíaco e perfusão renal ruim.","B":"Hipertensão venosa sistêmica com elevação de pressão venosa central.","C":"Insuficiência renal iatrogênica (medicamentos nefrotóxicos).","D":"Hipertensão arterial sistêmica não controlada.","E":"Piora de doença renal pré-existente (doença renovascular)."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-247147","number":"247147","sourceNumber":"247147","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O principal mecanismo que leva à perda de função renal na hipertensão arterial é:","options":{"A":"Hiperfiltração glomerular.","B":"Hipertensão glomerular.","C":"Isquemia.","D":"Fibrose intersticial.","E":"Esclerose glomerular."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-247184","number":"247184","sourceNumber":"247184","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Menino de 12 anos de idade é trazido ao pronto-socorro com história de falta de ar há\n48 horas, cefaleia e desmaio. Ao exame,\nencontra-se ansioso, dispneico, pletórico, com estase\nvenosa central. O paciente se recusa a deitar para o exame abdominal, a ausculta pulmonar é\nlimpa. Qual diagnóstico mais provável?","options":{"A":"Hipertensão intracraniana.","B":"Síndrome do mediastino superior.","C":"Ataque de pânico.","D":"Síndrome de lise tumoral.","E":"Crise de asma."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-217656","number":"217656","sourceNumber":"217656","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Com relação aos hipotensores, assinale a alternativa CORRETA:","options":{"A":"Há contraindicação relativa ao uso de alfabloqueadores em hipertensos com hipertrofia\nprostática benigna.","B":"Os inibidores diretos da renina causam redução da produção de angiotensina II e há fortes\nevidências de seus benefícios sobre a morbimortalidade.","C":"Os bloqueadores dos receptores AT1 da angiotensina II proporcionam redução da\nmorbimortalidade cardiovascular, mas não da renal.","D":"Os bloqueadores dos canais de cálcio não di-hidropiridínicos podem deprimir a função sistólica\ncardíaca, principalmente em pacientes que já apresentam tal disfunção antes do início do seu uso,\ndevendo ser evitados nessa condição."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-182602","number":"182602","sourceNumber":"182602","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Segundo a VII Diretriz Brasileira de Hipertensão Arterial - HAS (2016), a classificação\nda HAS em medição casual ou no consultório em\num paciente acima de 18 anos de idade com\nníveis tensionais de 140 X 95 mmHg, estaria classificado como:","options":{"A":"Pré hipertensão.","B":"HAS estágio 1.","C":"HAS estágio 2.","D":"HAS estágio 3."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-182624","number":"182624","sourceNumber":"182624","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente com Insuficiência Cardíaca que resulta em ligeira limitação da atividade física.\nEle fica confortável em repouso. A\natividade física ordinária resulta em fadiga, palpitações, dispneia\nou dor anginosa. Esse paciente deve ser classificado funcionalmente conforme a New York Heart\nAssociation (NYHA) em:","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183198","number":"183198","sourceNumber":"183198","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Mulher de 76 anos, hipertensa de longa data, referindo piora de dispneia, atualmente,\naté aos pequenos esforços. Apresenta ausculta\ncom galope de B4. A pressão arterial é de 160/88\nmm Hg e a FC= 96/min. Ao ecocardiograma são observados hipertrofia concêntrica do VE, átrio\nesquerdo pouco aumentado, tamanho e função ventricular esquerda normais e tempo de\nrelaxamento diastólico anormalmente lento. Qual destas drogas seria mais eficaz e com menor\nperfil de toxicidade?","options":{"A":"Digoxina,","B":"Lisinopril.","C":"Verapamil.","D":"Amlodipina.","E":"Metolazona."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-159089","number":"159089","sourceNumber":"159089","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O manejo do paciente hipertenso é de grande importância na prática clínica diária, por\nisso os conhecimentos sobre os fármacos\nutilizados para o tratamento da hipertensão arterial\nsistêmica e seus riscos são pré-requisitos básicos para o seu emprego adequado e responsável\npelo médico que irá atuar nas unidades básicas de saúde. Tendo em vista o exposto acima,\nrelacione as colunas, associando os efeitos adversos aos respectivos fármacos. (1)\nHidroclorotiazida; (2) Propranolol; (3) Anlodipino; (4) Captopril. ( ) Tosse e hipercalemia; ( )\nBroncoespasmo, insuficiência circulatória periférica, bradiarritmias e mascaramento de hipoglicemia\nem diabéticos; ( ) Hipocalemia e hiperuricemia; ( ) Cefaleia, edema periférico e palpitação. A ordem\nnumérica CORRETA, na coluna inferior, de cima para baixo é:","options":{"A":"2 - 3 - 4 - 1.","B":"2 - 4 - 1 - 3.","C":"4 - 2 - 1 - 3.","D":"4 - 1 - 3 - 2."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-159119","number":"159119","sourceNumber":"159119","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Com relação aos diuréticos usados na insuficiência cardiaca, pode-se afirmar que a:","options":{"A":"Clortalidona reduz o sódio e potássio urinários.","B":"Furosemida pode causar alcalose hipoclorêmica.","C":"Amilorida reduz a concentração sérica de magnésio.","D":"Hidroclorotiazida não interfere no nível sérico de glicose."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-159122","number":"159122","sourceNumber":"159122","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Sobre as urgências hipertensivas e complicações na hipertensão arterial, pode-se\nafirmar que: I - A causa da morte mais\nfrequente em hipertensos não tratados é o infarto agudo do\nmiocárdio. II - O metoprolol é o agente anti-hipertensivo parenteral mais indicado na maioria das\nemergências hipertensivas. III - No evento isquêmico agudo cerebral, não se deve administrar\n\nanti-hipertensivos, a não ser em condições específicas ou níveis de pressão extremamente\nelevados (PAS > 220mmHg ou PAD > 120 mmHg).","options":{"A":"Apenas a I está correta.","B":"Apenas a II está correta.","C":"Apenas a III está correta.","D":"I e III estão corretas."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-159125","number":"159125","sourceNumber":"159125","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Na terapêutica das emergências hipertensivas, pode se afirmar que:","options":{"A":"O captopril sublingual é a opção terapêutica para o tratamento ambulatorial.","B":"O nitroprussiato de sódio deve ser utilizado em pacientes com suspeita de isquemia miocárdica\npara a rápida redução do consumo de oxigênio.","C":"A furosemida está indicada no tratamento da eclâmpsia para controle de volemia.","D":"O betabloqueador venoso está indicado na suspeita de dissecção aórtica em conjunto com o\nnitroprussiato de sódio."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-108801","number":"108801","sourceNumber":"108801","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para um médico de família é fundamental ter conhecimento sobre abordagem da\nhipertensão arterial sistêmica em seus pacientes. Sobre este assunto é CORRETO afirmar que:","options":{"A":"A medicação de primeira escolha é o atenolol 25 mg/dia.","B":"Pacientes com nível pressórico controlado necessitam realizar consultas anuais.","C":"O uso de ácido acetilsalicílico associado é recomendado como terapia auxiliar nos pacientes\nhipertensos.","D":"Mudança do estilo de vida como tratamento inicial pode ser recomendado para alguns pacientes."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-84507","number":"84507","sourceNumber":"84507","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale a opção correta, em se tratando de exames de rotina MÍNIMA para pacientes\nportadores de hipertensão arterial.","options":{"A":"Hemograma, sódio, potássio, ureia, urocultura;","B":"Glicemia, Na, K, ECG de esforço;","C":"Hemograma, EPF, urina I, Ureia;","D":"Urina parcial, creatinina, Potássio, glicemia, colesterol e frações, ECG de repouso;","E":"Glicemia, fosfatase alcalina, K, Na."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-84549","number":"84549","sourceNumber":"84549","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual a alternativa não faz parte das indicações para o uso da espironolactona em\npacientes com Insuficiência Cardíaca segundo o último consenso (2013) da Academia Americana\ndo Coração?","options":{"A":"Pacientes com classe funcional II (NYHA) e Fração de ejeção < 30%.","B":"Pacientes com classe funcional III/IV (NYHA) e Fração de ejeção < 35%.","C":"Pacientes com Infarto Miocárdico com supra de ST e tenham recebido terapia com inibidores da\nECA, com fração de ejeção \"< ou =\" 40% e permaneça sintomático.","D":"Para pacientes que preencham os critérios e tenham níveis de potássio < 5 mEq/L e TFG > 30\nml/min por 1,73 m².","E":"Para os pacientes com Classe funcional III (NYHA) independente da Fração de ejeção."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-84493","number":"84493","sourceNumber":"84493","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Indivíduo do sexo masculino, 29 anos, estressado no trabalho e sedentário, com avó\nhipertensa, apresenta-se com IMC de 26,3 kg/m2 e PA de 138/84 mmHg (média de duas medidas).\nQual a melhor orientação do caso?","options":{"A":"A PA é normal e não necessita nenhuma orientação específica.","B":"A PA é normal e está recomendado o acompanhamento nutricional com vistas à redução do sal.","C":"A PA é normal alta e a ênfase deve ser perda de peso, iniciar atividade física e redução do sal.","D":"A PA é normal alta e deve ser prescrito fármaco anti-hipertensivo devido à história familiar\npositiva para hipertensão.","E":"A PA é alta e deve ser iniciado fármacos logo de início."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-84505","number":"84505","sourceNumber":"84505","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 65 anos admitido com história de ser portador de hipertensão arterial\nfazendo uso de hidroclorotiazida e losartana,\né admitido no pronto-socorro apresentando depressão\ndo segmento ST, achatamento das ondas T e ondas U proeminentes. Qual o distúrbio\nhidroeletrolítico mais provável:","options":{"A":"Hipocalcemia.","B":"Hiponatremia.","C":"Hipocalemia.","D":"Hipomagnesemia.","E":"Hipercalemia."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-66967","number":"66967","sourceNumber":"66967","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para pacientes hipertensos em estágio 2 (pressão arterial sistólica \"maior ou igual a\"\n160 mmHg e pressão arterial diastólica \"maior\nou igual a\" 100 mmHg), pode-se considerar o uso de\nassociações de fármacos anti-hipertensivos como terapia inicial. Ao usar diuréticos tiazídicos\nassociados a betabloqueador, os riscos mais importantes são:","options":{"A":"Hipocalemia e tosse.","B":"Hipovolemia e tosse.","C":"Hipocalemia e broncoespasmo.","D":"Hipercalemia e hiperuricemia."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-50109","number":"50109","sourceNumber":"50109","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Sua paciente é uma mulher assintomática de 26 anos, que você está examinando pela\nprimeira vez. Você observa tortuosidade arteriovenosa no exame oftalmoscópico e a PA é de\n220/132 mmHg. Ela é hospitalizada para uma avaliação mais profunda, que inclui arteriografia\nrenal, tendo em vista que você também detectou:","options":{"A":"História familiar de hipertensão arterial;","B":"Quatro a cinco leucócitos por campo de grande aumento no EAS;","C":"Que ela não está usando anticoncepcionais orais;","D":"Um discreto sopro na região subcostal esquerda, que apresenta componentes sistólicos e\ndiastólicos curtos."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-50118","number":"50118","sourceNumber":"50118","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Senhor de 52 anos, hipertenso em uso de captopril 75 mg/dia, hidroclorotiazida 25\nmg/dia, dislipidemia em uso de atorvastatina 20 mg/dia, esteatose hepática detectada no último\nultrassom. Ao exame físico apresenta: IMC - 37 kg/m², PA - 125 x 85 mmHg, FC - 80 bpm, Pele -\nAcantose nigricans em cotovelos. Exames recentes - Glicemia jejum - 128 mg/dl, Hemoglobina\nglicada - 7,6, Colesterol Total - 208, HDL c - 38 mg/dl, Triglicerídeos - 200. Responda a questão\ncom base no caso clínico. Quais os diagnósticos do CASO CLÍNICO?","options":{"A":"HAS, Dislipidemia, Esteatose hepática, Obesidade grau I, Diabetes Mellitus e Síndrome\nmetabólica;","B":"HAS, Dislipidemia, Esteatose hepática, Obesidade grau II, Intolerância à Glicose e Síndrome\nmetabólica;","C":"HAS, Dislipidemia, Esteatose hepática, Obesidade grau II, Diabetes Mellitus e Síndrome\nmetabólica;","D":"HAS, Dislipidemia, Estatose hepática, Obesidade grau I, Intolerância à Glicose e Síndrome\nmetabólica;"},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-50120","number":"50120","sourceNumber":"50120","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Senhor de 52 anos, hipertenso em uso de captopril 75 mg/dia, hidroclorotiazida 25\nmg/dia, dislipidemia em uso de atorvastatina 20\nmg/dia, esteatose hepática detectada no último\nultrassom. Ao exame físico, apresenta: IMC - 37 kg/m², PA - 125 x 85 mmHg, FC - 80 bpm, Pele -\nAcantose nigricans em cotovelos. Exames recentes - Glicemia jejum - 128 mg/dl, Hemoglobina\nglicada - 7,6, Colesterol Total - 208, HDL c - 38 mg/dl, Triglicerídeos - 200. Responda a questão\ncom base no caso clínico. Levando em consideração o CASO CLÍNICO e com base na\nfisiopatologia do Diabetes m=Mellitus, a classe de medicamento (s) que você escolherá deverá agir:","options":{"A":"Diminuindo a neoglicogênese hepática, aumentando a sensibilidade dos receptores periféricos à\ninsulina (fígado).","B":"Aumentando a produção de insulina pelas células beta do pâncreas.","C":"Diminuindo a secreção do Glucagon pelo pâncreas.","D":"Retardando a absorção de carboidratos pelo trato gastrointestinal."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-50123","number":"50123","sourceNumber":"50123","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente portador de Insuficiência Cardíaca (IC) estágio B pela classificação da\nAmerican Heart Association (AHA) deverá apresentar:","options":{"A":"Alto risco para IC sem cardiopatia estrutural ou sintomas de IC;","B":"Cardiopatia estrutural, mas sem sinal ou sintomas de IC;","C":"Cardiopatia estrutural com sintomas prévios ou atuais de IC;","D":"IC refratária exigindo intervenções especializadas;"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-50094","number":"50094","sourceNumber":"50094","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quais os sinais de insuficiência cardíaca mais frequentes na faixa etária pediátrica?","options":{"A":"Hepatomegalia, taquipneia, taquicardia, oligúria.","B":"Hepatomegalia, taquipneia, taquicardia, hipotensão.","C":"Hepatomegalia, taquipneia, taquicardia, cardiomegalia.","D":"Anasarca, edema agudo de pulmão, irritabilidade, enchimento capilar lentificado."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-37073","number":"37073","sourceNumber":"37073","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual dos pacientes abaixo apresenta uma emergência hipertensiva?","options":{"A":"Senhora de 65 anos, obesa, hipertensa e diabética há 20 anos, vai visitar a mãe na UTI e fica\nmuito emocionada, apresenta tontura e é levada ao\nOS, onde se constata PA = 210 X 120 mmHg; o\nrestante do exame físico com exceção da obesidade é normal.","B":"Jovem de 12 anos refere que há 15 dias teve impetigo; ontem acordou com as pálpebras\nedemaciadas e hoje não conseguiu praticar educação física por dispneia. Ao exame físico\nobservaram-se PA = 160 X 100 mmHg, pulmões livres, fundo de olho normal.","C":"Senhor de 72 anos, revascularizado do miocárdio há dois anos, refere dor retroestemal há 3\nhoras. Seu exame físico revela PA = 210 X 130 mmHg e os pulsos: diminuídos em membros\nsuperiores e não palpáveis em membros inferiores.","D":"Moça lúpica de 22 anos, há uma semana fez todos os exames para avaliação de atividade da\ndoença que foram normais; hoje refere\ncefaleia e PA = 180 X 105 mmHg.","E":"Senhora de 48 anos, portadora de estenose aórtica devido a cardite reumática, refere tontura\nrotatória e vômitos desde hoje cedo, PA = 180 x 105 mmHg."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-37087","number":"37087","sourceNumber":"37087","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente com Hipertensão Arterial Sistêmica acelerada apresenta ao exame de fundo\nde olho:","options":{"A":"Exudatos e papiledema","B":"Hemorragia retiniana e papiledema","C":"Dano Vascular sem papiledema","D":"Cruzamentos artério-venoso e papiledema","E":"Espasmo arteriolar e papiledema"},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-37105","number":"37105","sourceNumber":"37105","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação ao sopro cardíaco na criança, é CORRETO afirmar:","options":{"A":"O sopro inocente é a alteração da ausculta que ocorre na ausência de anormalidade anatômica\nou funcional ao sistema cardiovascular.","B":"O sopro inocente é um achado frequente, que ocorre em 50 a 70% das crianças, geralmente na\nidade escolar.","C":"A classificação do sopro quanto à intensidade é estadiado em graus de I a VI.","D":"A presença de frêmito (palpável) sempre caracterizará um sopro como patológico.","E":"Todas as alternativas estão corretas."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-37107","number":"37107","sourceNumber":"37107","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação à insuficiência cardíaca na criança é correto afirmar, exceto:","options":{"A":"É um evento clínico, bem estudado, sendo caracterizado por um estado de hipoperfusão tissular.","B":"Sempre é acompanhada de edema.","C":"Caracteriza-se por cardiomegalia, hepatomegalia, taquipneia e taquicardia.","D":"Pode ser classificada de alto e de baixo débito.","E":"Nenhuma das alternativas."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-29354","number":"29354","sourceNumber":"29354","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale a alternativa correta:","options":{"A":"A Insuficiência Cardíaca Congestiva (ICC) é a condição na qual o débito cardíaco é inadequado\npara as necessidades metabólicas do organismo.","B":"A ICC no lactente é caracterizada por taquicardia, cardiomegalia, taquipneia e hepatomegalia.","C":"A descarga simpática (em reposta à hipotensão, à hipoperfusão e a diminuição da oferta de 02)\ne a estimulação de mecanorreceptores\natriais e ventriculares desencadeiam um aumento de\ncatecolaminas, como adrenalina e noradrenalina as quais, por sua vez, estimulam barorreceptores\ncardíacos, aumentando a frequência cardíaca e a contratilidade miocárdica.","D":"Todas as alternativas estão corretas.","E":"Todas as alternativas estão incorretas."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-29340","number":"29340","sourceNumber":"29340","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Todas as situações clínicas abaixo são indícios de hipertensão arterial secudária,\nexceto:","options":{"A":"Sintomas de apneia durante o sono.","B":"Exame de urina anormal (proteinúria ou hematúria)","C":"Hipopotassemia espontânea","D":"Presença de sopro abdominal","E":"presença de síndrome metabólica associada"},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-343162","number":"343162","sourceNumber":"343162","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os inibidores da proteína co-transportadora SGLT2 (ISGLT2) inaugurou uma nova era\nno tratamento da insuficiência cardíaca IC em\npessoas com diabetes.","options":{"A":"Além de controlar efetivamente a glicemia, esses fármacos apresentam efeito importante na\nfisiopatologia da IC, reduzindo de forma expressiva as internações por insuficiência cardíaca e a\nmortalidade cardiovascular.","B":"Além de não controlar efetivamente a glicemia, esses fármacos apresentam efeito importante na\nfisiopatologia da IC, reduzindo de forma expressiva as internações por insuficiência cardíaca e a\nmortalidade cardiovascular.","C":"Além de controlar efetivamente a glicemia, esses fármacos apresentam efeito importante na\nfisiopatologia da IC, aumentando de forma expressiva as internações por insuficiência cardíaca e a\nmortalidade cardiovascular.","D":"Além de controlar efetivamente a glicemia, esses fármacos apresentam efeito importante na\nfisiopatologia da IC, reduzindo de forma expressiva as internações por insuficiência cardíaca e a\nnão a mortalidade cardiovascular."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-343163","number":"343163","sourceNumber":"343163","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A oclusão de artéria retiniana:","options":{"A":"Não é um marcador de lesão de pequenos vasos e tem sido associada a maior risco de evento\ncerebral.","B":"É um marcador de lesão de pequenos vasos e tem sido associada a maior risco de evento\ncerebral.","C":"É um marcador de lesão de pequenos vasos e tem sido associada a menor risco de evento\ncerebral.","D":"É um marcador de lesão de pequenos vasos e não tem sido associada a maior risco de evento\ncerebral."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-313427","number":"313427","sourceNumber":"313427","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os IECA e outros bloqueadores do Sistema Renina-Angiotensina-Aldosterona (SRAA),\nestão de acordo com o seguinte item\ncorreto:","options":{"A":"Podem provocar hipopotassemia em pacientes com insuficiência renal, sobretudo nos diabéticos\ne, o uso é contraindicado na gravidez, pelo\nrisco de complicações fetais. Por isso, seu emprego\ndeve ser cauteloso e frequentemente monitorado em adolescentes e mulheres em idade fértil.","B":"Podem provocar hiperpotassemia em pacientes com insuficiência renal, sobretudo nos\ndiabéticos e, o uso é indicado na gravidez\nfrequentemente monitorado em mulheres em idade fértil.","C":"Podem provocar hiperpotassemia em pacientes com insuficiência renal, exceto nos diabéticos e,\no uso é contraindicado na gravidez, pelo risco de complicações fetais. Por isso, seu emprego deve\nser cauteloso e frequentemente monitorado em adolescentes e mulheres em idade fértil.","D":"Podem provocar hiperpotassemia em pacientes com insuficiência renal, sobretudo nos\ndiabéticos e, o uso é contraindicado na\ngravidez, pelo risco de complicações fetais. Por isso, seu\nemprego deve ser cauteloso e frequentemente monitorado em adolescentes e mulheres em idade\nfértil."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-313429","number":"313429","sourceNumber":"313429","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Bloqueadores dos Receptores AT1 da Angiotensina II (BRA), estão de acordo com o\nseguinte item correto:","options":{"A":"Antagonizam a ação da Angiotensina II pelo bloqueio inespecífico dos Receptores AT1,\nresponsáveis pelas ações próprias da Angiotensina I (vasoconstrição, estímulo da proliferação\ncelular e da liberação de aldosterona).","B":"Antagonizam a ação da Angiotensina II pelo bloqueio específico dos Receptores AT1,\nresponsáveis pelas ações próprias da\nAngiotensina II (vasoconstrição, estímulo da proliferação\ncelular e da liberação de aldosterona).","C":"Aumentam a ação da Angiotensina II pelo bloqueio específico dos Receptores AT1,\nresponsáveis pelas ações próprias da Angiotensina\nII (vasoconstrição, estímulo da proliferação\ncelular e da liberação de aldosterona).","D":"Antagonizam a ação da Angiotensina II, mas não pelo bloqueio específico dos Receptores AT1,\nresponsáveis pelas ações próprias da Angiotensina II (vasoconstrição, estímulo da proliferação\ncelular e da liberação de aldosterona)."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-313431","number":"313431","sourceNumber":"313431","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale a alternativa correta de acordo com os Efeitos Adversos dos Bloqueadores de\nCanal de Cálcio:","options":{"A":"O edema maleolar costuma ser o efeito colateral mais registrado e resulta da própria ação\nvasodilatadora (mais arterial que venosa), promovendo a transudação capilar.","B":"O edema maleolar costuma ser o efeito colateral mais raro e resulta da própria ação\nvasodilatadora (mais arterial que venosa), promovendo a transudação capilar.","C":"O edema maleolar costuma ser o efeito colateral mais registrado e resulta da própria ação\nvasoconstrictora (mais arterial que venosa), promovendo a transudação capilar.","D":"O edema maleolar costuma ser o efeito colateral mais registrado e resulta da própria ação\nvasodilatadora (mais arterial que venosa), inibindo a transudação capilar."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-313434","number":"313434","sourceNumber":"313434","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A cefaleia latejante e as tonturas são comuns Bloqueadores de Canal de Cálcio BCC,\nsendo correta a alternativa:","options":{"A":"O rubor facial é mais raro com os BCC di-hidropiridínicos de ação rápida. A hipercromia do terço\ndistal das pernas (dermatite ocre) e a hipertrofia gengival são efeitos adversos ocasionais.","B":"O rubor facial é mais comum com os BCC di-hidropiridínicos de ação lenta. A hipercromia do\nterço distal das pernas (dermatite ocre) e a hipertrofia gengival são efeitos adversos ocasionais.","C":"O rubor facial é mais comum com os BCC di-hidropiridínicos de ação rápida. A hipercromia do\nterço distal das pernas (dermatite ocre) e a hipertrofia gengival são efeitos adversos ocasionais.","D":"O rubor facial é mais comum com os BCC não di-hidropiridínicos de ação rápida. A hipercromia\ndo terço distal das pernas (dermatite ocre) e\na hipertrofia gengival são efeitos adversos ocasionais."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-314209","number":"314209","sourceNumber":"314209","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Sabemos que a emergência hipertensiva caracteriza-se por descompensação rápida de\nfunções vitais causada por grande elevação da PA em presença de lesão evidente e recente de\nórgão-alvo. Assinale a alternativa que apresenta a droga de escolha nessa situação.","options":{"A":"Hidralazina.","B":"Nitroprussiato de sódio.","C":"Nifedipino.","D":"Enalapril."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-278073","number":"278073","sourceNumber":"278073","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação as situações que podem levar ao falso diagnóstico de Hipertensão Arterial\nResistente (HAR), acarretando a realização de exames e o uso de medicação de modo\ndesnecessário. Indique a alternativa correta.","options":{"A":"É possível referir-se à hipertensão do avental branco como uma causa de hipertensão arterial\npseudorresistente.","B":"É impossível referir-se à hipertensão do avental branco como uma causa de hipertensão arterial\npseudorresistente.","C":"É possível referir-se à hipertensão do avental branco como uma causa de hipertensão arterial\nresistente.","D":"É possível referir-se à hipertensão do avental branco como uma causa de hipotensão arterial\npseudorresistente."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-280393","number":"280393","sourceNumber":"280393","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma vez afastada a pseudorresistência, confirma-se a existência da HAR e inicia-se\numa investigação diagnóstica com exames\nespecíficos, conforme a orientação das Diretrizes de\nHipertensão em relação ao comprometimento de lesões em órgãos-alvo e hipertensão secundária.\nSendo correto que:","options":{"A":"A ocorrência de comorbidades associadas não deve ser detectada com exames especializados\nde acordo com a suspeita clínica.","B":"A ocorrência de comorbidades associadas nunca deve ser detectada com exames de acordo\ncom a suspeita clínica.","C":"A ocorrência de comorbidades associadas deve ser detectada com exames especializados de\nacordo com a suspeita clínica.","D":"A ocorrência de comorbidades associadas deve ser detectada com exames especializados,\nmesmo sem qualquer suspeita clínica."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-275968","number":"275968","sourceNumber":"275968","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"De acordo com as Diretrizes Brasileira de Hipertensão 2020, pode-se afirmar que:","options":{"A":"A hipertensão se caracteriza por níveis pressóricos iguais ou maiores que 130/90 mmHg.","B":"Uma das principais causas secundárias de hipertensão é a estenose da artéria renal.","C":"Indivíduos com níveis pressóricos de 120-129 mmHg e/ou diastólica de 80-89mmHg são\nconsiderados pré-hipertensos.","D":"No tratamento a prioridade é medicar o paciente ficando a orientação quanto as modificações do\nestilo de vida como auxiliar secundário ao tratamento medicamentoso.","E":"Nenhuma das alternativas anteriores."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-280394","number":"280394","sourceNumber":"280394","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No paciente com Estenose Mitral (EM) não importante, reavaliações podem ser\nrealizadas a cada 1 ano. Sendo correto que:","options":{"A":"O acompanhamento clínico do paciente, enquanto apresentar valvopatia Mitral anatomicamente\nnão importante é realizado com consultas e\nreavaliações ecocardiográficas periódicas.","B":"O acompanhamento clínico do paciente, enquanto apresentar valvopatia Mitral anatomicamente\nimportante é realizado com consultas e\nreavaliações ecocardiográficas periódicas.","C":"O acompanhamento clínico do paciente, enquanto apresentar valvopatia Mitral anatomicamente\nnão importante, não é realizado com consultas e\nreavaliações ecocardiográficas periódicas.","D":"O acompanhamento clínico do paciente, enquanto apresentar valvopatia Mitral anatomicamente\nnão importante é realizado com consultas e não com\nreavaliações ecocardiográficas periódicas."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-278075","number":"278075","sourceNumber":"278075","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A Hipertensão Arterial Resistente (HAR) é definida quando a pressão arterial (PA)\napresenta as seguintes características:","options":{"A":"Permanece abaixo das metas recomendadas com o uso de três anti-hipertensivos de diferentes\nclasses.","B":"Permanece acima das metas recomendadas com o uso de três anti-hipertensivos de diferentes\nclasses.","C":"Permanece acima das metas recomendadas com o uso de dois anti-hipertensivos de diferentes\nclasses.","D":"Permanece acima das metas recomendadas com o uso de três anti-hipertensivos de classes\niguais."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-280396","number":"280396","sourceNumber":"280396","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O correto momento de indicação e o tipo de tratamento intervencionista para pacientes\nportadores de valvopatia cardíaca estão atrelados ao preciso diagnóstico anatômico e funcional da\nvalvopatia cardíaca e a uma minuciosa avaliação global do paciente. Sendo adequado o item:","options":{"A":"A avaliação clínica individual e a nunca decisão da intervenção devem ser sempre\ncompartilhadas com paciente e familiares.","B":"A avaliação clínica individual e a decisão da intervenção devem ser sempre compartilhadas com\npaciente e familiares.","C":"A avaliação clínica individual e a decisão da intervenção devem ser sempre compartilhadas com\npaciente e não com familiares.","D":"A avaliação clínica individual e a decisão da intervenção devem ser sempre compartilhadas\nsomente com os familiares."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-280398","number":"280398","sourceNumber":"280398","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A ecocardiografia é o principal exame complementar para a avaliação anatômica da\nvalva mitral. Sendo assim, assinale a afirmativa correta.","options":{"A":"Sendo fundamental para a definição da gravidade da valvopatia, das repercussões\nhemodinâmicas e não dos parâmetros que estão relacionados à chance de sucesso das\nintervenções.","B":"Não sendo fundamental para a definição da gravidade da valvopatia, das repercussões\nhemodinâmicas e dos parâmetros que estão\nrelacionados à chance de sucesso das intervenções.","C":"Sendo fundamental para a definição da gravidade da valvopatia, das repercussões\nhemodinâmicas e dos parâmetros que não estão relacionados à chance de sucesso das\nintervenções.","D":"Sendo fundamental para a definição da gravidade da valvopatia, das repercussões\nhemodinâmicas e dos parâmetros que estão\nrelacionados à chance de sucesso das intervenções."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-278610","number":"278610","sourceNumber":"278610","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Durante a abordagem da Emergências Hipertensivas (EH), o profissional deverá\nrealizar a diferenciação entre emergência e\nurgência, fazendo o diagnóstico correto das diversas\nsituações de EH, a fim de selecionar a terapia mais adequada para cada Lesão de Órgão Alvo\nLOA.","options":{"A":"Isso é muito importante, pois o diagnóstico e o tratamento corretos podem evitar agravamento do\nquadro clínico decorrente da situação crítica.","B":"Isso é muito importante, pois o diagnóstico e o tratamento corretos não evitam agravamento do\nquadro clínico decorrente da situação crítica.","C":"Isso não é importante, pois o diagnóstico e o tratamento incorretos podem evitar agravamento\ndo quadro clínico decorrente da situação crítica.","D":"Isso é muito importante, pois o diagnóstico e o tratamento incorretos podem evitar agravamento\ndo quadro clínico decorrente da situação\ncrítica."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-278611","number":"278611","sourceNumber":"278611","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A proteína C reativa elevada foi preditoras independente de doença coronariana e\ncerebrovascular, podemos indicar como correto que:","options":{"A":"Sendo um marcador menos importante para hipertensos resistentes mais jovens, obesos, com\nMAPA não controlado e padrão não dipper\n(descenso noturno ausente ou atenuado).","B":"Sendo um marcador mais importante para hipertensos resistentes mais idosos, obesos, com\nMAPA não controlado e padrão não dipper\n(descenso noturno ausente ou atenuado).","C":"Sendo um marcador mais importante para hipertensos resistentes mais jovens, obesos, com\nMAPA controlado e padrão dipper (descenso noturno\nausente ou atenuado).","D":"Sendo um marcador mais importante para hipertensos resistentes mais jovens, obesos, com\nMAPA não controlado e padrão não dipper\n(descenso noturno ausente ou atenuado)."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-278613","number":"278613","sourceNumber":"278613","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Atualmente, várias opções terapêuticas medicamentosas estão disponíveis para o\ntratamento das Emergências Hipertensivas (EH). O fármaco anti-hipertensivo ideal para uso\nparenteral deve apresentar as seguintes características listadas abaixo, indique a errada.","options":{"A":"capacidade de reverter alterações fisiopatológicas envolvidas.","B":"rápido início de ação.","C":"curva dose-resposta imprevisível.","D":"mínimo ajuste de dosagem."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-280403","number":"280403","sourceNumber":"280403","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Por outro lado, pacientes com Insuficiência Mitral (IM) importante devem prosseguir no\nfluxograma de avaliação específica, buscando-se sintomas secundários à valvopatia e/ou presença\nde complicadores. Sendo adequado o item:","options":{"A":"Os pacientes com IM anatomicamente discreta ou moderada não deverão ser mantidos em\nacompanhamento clínico e ecocardiográfico periódicos, sem indicação de intervenção\n(medicamentosa ou cirúrgica) para interrupção da história natural da doença valvar.","B":"Os pacientes com IM anatomicamente discreta ou moderada deverão ser mantidos em\nacompanhamento clínico e ecocardiográfico periódicos, com indicação de intervenção\n(medicamentosa ou cirúrgica) para interrupção da história natural da doença valvar.","C":"Os pacientes com IM anatomicamente grave deverão ser mantidos em acompanhamento clínico\ne ecocardiográfico periódicos, sem indicação de\nintervenção (medicamentosa ou cirúrgica) para\ninterrupção da história natural da doença valvar.","D":"Os pacientes com IM anatomicamente discreta ou moderada deverão ser mantidos em\nacompanhamento clínico e ecocardiográfico periódicos, sem indicação de intervenção\n(medicamentosa ou cirúrgica) para interrupção da história natural da doença valvar."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-278086","number":"278086","sourceNumber":"278086","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assim, hipertensão arterial resistente não controlada (HAR-NC) é definida como uma\nPA que permanece acima do nível desejado\n(140/90 mmHg), sendo correto o item:","options":{"A":"Apesar do uso não concomitante de quatro ou mais agentes anti-hipertensivos de diferentes\nclasses e um quarto fármaco, que geralmente é\num antagonista do receptor mineralocorticoide ou\num bloqueador simpático central.","B":"Apesar do uso concomitante de quatro ou mais agentes anti-hipertensivos de iguais classes e\num quarto fármaco, que geralmente é um antagonista do receptor mineralocorticoide ou um\nbloqueador simpático central.","C":"Apesar do uso concomitante de quatro ou mais agentes anti-hipertensivos de diferentes classes\ne um quarto fármaco, que geralmente é um\nantagonista do receptor mineralocorticoide ou um\nbloqueador simpático central.","D":"Apesar do uso concomitante de quatro ou mais agentes anti-hipertensivos de diferentes classes\ne um quarto fármaco, que não pode ser um\nantagonista do receptor mineralocorticoide ou um\nbloqueador simpático central."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-279037","number":"279037","sourceNumber":"279037","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para pessoas com Cardiopatia Chagásica em fase inicial, podemos indicar como\ncorreto:","options":{"A":"Apresentam somente alterações no eletrocardiograma (ECG), com fração de ejeção (FE)\nanormal, ausência de insuficiência cardíaca (IC)\ne presença de arritmias graves, tanto o tratamento\nquanto não tratar com benznidazol são alternativas válidas.","B":"Apresentam somente alterações no eletrocardiograma (ECG), com fração de ejeção (FE)\nnormal, ausência de insuficiência cardíaca (IC) e ausência de arritmias graves, somente o\ntratamento com benznidazol é alternativa válida.","C":"Apresentam somente alterações no eletrocardiograma (ECG), com fração de ejeção (FE)\nnormal, ausência de insuficiência cardíaca (IC) e\nausência de arritmias graves, tanto o tratamento\nquanto não tratar com benznidazol são alternativas válidas.","D":"Não apresentam alterações no eletrocardiograma (ECG), com fração de ejeção (FE) normal,\nausência de insuficiência cardíaca (IC) e ausência de arritmias graves, tanto o tratamento quanto\nnão tratar com benznidazol são alternativas válidas."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-278634","number":"278634","sourceNumber":"278634","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quais os fatores mais importantes na fisiopatologia da obstrução da faringe durante o\nsono em crianças com síndrome da apneia\nobstrutiva do sono e doenças neuromusculares ou\nneurológicas?","options":{"A":"Aumento do tecido mole ou diminuição da estrutura óssea circunjacente.","B":"Hipertrofia de tonsilas faríngea e palatinas.","C":"Hipertrofia de tonsilas palatinas e adenoide.","D":"Hipotonia muscular ou redução do controle ventilatório central."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-280464","number":"280464","sourceNumber":"280464","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Médico-Líder no Programa de Reabilitação Cardiovascular coordena as ações médicas,\nsendo correto que possui a seguinte função:","options":{"A":"Executar a avaliação pré-participação, com inclusão de testes de exercício, de modo a subsidiar\na programação inicial das sessões de treinamento da\nReabilitação Cardiovascular - RCV.","B":"Executar a avaliação pré-participação, com inclusão de testes de exercício, de modo a subsidiar\na programação final das sessões de treinamento da\nReabilitação Cardiovascular - RCV.","C":"Executar a avaliação pós-participação, com inclusão de testes de exercício, de modo a subsidiar\na programação inicial das sessões de treinamento da\nReabilitação Cardiovascular - RCV.","D":"Jamais executar a avaliação pré-participação, com inclusão de testes de exercício, de modo a\nsubsidiar a programação inicial das sessões de treinamento da Reabilitação Cardiovascular - RCV."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-249381","number":"249381","sourceNumber":"249381","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Considerando as aplicações da monitorização residencial da pressão arterial, não\npodemos apenas indicar como inadequado que:","options":{"A":"As variações dia a dia da PA podem ser avaliadas.","B":"Variações permitem estabelecer separadamente as medidas do período matinal e do\nentardecer/anoitecer.","C":"A PA matinal não pode estar associada a dano em órgão-alvo como AVE.","D":"A associação de dano em órgão-alvo com a PA durante o entardecer/anoitecer da MRPA pode\nser equivalente à PA durante o sono da MAPA."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-249285","number":"249285","sourceNumber":"249285","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No diabetes, a hipotensão ortostática (HO) ocorre, frequentemente, consiste em\nredução da PA sistólica, de pelo menos 20\nmmHg, ou da PA diastólica, de pelo menos 10 mmHg,\nem 1 a 3 minutos após se assumir posição ortostática. Sendo correto que:","options":{"A":"Consequência de denervação parassimpática vasomotora eferente, reduzindo a vasoconstrição\ndo leito vascular esplâncnico e periférico.","B":"Consequência de denervação simpática vasomotora aferente, reduzindo a vasoconstrição do\nleito vascular esplâncnico e periférico.","C":"Consequência de denervação simpática vasomotora eferente, reduzindo a vasoconstrição do\nleito vascular esplâncnico e periférico.","D":"Consequência de denervação simpática vasomotora eferente, aumentando a vasoconstrição do\nleito vascular esplâncnico e periférico."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-249290","number":"249290","sourceNumber":"249290","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale a alternativa que apresenta alterações cognitivas presentes na criança com\nsíndrome da apneia obstrutiva do sono.","options":{"A":"São achados de exame.","B":"Podem estar presentes desde o ronco primário.","C":"São sempre encaminhadas para psicoterapia.","D":"Devem ser muito valorizadas."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-249210","number":"249210","sourceNumber":"249210","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Marque a alternativa correta sobre a cirurgia de adenotonsilectomia.","options":{"A":"Deve ser sempre indicada na síndrome da apneia obstrutiva do sono independente do grau de\nobstrução e da queixa dos pais.","B":"Tem seus riscos e está contraindicada em obesos e menores de 02 anos.","C":"Pode ser indicada como tratamento da síndrome da apneia obstrutiva do sono na criança, mas\npode não melhorar a apneia.","D":"Deve ser sempre indicada, independentemente da faixa etária ou dos riscos."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215470","number":"215470","sourceNumber":"215470","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Elevação matinal precoce da PA ? calculada pela diferença entre a PAS matinal (média\ndas pressões nas primeiras duas horas após o\ndespertar) e a menor PAS durante o sono (média da\npressão mais baixa e das pressões imediatamente antes e após a mais baixa) ? tem sido associada\na desfechos cardiovasculares. É CORRETO, apenas, que:","options":{"A":"A dificuldade da padronização do cálculo desse parâmetro e a sua baixa reprodutibilidade\nindicam que deve ser usado na prática clínica.","B":"A dificuldade da padronização do cálculo desse parâmetro e a sua baixa reprodutibilidade\nindicam que ele não deve ser usado na prática\nclínica.","C":"A facilidade da padronização do cálculo desse parâmetro e a sua baixa reprodutibilidade indicam\nque ele não deve ser usado na prática clínica.","D":"A dificuldade da padronização do cálculo desse parâmetro e a sua alta reprodutibilidade indicam\nque ele não deve ser usado na prática clínica."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215485","number":"215485","sourceNumber":"215485","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A variabilidade extraída a partir das diferenças de cada medida é denominada\nvariabilidade de curto período (short term variability). Aponte, apenas. a CORRETA.","options":{"A":"Está identificada uma associação positiva entre mortalidade e variabilidade sistólica diurna de\ncurto período. Diante de tais resultados, a redução da variabilidade da PA não têm implicações\nterapêuticas independentemente da redução das médias de PA.","B":"Está identificada uma associação positiva entre mortalidade e variabilidade sistólica diurna de\ncurto período. Diante de tais resultados, a redução da variabilidade da PA poderia ter implicações\nterapêuticas independentemente da redução das médias de PA.","C":"Está identificada uma associação positiva entre mortalidade e variabilidade sistólica diurna de\ncurto período. Diante de tais resultados, a redução da variabilidade da PA poderia ter implicações\nterapêuticas dependentemente da redução das médias de PA.","D":"Está identificada uma associação negativa entre mortalidade e variabilidade sistólica diurna de\ncurto período. Diante de tais resultados, a redução da variabilidade da PA poderia ter implicações\nterapêuticas independentemente da redução das médias de PA."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215494","number":"215494","sourceNumber":"215494","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Suporte ventilatório não invasivo com pressão positiva está indicado em todos os\npacientes com Insuficiência Cardíaca e com\nSatO2 < 90% com esforço respiratório, ou desconforto\nrespiratório, que não apresentaram melhora com oxigenoterapia. Apenas um dos itens abaixo se\nmostra com dados INCORRETOS, aponte-o.","options":{"A":"Nos pacientes com edema agudo de pulmão associados com Infarto Agudo do Miocárdio (IAM),\nhá benefício comprovado para redução da\nmortalidade com o suporte invasivo.","B":"Também está indicado nos pacientes com edema agudo de pulmão, com benefícios\ncomprovados na redução de evolução para suporte ventilatório invasivo.","C":"O suporte respiratório tem como alvos estabelecer Saturação de Oxigênio (SatO2) > 90% e\nredução do trabalho respiratório, tendo\ncomo opções a oxigenoterapia com cateter nasal ou\nmáscara, o suporte ventilatório não invasivo com pressão positiva e o suporte ventilatório invasivo\ncom pressão positiva.","D":"Oxigenoterapia está indicada em todos os pacientes com SatO2 < 90%, com cateter nasal ou\nmáscara, com oxigênio a 100% 3 a 5 L/minuto, sendo que, em pacientes com DPOC, o\nrecomendado é 1 a 2 L/minuto, para evitar a indução de hipercapnia."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215230","number":"215230","sourceNumber":"215230","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No cenário da Insuficiência Cardíaca (IC) avançada, a classificação clínica dos\npacientes, baseada nas classes funcionais\npropostas pela New York Heart Association (NYHA),\nque é funcional e usada para descrever e classificar a gravidade dos sintomas apresenta\nindicações e limitações. Qual dos itens abaixo está INADEQUADO?","options":{"A":"Não mais possibilita adequada seleção dos pacientes que se beneficiarão de\ncardio-desfibriladores implantáveis.","B":"Não mais possibilita adequada seleção dos pacientes que se beneficiarão de ressincronizadores\nventriculares e transplante cardíaco.","C":"Não mais possibilita adequada seleção dos pacientes que se beneficiarão de Dispositivos de\nAssistência Circulatória Mecânica (DACM).","D":"Possibilita adequada seleção dos pacientes que se beneficiarão de terapias medicamentosas."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215503","number":"215503","sourceNumber":"215503","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os opioides aliviam ansiedade e dispneia dos pacientes com edema agudo de pulmão,\nmas o uso rotineiro não é recomendado, devido a riscos de efeitos adversos, como os listados\nabaixo, indique o INADEQUADO.","options":{"A":"Náusea.","B":"Bradicardia e depressão respiratória.","C":"Hipertensão.","D":"Controvérsias a respeito de maior risco de mortalidade com seu uso."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215510","number":"215510","sourceNumber":"215510","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"As cargas de pressões da MAPA expressam a percentagem de medidas acima dos\nvalores de normalidade para as 24 horas, vigília e sono.","options":{"A":"Avaliação prospectiva em estudo populacional indica que esse parâmetro possa modificar a\nestratificação de risco fornecida pelas médias de PA.","B":"Avaliação prospectiva em estudo populacional não indica que esse parâmetro não possa\nmodificar a estratificação de risco não fornecida pelas médias de PA.","C":"Avaliação prospectiva em estudo populacional não indica que esse parâmetro possa modificar a\nestratificação de risco fornecida pelas baixas e não médias de PA.","D":"Avaliação prospectiva em estudo populacional não indica que esse parâmetro possa modificar a\nestratificação de risco fornecida pelas médias de PA."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215517","number":"215517","sourceNumber":"215517","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O edema agudo de pulmão pode ser a apresentação clínica inicial de cerca de\npacientes hospitalizados por Insuficiência Cardíaca (IC), somente NÃO sendo correta uma\nalternativa. Marque-a.","options":{"A":"A crise hipertensiva, a insuficiência mitral aguda (disfunção do músculo papilar secundária à\ndoença isquêmica ou ruptura espontânea) são os\nfatores causais mais comuns de edema agudo de\npulmão cardiogênico.","B":"Síndrome coronariana aguda são os fatores causais mais comuns de edema agudo de pulmão\ncardiogênico.","C":"A apresentação clínica, com hipotensão arterial e sinais de baixo débito cardíaco, é menos\nfrequente e, em geral não observada em pacientes com IC crônica agudizada.","D":"Os pacientes com edema agudo de pulmão apresentam modelos distintos de distribuição\nvolêmica."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-216305","number":"216305","sourceNumber":"216305","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Novas tecnologias ecocardiográficas, como speckle tracking com strain longitudinal\nventricular são mais sensíveis em detectar\ndisfunção miocárdica subclínica do que as medidas da\nfunção sistólica global. Podemos concordar apenas com o item CORRETO:","options":{"A":"A avaliação ecocardiográfica por parâmetros convencionais, como a FEVE, é raramente afetada\npor mudanças contínuas nas condições de\npré-carga e pós-carga.","B":"A avaliação ecocardiográfica por parâmetros convencionais, como a FEVE, é frequentemente\nafetada por mudanças contínuas nas condições de\npré-carga e mas não de pós-carga.","C":"A avaliação ecocardiográfica por parâmetros convencionais, como a FEVE, é frequentemente\nafetada por mudanças contínuas nas condições de\npré-carga e pós-carga.","D":"A avaliação ecocardiográfica por parâmetros convencionais, como a FEVE, é frequentemente\nafetada por mudanças contínuas nas condições\nsomente de pós-carga."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215242","number":"215242","sourceNumber":"215242","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Na abordagem inicial dos pacientes com sinais e sintomas sugestivos de Insuficiência\nCardíaca (IC) crônica ambulatorial,\nrecomenda-se a realização de diversos exames laboratoriais\ncomplementares, estando INADEQUADO que:","options":{"A":"Para avaliar a presença e a gravidade de lesões somente no coração.","B":"Para detectar comorbidades.","C":"Para verificar fatores agravantes do quadro clínico.","D":"A realização de exames seriados pode ser necessária para a monitoração de variáveis de\nsegurança, durante o tratamento da IC, incluindo função renal e eletrólitos."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215525","number":"215525","sourceNumber":"215525","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os pacientes com edema agudo de pulmão apresentam modelos distintos de\ndistribuição volêmica sendo Insuficiência\nCardíaca (IC) aguda nova com congestão pulmonar sem\nhipervolemia periférica (IC de novo). Somente sendo INADEQUADO que:","options":{"A":"Neste modelo hemodinâmico, o tratamento tem como objetivo redistribuir o volume da circulação\npulmonar para a circulação periférica.","B":"A melhoria da distribuição de volume é feita por ação de vasodilatadores com uso judicioso de\ndiuréticos e suporte ventilatório com pressão positiva não invasiva de baixa pressão, para reduzir o\ntrabalho respiratório e a hipoxemia, que podem reduzir as taxas de intubação e de mortalidade.","C":"O uso de ventilação não invasiva é recomendado em pacientes com congestão pulmonar\nassociada a desconforto respiratório e/ou hipoxemia.","D":"É recomendável ter-se cautela com pacientes hipotensos (pressão positiva pode aumentar a\npressão arterial) e em pacientes após IAM, os quais podem ter pior evolução."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215532","number":"215532","sourceNumber":"215532","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Insuficiência Cardíaca (IC) crônica agudizada apresenta o outro modelo de edema\nagudo de pulmão, somente sendo INCORRETO que:","options":{"A":"Apresenta congestão pulmonar, mas não a sistêmica.","B":"O tratamento tem como prioridade a redução da volemia.","C":"Indicação de uso, em larga escala, de diuréticos associados a vasodilatadores e, por vezes,\ninotrópicos.","D":"Em pacientes com sinais de baixo débito com hipotensão arterial, o suporte inotrópico é o\ntratamento de escolha."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215249","number":"215249","sourceNumber":"215249","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A realização de Eletrocardiograma (ECG) de 12 derivações é recomendada na\navaliação inicial de todos os pacientes com\ninsuficiência cardíaca, para avaliar sinais de cardiopatia\nque podem demandar cuidados e tratamentos específicos. Marque a opção INCORRETA.","options":{"A":"Vários destes aspectos são marcadores prognósticos em muitas cardiopatias, como na\nchagásica crônica.","B":"Para avaliar sinais de cardiopatia estrutural como hipertrofia ventricular esquerda, isquemia\nmiocárdica e áreas de fibrose.","C":"A detecção de Bloqueio de Ramo Esquerdo (BRE), com alargamento pronunciado da duração\ndo complexo QRS, não altera a indicação da\nTerapia de Ressincronização Cardíaca (TRC).","D":"Para avaliar distúrbios da condução atrioventricular, bradicardia ou taquiarritmias, que podem\ndemandar cuidados e tratamentos específicos."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215255","number":"215255","sourceNumber":"215255","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A radiografia simples do tórax, por sua simplicidade, rapidez de obtenção e ampla\ndisponibilidade, é recomendada na avaliação inicial dos pacientes com sinais e sintomas de\nInsuficiência Cardíaca. Portanto, é INCORRETO:","options":{"A":"Para a avaliação de cardiomegalia e congestão pulmonar.","B":"Sensibilidade do método é bastante limitada e, ainda, que a disfunção sistólica cardíaca\nsignificativa pode ocorrer somente com cardiomegalia na radiografia de tórax.","C":"O método tem maior valor no contexto da IC aguda, em que as alterações de congestão\npulmonar são mais intensas.","D":"A radiografia de tórax também é útil por sua capacidade de identificar causas pulmonares de\ndispneia, como doença pulmonar intersticial, Doença Pulmonar Obstrutiva Crônica (DPOC),\nneoplasia pulmonar e pneumonia."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215263","number":"215263","sourceNumber":"215263","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O Ecocardiograma Transtorácico Bidimensional com análise dos fluxos pelo método\ndoppler (Eco-2D-Doppler) é o teste diagnóstico por\nimagem preferencial para avaliação inicial dos\npacientes com suspeita de Insuficiência Cardíaca (IC), por sua ampla disponibilidade e por\nprescindir do uso de radiação ionizante. Estando ADEQUADO que:","options":{"A":"Método amplamente abrangente, o ecocardiograma não pode identificar acuradamente a\npresença de alterações estruturais cardíacas.","B":"Pode identificar acuradamente incluindo anormalidade do miocárdio, das válvulas cardíacas e do\npericárdio, sem avaliar aspectos hemodinâmicos.","C":"O ecocardiograma permite a avaliação simultânea de múltiplas variáveis relevantes, do ponto de\nvista clínico, útil para a compreensão das manifestações clínicas.","D":"Auxilia no planejamento terapêutico, mas não na estratificação prognóstica dos pacientes com\nIC."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215284","number":"215284","sourceNumber":"215284","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Indicações de uso do Ecocardiograma Transtorácico como teste diagnóstico por\nimagem preferencial para avaliação inicial dos\npacientes com suspeita de Insuficiência Cardíaca IC,\npor sua ampla disponibilidade e por utilizar radiação ionizante, estando INADEQUADO que:","options":{"A":"Existem inúmeros estudos mostrando que a avaliação da deformação miocárdica pela técnica de\nspeckle tracking adiciona informações ao cenário clínico, constituindo um marcador precoce de\ndisfunção ventricular, antes mesmo da alteração da fração de ejeção.","B":"A estimativa do Global Longitudinal Strain vem sendo testada para a detecção subclínica da\ntoxicidade cardíaca secundária à quimioterapia.","C":"Tendo em vista um grande número de softwares e modalidades diferentes de execução, além da\ntecnologia necessária, a avaliação de deformação miocárdica está indicada na avaliação de rotina\nnos pacientes com IC.","D":"A utilização do ecocardiograma transtorácico ou ultrassom torácico em conjunto com a avaliação\nclínica ajuda de forma significativa a\nestabelecer com maior certeza o modelo\nclínico?hemodinâmico do paciente."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215290","number":"215290","sourceNumber":"215290","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro das recomendações para diagnóstico e tratamento da miocardite por doença de\nChagas aguda ou reativação, devemos entender\nque a miocardite por doença de Chagas deve ser\nsuspeitada nos seguintes cenários. Indique o item que se apresenta ERRADO.","options":{"A":"Insuficiência Cardíaca (IC) de início recente.","B":"Sinais de reativação da infecção pelo Trypanosoma cruzi no contexto de transplante de órgãos\ne/ou uso de imunossupressores, somente com\nsinais de IC.","C":"Sinais de reativação da infecção por T. cruzi no contexto de síndrome da imunodeficiência\nadquirida com ou sem sinais de IC.","D":"Alterações recentes em exames de ECG ou de imagem com ou sem sinais/sintomas de IC em\npaciente com epidemiologia positiva."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215294","number":"215294","sourceNumber":"215294","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os peptídeos natriuréticos, quando disponíveis, devem ser utilizados de rotina na\navaliação diagnóstica admissional na sala de emergência de pacientes com dispneia ou suspeita\nde Insuficiência Cardíaca (IC) aguda, sendo INADEQUADO, apenas, que","options":{"A":"Apresentam alto valor preditivo de IC quando analisados de forma isolada, ou quando\nassociados ao exame clínico e radiológico do tórax.","B":"Em decorrência dos vários fatores clínicos que podem estar associados à elevação dos\npeptídeos natriuréticos, reduzindo sua capacidade preditiva diagnóstica positiva.","C":"Níveis séricos intermediários de BNP entre 100 e 500 pg/mL, ou NT-proBNP entre 300 e 900\npg/mL necessitam da correlação clínica para confirmação do diagnóstico da IC aguda. Por outro\nlado, a presença de níveis elevados de BNP > 500 pg/mL e NT-proBNP > 900 pg/mL indicam\nfortemente diagnóstico de IC aguda.","D":"Os peptídeos natriuréticos apresentam baixa capacidade de afastar o diagnóstico (baixa\nsensibilidade), na presença de níveis séricos de BNP < 100 pg/mL e NT-proBNT < 300 pg/mL."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215300","number":"215300","sourceNumber":"215300","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em situações clínicas de rápida instalação, como edema agudo de pulmão em flush, na\ninsuficiência mitral aguda, ou no cor pulmonale agudo, podemos observar níveis não elevados dos\npeptídeos natriuréticos. Sendo CORRETO que, em pacientes:","options":{"A":"Sem uso do medicamento sacubitril-valsartana, a inibição da neprilisina pelo sacubitril promove\nelevação nos níveis séricos do BNP, mas não do NT-proBNP, interferindo na acurácia diagnóstica\ndo BNP. Nestes pacientes, devemos utilizar o NT-proBNP.","B":"Em uso do medicamento sacubitril-valsartana, a inibição da neprilisina pelo sacubitril, não\npromove elevação nos níveis séricos do BNP, mas\nnão do NT proBNP, interferindo na acurácia\ndiagnóstica do BNP. Nestes pacientes, devemos utilizar o NT-proBNP.","C":"Em uso do medicamento sacubitril-valsartana, a inibição da neprilisina pelo sacubitril promove\nelevação nos níveis séricos do BNP, mas não do NT proBNP, interferindo na acurácia diagnóstica\ndo BNP. Nestes pacientes, devemos utilizar o NT-proBNP.","D":"Em uso do medicamento sacubitril-valsartana, a inibição da neprilisina pelo sacubitril promove\nredução nos níveis séricos do BNP, mas não\ndo NT proBNP, interferindo na acurácia diagnóstica\ndo BNP. Nestes pacientes, devemos utilizar o NT-proBNP."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215555","number":"215555","sourceNumber":"215555","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os pacientes com Hipertensão Arterial Pulmonar - HAP devem ser submetidos à\navaliação clínica periódica com equipe de\nserviço especializado ou de centro de referência\n(pneumologistas, cardiologistas e reumatologistas, em caso de HAP associada a doenças do tecido\nconjuntivo), para consideração dos sinais de insuficiência ventricular direita e síncope, da classe\nfuncional, do teste de caminhada de 6 minutos e de ecocardiografia. Está INCORRETA a\nalternativa:","options":{"A":"A primeira avaliação deve ser realizada 3 meses após o início do tratamento, tendo em vista que\na maioria dos estudos utilizou esse prazo\npara confirmar a resposta ao tratamento medicamentoso.","B":"Para os pacientes que se mantêm em nível estável e satisfatório após início do tratamento,\npreconiza-se manter acompanhamento semestral ou anual em serviço especializado.","C":"Pacientes em nível estável, mas não satisfatório, devem manter acompanhamento trimestral em\nserviço especializado ou centro de referência para otimização terapêutica.","D":"Pacientes em nível instável e deteriorando, apesar do tratamento, não são candidatos a\ntransplante pulmonar, independentemente do início do tratamento; devem ser reavaliados pelo\nmenos trimestralmente em serviço especializado ou em\n\ncentro de referência e mantidos sob acompanhamento simultâneo com as equipes."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215283","number":"215283","sourceNumber":"215283","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Outros exames laboratoriais que devem ser solicitados na admissão são: troponina (na\nsuspeita de doença arterial coronária, miocardite ou Takotsubo), entre outros, somente estando\nINADEQUADO nesse conceito, o item que se apresenta errado. Indique-o.","options":{"A":"O ECG permite suspeitar da etiologia da IC e da causa da descompensação. A presença de um\nECG normal é comum, e praticamente não exclui\ndoença miocárdica crônica.","B":"Na admissão do paciente, é necessária a avaliação por meio do monitor, com confirmação\nposterior pelo ECG de taquiarritmias ou\nbradiarritmias, que demandem intervenção terapêutica\nimediata.","C":"O ecocardiograma deve ser realizado em todos os pacientes dentro das primeiras 48 horas da\nadmissão.","D":"A realização precoce do ecocardiograma apresenta particular importância nos pacientes com\nchoque cardiogênico e IC aguda nova."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-212220","number":"212220","sourceNumber":"212220","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Insuficiência cardíaca é uma síndrome em que o coração não é capaz de ofertar\noxigênio aos tecidos em taxa adequada às\ndemandas ou o faz à custa de elevação de sua pressão\nde enchimento (pré-carga). Geralmente, resulta de disfunção estrutural ou funcional. Assinale a\nalternativa que contempla uma causa de insuficiência cardíaca diastólica.","options":{"A":"Sepse.","B":"Doença de Chagas.","C":"Estenose valvar aórtica.","D":"Síndrome de Takotsubo.","E":"Miocardiopatia periparto."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215478","number":"215478","sourceNumber":"215478","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre o efeito analgésico da medicação alfa-2\nagonista.","options":{"A":"Por via sistêmica, potencializa o efeito analgésico do opioide pela regulação do aumento da\nsubstância P (neuromodulador) no SNC.","B":"Estimula receptores alfa-2 agonistas com redução do estímulo simpático.","C":"Melhor efeito analgésico via epidural, pois atinge maiores concentrações.","D":"Por via oral, potencializa o efeito analgésico do opioide."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-182726","number":"182726","sourceNumber":"182726","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Não podemos determinar como correto o seguinte item referenciando a ecocardiografia\ntranstorácica como método diagnóstico, assim\nindique o item ERRADO dos listados abaixo.","options":{"A":"A ecocardiografia transtorácica é o principal método diagnóstico em pacientes com IC suspeita\nou conhecida.","B":"A ecocardiografia transtorácica por este método, incluindo formas refinadas de análise, como a\ndo strainmiocárdico e a ecocardiografia\ntridimensional, podemos avaliar com pequena precisão os\nvolumes ventriculares, a fração de ejeção, o débito cardíaco.","C":"A ecocardiografia de rotina não é indicada em todo paciente cardiopata em pré-operatório, pois\nainda não há evidências de que seu uso esteja associado ao aumento da sobrevida ou à menor\npermanência hospitalar.","D":"A ecocardiografia transtorácica em uso pré-operatório, pelo contrário, aumenta o tempo de\nhospitalização, sem benefício clínico."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183563","number":"183563","sourceNumber":"183563","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Não pode ser determinado como adequado a pacientes com Insuficiência Cardíaca\nDescompensada ICD na fase avançada, o seguinte item:","options":{"A":"Outro fator importante, presente em pacientes com Insuficiência Cardíaca Descompensada ICD\nna fase avançada, é a elevação de citocinas, com o achado de maiores níveis do fator de necrose\ntumoral, de interleucina-6 e de endotelinas. Estas alterações são responsáveis pela caquexia nos\npacientes graves com ICD.","B":"Em uma fase mais avançada, a maior estimulação neuro-humoral se faz com predomínio dos\nneuro-hormônios com efeito vasoconstritor, estes induzem aumento da resistência periférica e piora\nda função cardíaca, levando o coração para um círculo vicioso de agravamento progressivo.","C":"Nesta fase, drogas que modulem a estimulação neuro-humoral aumentada são aquelas que\ninfluenciam positivamente a evolução da doença.","D":"A fisiopatologia dos pacientes com função sistólica preservada não é diferente da de pacientes\ncom baixa fração de ejeção."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183597","number":"183597","sourceNumber":"183597","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A terapêutica antiviral tem como objetivo promover a eliminação viral como também\nimpedir a sua replicação. Quanto a isso, podemos considerar INCORRETO que:","options":{"A":"Dentre as possibilidades terapêuticas, temos a infusão subcutânea de interferon-ß (IFN- ß) e a\nimunoglobulina intravenosa (IG- IV).","B":"A infusão subcutânea de IFN-ß em pacientes com cardiomiopatia dilatada e persistência viral\n(adenovírus e enterovírus) não demonstrou eliminação viral, mas melhora clínica da capacidade\nfuncional e função ventricular.","C":"Em pacientes com miocardite viral por parvovírus-B19, o IFN-ß esteve associado à redução da\ncarga viral, melhora da função endotelial e da função ventricular.","D":"A terapêutica com IFN-ß em pacientes com miocardite viral está se consolidando como opção\nterapêutica antiviral."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183608","number":"183608","sourceNumber":"183608","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"IC - Insuficiência Cardíaca pode ser classificada de diferentes formas, sendo que ainda\nnão existe uma classificação consensual, havendo vantagens e desvantagens entre as existentes.\nA classificação Clínico/Hemodinâmico, além de nos permitir melhor avaliação diagnóstica e de\ntratamento para todos os tipos de pacientes com ICD, permite também traçar o prognóstico destes\npacientes. Sendo concebido como INADEQUADO que:","options":{"A":"Diferentes formas de apresentação não são facilmente caracterizadas através da abordagem\nclínica direta.","B":"As classificações têm como objetivo estabelecer o tratamento mais correto de acordo com o\nquadro clínico específico de cada paciente no momento do diagnóstico.","C":"Para orientação prática do tratamento da ICD no SAVIC adotamos a Classificação\nClínico/Hemodinâmico, que é a mais atual e é a\nclassificação que procura melhor descrever os\naspectos clínicos da gravidade do paciente desde o momento de chegada na sala de emergência.","D":"Por meio da observação da perfusão periférica do paciente e de seu grau de congestão\npulmonar através da ausculta pulmonar e estase\njugular, ela permite fácil aplicação em todos os\nsetores."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183055","number":"183055","sourceNumber":"183055","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A Cardiomiopatia Hipertrófica (CMH) é a doença cardíaca genética maior causadora de\nmorte súbita em jovens, com uma prevalência\n\nde 1 para cada 500 adultos. Não sendo possível concordar com seguinte item abaixo","options":{"A":"Trata-se de uma doença genética de herança autossômica dominante e atualmente reconhecida\ncomo do sarcômero cardíaco.","B":"Entre os mecanismos fisiopatológicos, estão implicadas mutações nos genes que codificam as\nprincipais proteínas estruturais da\n\narquitetura miocárdica.","C":"A heterogeneidade genética é uma característica dessa doença, observando-se diversos\npadrões de localização e extensão da\n\nhipertrofia.","D":"A expressão clínica da doença é pouco variável, sendo a maioria dos portadores assintomática."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183065","number":"183065","sourceNumber":"183065","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Apesar de importantes para a estratificação de risco e orientação da terapêutica nos\nportadores de Cardiomiopatia Hipertrófica CMH,\n\na sensibilidade e a especificidade desses critérios são limitadas. Os critérios clínicos\nestabelecidos\nde pior prognóstico na CMH são:","options":{"A":"Septo interventricular com espessura > 30 mm, morte súbita prematura na família, história de\nsíncope sem etiologia definida,\n\nTaquicardia Ventricular Não Sustentada (TVNS) ao Holtere resposta normal da pressão arterial ao\nteste de esforço em indivíduos com menos de 40 anos.","B":"Septo interventricular com espessura > 30 mm, morte súbita prematura na família, história de\nsíncope sem etiologia definida,\n\nTaquicardia Ventricular Não Sustentada (TVNS) ao Holter e resposta anormal da pressão arterial\nao teste de esforço em indivíduos com menos de\n60 anos.","C":"Septo interventricular com espessura > 40 mm, morte súbita prematura na família, história de\nsíncope sem etiologia definida,\n\nTaquicardia Ventricular Não Sustentada (TVNS) ao Holter e resposta anormal da pressão arterial\nao teste de esforço em indivíduos com menos de\n40 anos.","D":"Septo interventricular com espessura > 30 mm, morte súbita prematura na família, história de\nsíncope sem etiologia definida,\n\nTaquicardia Ventricular Não Sustentada (TVNS) ao Holter e resposta anormal da pressão arterial\nao teste de esforço em indivíduos com menos de\n40 anos."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183073","number":"183073","sourceNumber":"183073","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Ocorre pior prognóstico (morte súbita e evolução para Insuficiência Cardíaca\nCongestiva ? ICC) em pacientes com Cardiomiopatia\n\nHipertrófica CMH, com maior porcentagem de colágeno no miocárdio identificado pela biópsia.\nPodemos, apenas, CONCORDAR que","options":{"A":"analogamente à miocardiopatia isquêmica, vários indícios apontam que o mecanismo\narritmogênico que levaria à morte súbita, nos\nportadores de CMH, esteja diretamente ligado à\nfibrose miocárdica, como sugerido por estudos demonstrando direta\n\ncorrelação entre a presença de fibrose miocárdica visibilizada na Ressonância Magnética\nCardiovascular - RMC e Taquicardia\n\nVentricular Não Sustentada TVNS registrada no Holter.","B":"Analogamente à miocardiopatia isquêmica, vários indícios apontam que o mecanismo\narritmogênico que levaria à morte súbita, nos\nportadores de CMH, esteja indiretamente ligado à\nfibrose miocárdica, como sugerido por estudos demonstrando direta\n\ncorrelação entre a presença de fibrose miocárdica visibilizada na Ressonância Magnética\nCardiovascular - RMC e Taquicardia\n\nVentricular Não Sustentada TVNS registrada no Holter.","C":"ao contrário da miocardiopatia isquêmica, vários indícios apontam que o mecanismo\narritmogênico que levaria à morte súbita, nos\nportadores de CMH, esteja diretamente ligado à\nfibrose miocárdica, como sugerido por estudos demonstrando direta correlação entre a ausência de\nfibrose miocárdica visibilizada na Ressonância Magnética Cardiovascular - RMC e Taquicardia\nVentricular\n\nNão Sustentada TVNS registrada no Holter.","D":"analogamente à miocardiopatia isquêmica, vários indícios apontam que o mecanismo\narritmogênico que levaria à morte súbita, nos\nportadores de CMH, não esteja diretamente ligado à\nfibrose miocárdica, como sugerido por estudos demonstrando direta\n\ncorrelação entre a presença de fibrose miocárdica visibilizada na Ressonância Magnética\n\nCardiovascular - RMC e Taquicardia\n\nVentricular Não Sustentada TVNS registrada no Holter."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183630","number":"183630","sourceNumber":"183630","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os diuréticos de alça (furosemida) são os medicamentos de primeira escolha, em\ndecorrência do seu efeito venodilatador, que já tem início nos primeiros minutos da administração\nendovenosa. NÃO sendo adequado, porém, que:","options":{"A":"Já tem uso consagrado, sem trabalhos que demonstrem redução na mortalidade, com grandes\nefeitos na hipervolemia e congestão.","B":"Em decorrência dessa ação inicial, diminuem a pré-carga; além disso, são drogas que\npromovem grande eliminação de água livre, efeito este, mais precoce.","C":"É o diurético de escolha nas descompensações agudas dos pacientes congestos.","D":"A dose recomendada é de 1mg/Kg como dose de ataque."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183079","number":"183079","sourceNumber":"183079","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A RM é um método bastante útil na avaliação da Cardiomiopatia Hipertrófica CMH,\nfornecendo informações que auxiliam no\n\ndiagnóstico e no prognóstico da doença. Estudos comparativos entre a Ressonância Magnética\nCardiovascular RMC e a\n\necocardiografia demonstraram melhor sensibilidade na detecção de segmentos com hipertrofia.\n\nPodemos, apenas, CONCORDAR\nque,","options":{"A":"nos casos de dúvida diagnóstica, especialmente nos casos de diferenciação de hipertrofia\nmiocárdica em atletas, os achados de áreas de\nfibrose miocárdica, com padrão multifocal, apenas\ndefinem o diagnóstico da doença, uma vez que, hipertrofia fisiológica do exercício não resulta em\náreas de fibrose miocárdica.","B":"nos casos de dúvida diagnóstica, especialmente nos casos de diferenciação de hipertrofia\nmiocárdica em atletas, os achados de\n\náreas de fibrose miocárdica, com padrão multifocal ou confluente, definem o diagnóstico da\ndoença, uma vez que, hipertrofia fisiológica do exercício não resulta em áreas de fibrose\nmiocárdica.","C":"nos casos de dúvida diagnóstica, especialmente nos casos de diferenciação de hipertrofia\nmiocárdica em atletas, os achados de áreas de\nfibrose miocárdica, com padrão multifocal ou\nconfluente, não definem o diagnóstico da doença, uma vez que, hipertrofia fisiológica do exercício\nresulta em áreas de fibrose miocárdica.","D":"nos casos de dúvida diagnóstica, especialmente nos casos de diferenciação de hipertrofia\nmiocárdica em atletas, os achados de áreas de\nfibrose miocárdica confluente, definem o\ndiagnóstico da doença, uma vez que, hipertrofia fisiológica do exercício resulta em áreas de fibrose\nmiocárdica."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183635","number":"183635","sourceNumber":"183635","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O processo de imunomodulação tem como objetivo reduzir a agressão inflamatória e\nautoimune através da remoção e modulação de possíveis agentes agressores envolvidos na\npatogênese da miocardite. Sobre isso, assinale a alternativa INCORRETA:","options":{"A":"A terapia de imunoadsorção através de plasmaférese seletiva visa a retirada de autoanticorpos\nespecíficos associada à terapia\n\ncom IG-IV para imunomodulação inflamatória das citocinas e da produção dos autoanticorpos","B":"A pentoxifilina apresenta como propriedades anti-inflamatórias o bloqueio da transcriptase do\nTNF-a e a redução dos níveis de interleucinas 2 e 6, com consequente redução dos efeitos de\ncardioagressão dessas citocinas.","C":"A utilização da imunoadsorção em pacientes com cardiomiopatia inflamatória crônica com níveis\nséricos elevados de autoanticorpos contra ß1 neuroreceptor miocárdico associado à reposição de\nIG-IV, demonstrou redução da atividade inflamatória miocárdica e melhora clínica da classe\nfuncional e da função ventricular, mas não maior sobrevida ao fim de cinco anos.","D":"Na cardiomiopatia dilatada com IC crônica e na cardiomiopatia periparto, a utilização de\npentoxifilina na posologia de 1200mg a 2400mg/dia, pelo período de seis meses, ocasionou\nmelhora clínica da classe funcional e da função ventricular."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183062","number":"183062","sourceNumber":"183062","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Insuficiência Cardíaca Descompensada por Edema Agudo de Pulmão pode ser\nidentificada no paciente que apresenta diversas características, EXCETO pelo item:","options":{"A":"Quando apresenta aumento progressivo da pressão capilar pulmonar.","B":"No qual ocorre aumento do líquido nos espaços intersticial e alveolar pulmonar.","C":"Quando causa dispneia súbita e intensa ao repouso com saturação O2 < que 90% à respiração\nambiente.","D":"Quando esse quadro está comprovado pela radiografia de tórax."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183070","number":"183070","sourceNumber":"183070","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O conhecimento da fisiopatologia da IC Insuficiência Cardíaca e da Insuficiência\nCardíaca Descompensada ? ICD permite uma melhor\ncompreensão na abordagem do paciente.\nSendo INADEQUADO que,","options":{"A":"Apesar da gravidade da doença, conhecendo-se princípios básicos de sua fisiopatologia,\npode-se modificar sua evolução e mudar\n\no prognóstico da doença.","B":"A causa mais comum de ICD é a redução da contratilidade miocárdica, geralmente associada à\nmiocardiopatia isquêmica,\n\ndilatada idiopática, chagásica ou hipertensiva.","C":"Outras condições que levam à ICD são aquelas em que o coração é submetido à sobrecarga\nhemodinâmica apenas de volume,\n\ndistúrbios de FC (bradiarritmias ou taquiarritmias) ou condições que interfiram com o enchimento\natrial.","D":"Na fase inicial da IC, antes mesmo do estabelecimento da ICD, há diminuição da função\nmiocárdica, e mecanismos adaptativos\n\nsão estimulados para corrigir a disfunção ventricular."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183646","number":"183646","sourceNumber":"183646","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Nos estudos em que foi avaliada a relação entre o uso de insulina e insuficiência\ncardíaca - IC, verificou-se um impacto nulo ou\nde aumento de mortalidade. Estando CORRETO\nque:","options":{"A":"É provável que a insulina represente apenas um confundidor, tendo em vista que muitas vezes a\nsua indicação de tratamento representa um DM\ninicial ou a presença de indicação para o uso de\nmedicação oral (como insuficiência renal avançada), o que por si já demonstra status clínico mais\ngrave.","B":"É provável que a insulina represente apenas um confundidor, tendo em vista que muitas vezes a\nsua indicação de tratamento representa um DM\navançado ou a presença de contraindicação para o\nuso de medicação oral (como insuficiência renal avançada), o que por si já demonstra status clínico\nmais grave. Nenhum estudo foi realizado, entretanto, com o objetivo de comparar objetivamente o\nimpacto do tratamento com e sem insulina.","C":"É improvável que a insulina represente apenas um confundidor, tendo em vista que muitas\nvezes a sua indicação de tratamento\nrepresenta um DM avançado ou a presença de indicação para\no uso de medicação oral (como insuficiência renal avançada).","D":"É provável que a insulina represente apenas um confundidor, tendo em vista que muitas vezes a\nsua indicação de tratamento representa um DM\navançado ou a ausência de contraindicação para o\nuso de medicação oral (como insuficiência renal inicial), o que por si já demonstra status clínico\nmais leve. Nenhum estudo foi realizado, entretanto, com o objetivo de comparar objetivamente o\nimpacto do tratamento com e sem insulina."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183122","number":"183122","sourceNumber":"183122","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A situação clínica identificada no paciente que apresenta aumento abrupto da pressão\ncapilar pulmonar, ocorrendo aumento do líquido nos espaços intersticial e alveolar pulmonar,\ncausada de maneira súbita e intensa ao repouso deve ser entendida como","options":{"A":"Insuficiência Cardíaca Descompensada por Edema Agudo de Pulmão.","B":"Insuficiência Cardíaca Descompensada Aguda.","C":"Insuficiência Cardíaca Descompensada por Alto Débito.","D":"Insuficiência Cardíaca Descompensada Direita."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183645","number":"183645","sourceNumber":"183645","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A maioria dos pacientes vai necessitar do uso de mais de um medicamento para que\nsejam atingidas as metas de controle de Hipertensão. Sendo INADEQUADO que:","options":{"A":"Pacientes com HA estágio 1 e com risco CV alto ou muito alto ou com DCV associada e aqueles\ncom estágio 2 ou 3 com ou sem outros FRCV associados, devem ser considerados para o uso de\ncombinação de fármacos.","B":"A utilização de associações de dois medicamentos em baixas dosagens em hipertensos estágio\n1, mesmo com baixo ou moderado risco CV, embora\nnão preferencial, também poderá ser\nconsiderada em casos individuais.","C":"Associação de DIU tiazídicos com poupadores de potássio. O uso de DIU de alça deve ser\nreservado para aqueles com RFG abaixo de 10 ml/min ou com edema grave.","D":"Para a escolha dos medicamentos em associação, deve ser evitado o uso de anti-hipertensivos\ncom mesmo mecanismo."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183592","number":"183592","sourceNumber":"183592","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro das classes de anti-hipertensivos, atualmente consideradas preferenciais para o\ncontrole da PA em monoterapia inicial, são verdadeiras as indicações, EXCETO:","options":{"A":"Deve ser observado que os DIU são os fármacos que apresentam menos evidências de\nefetividade com relação aos desfechos CV, com\nclaros benefícios para todos os tipos de eventos.","B":"Há situações em que a indicação de um ou outro grupo ganha destaque, de acordo com a\ncomorbidade presente.","C":"O BB poderá ser considerado como fármaco inicial em situações específicas, como a\nassociação de enxaqueca.","D":"O BB poderá ser considerado como fármaco inicial em situações específicas, como a IC e a\ncoronariopatia."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183089","number":"183089","sourceNumber":"183089","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Há várias evidências indicando que a suspensão dos betabloqueadores pode promover\naumento da mortalidade, assim, deve-se\nevitar a suspensão sistemática dos betabloqueadores.\n\nQuando se suspeitar que eles são responsáveis pela instabilidade hemodinâmica dos pacientes,\napenas podemos ACEITAR que","options":{"A":"garantir a suspensão de drogas é aspecto importante a ser considerado é a suspensão dos\nbetabloqueadores nos pacientes que fazem uso deles.","B":"garantir a não suspensão de drogas é aspecto importante a ser considerado é a não suspensão\ndos betabloqueadores nos pacientes que fazem uso\ndeles, devendo a dose ser ajustada e a\nsuspensão somente ser realizada em casos de instabilidade hemodinâmica grave, bloqueios\natrioventriculares avançados ou efeito colateral comprovadamente relacionado ao medicamento.","C":"garantir a não suspensão de drogas é aspecto importante a ser considerado é a não suspensão\ndos betabloqueadores nos pacientes que fazem uso\ndeles, devendo a dose ser ajustada e a\nsuspensão somente ser realizada em casos de instabilidade hemodinâmica grave, bloqueios\natrioventriculares de primeiro grau.","D":"garantir a não suspensão de drogas é aspecto importante a ser considerado é a não suspensão\ndos betabloqueadores nos pacientes que fazem uso\ndeles, não devendo a dose ser ajustada e a\nsuspensão somente ser realizada em casos de instabilidade hemodinâmica grave, bloqueios\natrioventriculares avançados ou efeito colateral comprovadamente relacionado ao medicamento."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-181325","number":"181325","sourceNumber":"181325","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale a alternativa que representa o débito cardíaco.","options":{"A":"Força exercida no miocárdio no final da diástole.","B":"Produto do volume sistólico pela frequência cardíaca.","C":"Mede a pós carga ou a resistência do ventrículo esquerdo.","D":"Pressão exercida pelo sangue contra a parede das artérias.","E":"Resistência, impedância ou pressão que os ventrículos têm que exercer para ejetar seu volume\nsanguíneo."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-181338","number":"181338","sourceNumber":"181338","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo masculino, 50 anos, obeso, diabético tipo 2, com HDL baixo e função\nrenal normal, vem mantendo pressão arterial de 145 x 95 mmHg. Diante do quadro, qual a conduta\nterapêutica e meta pressórica a ser atingida?","options":{"A":"Mudança do estilo de vida associada ao tratamento medicamentoso, com meta pressórica < 140\nx 90 mmHg.","B":"Mudança do estilo de vida associada ao tratamento medicamentoso, com meta pressórica < 140\nx 80 mmHg.","C":"Mudança do estilo de vida associada ao tratamento medicamentoso, com meta pressórica < 130\nx 80 mmHg.","D":"Mudança do estilo de vida por 3 meses; na falta de controle pressórico nesse período, iniciar\ntratamento farmacológico. Meta pressórica < 130 x 80 mmHg.","E":"Mudança do estilo de vida por 6 meses; na falta de controle pressórico nesse período, iniciar\ntratamento farmacológico. Meta pressórica < 130 x 80 mmHg."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183564","number":"183564","sourceNumber":"183564","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No que se refere ao manejo de suporte de crianças com Hipertensão Arterial Pulmo\n(HAP), assinale a alternativa INCORRETA.","options":{"A":"A anticoagulação com varfarina é contraindicada em crianças com doença tromboembólica,\npodendo ser benéfica em outros pacientes com\nHAP de outras etiologias.","B":"Como a hipóxia é um vasoconstritor pulmonar potente, deve-se utilizar a suplementação com\noxigênio para a sua correção em pacientes com HAP.","C":"Deve-se tratar a insuficiência cardíaca e as arritmias com digoxina (melhora a contratilidade) e\nantiarrítmicos.","D":"Os diuréticos são utilizados para tratar a sobrecarga de volume causada pela HAP associada\ncom falência de ventrículo direito e\n\nsão utilizados habitualmente na doença mais avançada."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183575","number":"183575","sourceNumber":"183575","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O sildenafil tem sido utilizado com o objetivo de prevenir os episódios de Hipertensão\nArterial Pulmonar, observando-se melhora na\nPressão Arterial Pulmonar, no tempo para extubação\ne no tempo de permanência na UTI de crianças após a realização de cirurgia cardíaca. São efeitos\nadversos relacionados ao uso do sildenafil, EXCETO","options":{"A":"dispepsia.","B":"hipertensão arterial sistêmica.","C":"epistaxe.","D":"cefaleia."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-182741","number":"182741","sourceNumber":"182741","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Aspectos importantes na medição da PA na população idosa decorrem de alterações\npróprias do envelhecimento, com grande interação nos achados e na interpretação clínica da\nsituação, sendo assim, assinale a alternativa CORRETA:","options":{"A":"A pseudo-hipertensão, que está associada ao processo aterosclerótico, pode ser detectada pela\nmanobra de Osler, ou seja, a artéria radial permanece ainda palpável após a insuflação do\nmanguito pelo menos 30 mmHg acima do desaparecimento do pulso radial. Maior ocorrência de\nEAB, hipotensão ortostática e pós-prandial e, finalmente, a presença de arritmias, como fibrilação\natrial, podem dificultar a medição da PA.","B":"A pseudo-hipertensão, não está associada ao processo aterosclerótico, pode ser detectada pela\nmanobra de Osler, ou seja, a artéria radial permanece ainda palpável após a insuflação do\nmanguito pelo menos 30 mmHg acima do desaparecimento do pulso radial. Maior ocorrência de\nEAB, hipotensão ortostática e pós-prandial e, finalmente, a presença de arritmias, como fibrilação\natrial, podem dificultar a medição da PA.","C":"A pseudo-hipertensão, que está associada ao processo aterosclerótico, pode ser detectada pela\nmanobra de Osler, ou seja, a artéria radial permanece impalpável após a insuflação do manguito\npelo menos 30 mmHg acima do desaparecimento do pulso radial. Maior ocorrência de EAB,\nhipotensão ortostática e pós-prandial e, finalmente, a presença de arritmias, como fibrilação\natrial,\npodem dificultar a medição da PA.","D":"A pseudo-hipertensão, que está associada ao processo aterosclerótico, pode ser detectada pela\nmanobra de Osler, ou seja, a artéria radial permanece ainda palpável após a insuflação do\nmanguito pelo menos 50 mmHg acima do desaparecimento do pulso radial. Maior ocorrência de\nEAB, hipotensão ortostática e pós-prandial e, finalmente, a presença de arritmias, como fibrilação\natrial, podem dificultar a medição da PA."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-182760","number":"182760","sourceNumber":"182760","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Ocorre uma grande variação da PA nos idosos ao longo das 24 horas, o que torna a\nMAPA uma ferramenta muitas vezes útil, também a pseudo-hipertensão, que está associada ao\nprocesso aterosclerótico, pode ser detectada pela manobra de Osler. Dessa forma, indique a\nalternativa CORRETA:","options":{"A":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a menor frequência do hiato auscultatório, que consiste no desaparecimento\ndos sons durante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente altos para a PAD.","B":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a maior frequência do hiato auscultatório, que consiste no aparecimento\nprecoce dos sons durante a deflação do manguito, não resultando em valores falsamente baixos\npara a PAS ou falsamente altos para a PAD.","C":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a maior frequência do hiato auscultatório, que consiste no desaparecimento\ndos sons durante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente altos para a PAD.","D":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a maior frequência do hiato auscultatório, que consiste no aparecimento dos\nsons durante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente baixos para a PAD."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-182792","number":"182792","sourceNumber":"182792","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A decisão terapêutica para tratamento da Pressão Arterial deve basear-se não apenas\nno nível da PA, mas considerar também a\npresença de Fatores de Risco, Lesões de Órgãos Alvos\ne Doença Cardiovascular concomitante. Em relação a isso, assinale a alternativa INCORRETA:","options":{"A":"Por outro lado, resultados de estudos clínicos controlados e randomizados com uso de fármacos\nanti-hipertensivos placebo-controlados em hipertensos demonstraram claramente redução\nsignificativa de mortalidade CV, AVE, infarto do miocárdio e IC. Cabe destacar que a maioria\ndesses estudos avaliou indivíduos com idade \"maior ou igual que\" 55 anos, de alto risco CV e\ntempo de seguimento de 3 a 6 anos, limitando, portanto, a extrapolação desses benefícios para o\ntratamento de longo prazo e em pacientes com outras características.","B":"Indivíduos com PA \"maior ou igual que\" 160/100 mmHg e/ou portadores de risco CV estimado\nalto, mesmo no estágio 1, devem iniciar de\nimediato o tratamento medicamentoso associado à\nterapia não medicamentosa.","C":"A abordagem terapêutica da PA elevada inclui medidas não medicamentosas e o uso de\nfármacos anti-hipertensivos, a fim de reduzir a PA,\nproteger órgãos-alvo, prevenir desfechos CV e\nrenais. Medidas não medicamentosas têm se mostrado ruins na redução da PA, pela perda de\nadesão a curto prazo.","D":"Estudos com fármacos anti-hipertensivos, a maioria realizada com esse perfil de pacientes\nhipertensos estágios 2 e 3 e/ou de alto risco,\ndemonstraram eficácia na redução da PA e proteção\nCV."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-182802","number":"182802","sourceNumber":"182802","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A abordagem de hipertensos estágio 1 de risco baixo e moderado, apresenta uma\nlacuna no rol de evidências em favor do impacto da terapia anti-hipertensiva sobre a redução de\ndesfechos em hipertensos estágio 1 de risco baixo e moderado. Em relação a isso, assinale a\nalternativa INCORRETA:","options":{"A":"Nos hipertensos estágio 1 e moderado ou baixo risco CV, a terapia não farmacológica deve ser\ntentada por um ano.","B":"Findo esse período no qual a falta de controle da PA condicionará o início de terapia\nfarmacológica. Faz-se imperativo, contudo,\nacompanhar esses indivíduos com avaliação periódica\nda adesão às medidas não farmacológicas.","C":"Constatada a falta de adesão às medidas não farmacológicas ou a piora dos valores\npressóricos, dever-se-á iniciar precocemente a terapia farmacológica.","D":"Vale destacar que a intervenção em hipertensos de baixo risco no estágio 1 pode prevenir a\nprogressão para um risco CV mais elevado."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-158800","number":"158800","sourceNumber":"158800","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Frequentemente há necessidade de associação de fármacos para o controle da\npressão arterial. Qual a associação de fármacos\nque deve ser usada com cautela em pacientes\ndiabéticos, em razão da dificuldade do controle glicêmico?","options":{"A":"Betabloqueadores e diuréticos.","B":"Diuréticos e bloqueadores dos receptores de angiotensina.","C":"Inibidores da enzima conversora angiotensina e diuréticos.","D":"Bloqueadores dos canais de cálcio e bloqueadores dos receptores de angiotensina.","E":"Bloqueadores dos canais de cálcio e inibidores da enzima conversora de angiotensina."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-158795","number":"158795","sourceNumber":"158795","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente, 45 anos, obesa, comparece ao ambulatório e relata ser hipertensa e\ndislipidêmica. Traz resultados de exames\nlaboratoriais: glicemia 120 mg/dl; triglicerídeos 180 mg/dl\ne LDL 160 mg/dl, e na consulta PA = 170 x 100 mmHg. Foi orientada a iniciar de imediato terapia\nnão medicamentosa. Conforme a 7ª Diretriz Brasileira de Hipertensão Arterial, qual o estágio da\nhipertensão quando deve ser iniciada a terapia medicamentosa, qual a meta e a melhor conduta\nterapêutica a ser implementada?","options":{"A":"Estágio 2, terapia medicamentosa deve ser iniciada após 3 meses da mudança no estilo de vida;\n\n< 130 x 80 mmHg; terapia combinada (duas classes diferentes).","B":"Estágio 2, terapia medicamentosa deve ser iniciada de imediato; < 140 x 90 mmHg; terapia\ncombinada (duas classes diferentes).","C":"Estágio 2, terapia medicamentosa deve ser iniciada de imediato; < 130 x 80 mmHg; terapia\ncombinada (duas classes diferentes).","D":"Estágio 2, terapia medicamentosa deve ser iniciada de imediato; < 130 x 80 mmHg;\nmonoterapia.","E":"Estágio 3, terapia medicamentosa deve ser iniciada de imediato; < 130 x 80 mmHg; terapia\ncombinada (duas classes diferentes)."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161356","number":"161356","sourceNumber":"161356","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente feminina de 56 anos de idade, hipertensa mal controlada, evoluiu com\nagitação seguida de insuficiência respiratória\nnesta manhã. Sua pressão sistólica foi de 230 mmHg.\nQuando assumiu o seu turno no plantão, foi passado o caso como Encefalopatia Hipertensiva, após\ndiagnóstico por Tomografia de Crânio. Dos achados a seguir, qual deles, na Tomografia, NÃO é\ncompatível com o diagnóstico?","options":{"A":"Edema Cerebral.","B":"Apagamento de Sulcos.","C":"Lâmina hiperdensa.","D":"Dificuldade de separação de substância cinza e branca."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-158754","number":"158754","sourceNumber":"158754","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 15 anos, sexo feminino, foi atendida na emergência com quadro de\nfaringoamigdalite. O médico avaliou a paciente e a liberou para casa com prescrição de\n\nanti-inflamatório. Evoluiu com poliartrite, nódulos subcutâneos e cardite. Qual a lesão valvar mais\nfrequente na febre reumática crônica?","options":{"A":"Estenose mitral.","B":"Estenose aórtica.","C":"Estenose tricúspide.","D":"Insuficiência aórtica.","E":"Insuficiência mitral."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161302","number":"161302","sourceNumber":"161302","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quando da escolha do tratamento anti-hipertensivo, ocorre a necessidade de grande\nraciocínio clínico a fim de determinar a escolha ideal, considerando paciente, mecanismo de ação\ndas medicações, bem como seus efeitos colaterais. Acerca desse assunto, indique a opção\nconsiderada INCORRETA.","options":{"A":"A metildopa pode provocar reações autoimunes, como febre, anemia hemolítica, galactorreia e\ndisfunção hepática, que na maioria dos casos desaparecem com a cessação do uso.","B":"Os Betabloqueadores promovem diminuição inicial do débito cardíaco, e aumento da secreção\nde renina, havendo readaptação dos\nbarorreceptores e aumento das catecolaminas nas sinapses\nnervosas.","C":"Os bloqueadores dos canais de cálcio agem primordialmente proporcionando redução da RVP\ncomo consequência da diminuição da quantidade de\ncálcio no interior das células musculares lisas\ndas arteríolas, decorrente do bloqueio dos canais de cálcio na membrana dessas células.","D":"Bloqueadores dos receptores AT1 da angiotensina II, os BRA antagonizam a ação da\nangiotensina II por meio do bloqueio específico dos receptores AT1, responsáveis pelas ações\nvasoconstritoras, proliferativas e estimuladoras da liberação de androsterona, próprias da\nangiotensina II."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161392","number":"161392","sourceNumber":"161392","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente com Insuficiência Renal Crônica não dialítica apresenta hoje intensa dispneia\ndemonstrando em sua ausculta pulmonar estertores e roncos difusos, sendo sua saturação de\n80%. Foi indicado entubação e iniciada ventilação mecânica com altas FiO2. Sua pressão é de 230\nx 120 mmHg. Iniciado Nitroprussiato de Sódio e solicitado avaliação da Nefrologia para possível\nHemodiálise, assinale a alternativa considerada ADEQUADA.","options":{"A":"Provavelmente não ocorrerá necessidade de hemodiálise após controle da hipertensão.","B":"Foi inadequada a indicação de ventilação mecânica.","C":"A opção por nitroprussiato foi inadequada.","D":"Maior risco de toxicidade por disfunção orgânica."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161226","number":"161226","sourceNumber":"161226","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"?Medicação que promove a inibição direta da ação da renina com consequente\ndiminuição da formação de angiotensina II.\nOutras ações podem contribuir para a redução da PA e\na proteção tissular, tais como redução da atividade plasmática de renina, bloqueio de um receptor\ncelular próprio de renina/pró-renina e diminuição da síntese intracelular de angiotensina II. Foi\ndemonstrado sua eficácia anti-hipertensiva, bem como sua capacidade, em sonoterapia, de\nredução da PA de intensidade semelhante aos demais anti-hipertensivos.? Marque a alternativa a\nque corresponde essa afirmação.","options":{"A":"BRA.","B":"IECA.","C":"Alisquireno.","D":"Betabloqueador."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161197","number":"161197","sourceNumber":"161197","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Acerca da pesquisa diagnóstica de complicações em órgãos-alvo, relacionadas com a\nHipertensão Arterial, as informações obtidas e otimizadas pelo Ecocardiograma estão corretas, com\nEXCEÇÃO de uma. Aponte-a.","options":{"A":"Menos sensível do que o ECG no diagnóstico de HVE.","B":"Agrega valor na avaliação das formas geométricas de hipertrofia e tamanho do átrio esquerdo.","C":"Análise da função sistólica e diastólica.","D":"Indicado na presença de indícios de HVE ao ECG ou pacientes com suspeita clínica de IC."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161203","number":"161203","sourceNumber":"161203","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação à decisão de tratamento da abordagem de hipertensos estágios 2 e 3 e/ou\nde alto risco, assinale a alternativa\nconsiderada CORRETA.","options":{"A":"Indivíduos com PA (maior ou igual) 180/100 mmHg e/ou portadores de risco CV estimado alto,\nmesmo no estágio 1, devem iniciar de imediato o tratamento medicamentoso associado à terapia\nnão medicamentosa.","B":"Estudos com fármacos anti-hipertensivos, a maioria realizada com esse perfil de pacientes,\ndemonstraram eficácia na redução\n\nda PA e proteção CV.","C":"Admite-se que a terapia não farmacológica isoladamente possa promover reduções da PA\nsuficientes para o alcance da meta pressórica recomendada, sendo efetivo controle da PA e de\noutros FRCV frequentemente presentes.","D":"Embora o benefício absoluto da terapia seja menor nos estágios 2 e 3, também aumenta o risco\nresidual devido à frequente presença e influência de outros FR e LOA já instalada, neutralizando\nparte desse benefício. Essa observação reforça a importância de se abordar o risco CV de forma\nglobal."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161270","number":"161270","sourceNumber":"161270","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentre as possíveis causas de hipertensão arterial secundária, ou seja, com etiologia\ndefinida e, acima de tudo, potencialmente\ncurável, o Feocromocitoma (FEO) são tumores de células\ncromafins do eixo simpático-adreno-medular produtores de catecolaminas. A respeito disso, aponte\na alternativa INCORRETA.","options":{"A":"De 10% a 15% são extradrenais (paragangliomas), 10% são bilaterais e 90% são malignos.","B":"Formas familiares apresentam traço autossômico dominante ou são parte de síndromes com\nmutações genéticas reconhecidas.","C":"Presença de HA persistente ou paroxística (50%), paroxismos de cefaleia, sudorese profusa e\npalpitações (tríade clássica) são indicativos da doença.","D":"O diagnóstico laboratorial é baseado em dosagens de catecolaminas e seus metabólitos no\nsangue e na urina."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161414","number":"161414","sourceNumber":"161414","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentre os objetivos de uma reabilitação cardiovascular e da prevenção secundária,\npodemos considerar como seus pilares da reabilitação cardiovascular os listados a seguir, com\nEXCEÇÃO de um. Indique-o.","options":{"A":"Mudanças no estilo de vida com ênfase na atividade física programada, adoção de hábitos\nalimentares saudáveis, remoção do tabagismo e do uso de drogas em geral.","B":"Uso de estratégias para modular o estresse.","C":"O programa de RCV deve ter como objetivo, não só melhorar o estado fisiológico, mas sem\npoder interferir também o psicológico do paciente cardíaco.","D":"O programa deve se basear em uma intervenção multidisciplinar (programa de exercício,\neducação, avaliação médica, avaliação nutricional etc.)."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161359","number":"161359","sourceNumber":"161359","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro dos conceitos epidemiológicos básicos de Hipertensão Arterial, indique a\nalternativa que NÃO se encaixa perfeitamente nesse assunto.","options":{"A":"Hipertensão Arterial (HA) é condição clínica multifatorial caracterizada por elevação sustentada\ndos níveis pressóricos = 140 e/ou 90 mmHg.","B":"Frequentemente se associa a distúrbios metabólicos, alterações funcionais e/ou estruturais de\nórgãos-alvo.","C":"Agravada pela presença de outros Fatores de Risco (FR), como dislipidemia, obesidade\nabdominal, intolerância à glicose e Diabetes Melito (DM).","D":"Mantém associação dependente com eventos, como morte súbita, Acidente Vascular Encefálico\n(AVE), Infarto Agudo do Miocárdio (IAM),\nInsuficiência Cardíaca (IC), Doença Arterial Periférica\n(DAP) e Doença Renal Crônica (DRC), fatal e não fatal."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161366","number":"161366","sourceNumber":"161366","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentre os diversos fatores de risco para Hipertensão Arterial, na realidade brasileira,\nestudos que avaliaram o impacto de\npolimorfismos na população não conseguiram identificar um\npadrão mais prevalente. Indique este fator.","options":{"A":"Na ingestão de álcool.","B":"na idade.","C":"Na genética.","D":"No sexo."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161380","number":"161380","sourceNumber":"161380","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Você participa do grupo de conselho de saúde de sua cidade, e como médico foi\nsolicitado a opinar a respeito de estratégias para a implementação de medidas de prevenção e\ndesenvolvimento da Hipertensão Arterial. Em relação à sua opinião sobre essas estratégias,\nassinale a alternativa considerada INCORRETA.","options":{"A":"Englobam políticas públicas de saúde combinadas com ações das sociedades médicas e dos\nmeios de comunicação.","B":"O objetivo deve ser estimular o diagnóstico precoce, e somente o tratamento medicamentoso\ncontínuo.","C":"O controle da PA e de FR associados por meio da modificação do estilo de vida (MEV).","D":"Estimular uso regular de medicamentos."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161383","number":"161383","sourceNumber":"161383","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Sobre o sedentarismo no contexto brasileiro de hipertensos, estudos de nossa\npopulação revelaram prevalência geral de sedentarismo de 75,8%. Observou-se associação\nsignificativa entre HA e idade, sexo masculino, e diversos outros fatores, EXCETO por:","options":{"A":"sobrepeso.","B":"adiposidade central.","C":"sedentarismo nos momentos de folga e durante o trabalho.","D":"escolaridade inferior a 8 anos e renda per capita superior a 5 salários mínimos."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161389","number":"161389","sourceNumber":"161389","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em referência aos procedimentos para se aferir à Pressão Arterial, marque a opção que\nNÃO se enquadra nesses procedimentos.","options":{"A":"Explicar o procedimento ao paciente e deixá-lo em repouso de 3 a 5 minutos em ambiente\ncalmo.","B":"Certificar-se de que o paciente não esteja com a bexiga cheia.","C":"Certificar-se de que o paciente não tenha praticado exercícios físicos há pelo menos 60 minutos.","D":"Certificar-se de que o paciente não tenha fumado nos 10 minutos anteriores"},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161393","number":"161393","sourceNumber":"161393","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para a adequada técnica de aferição da Pressão Arterial, assinale a alternativa\nCORRETA.","options":{"A":"Posicionamento, o paciente deve estar sentado, com pernas cruzadas.","B":"Posicionamento, o paciente deve estar com os pés apoiados no chão, dorso recostado na\ncadeira e relaxado.","C":"O braço deve estar na altura acima do coração, apoiado, com a palma da mão voltada para cima\ne as roupas não devem garrotear o membro.","D":"Medir a PA na posição de pé, após 5 minutos, nos diabéticos, idosos e em outras situações em\nque a hipotensão ortostática possa ser\nfrequente ou suspeitada."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161282","number":"161282","sourceNumber":"161282","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Nos casos de miocardite, a Ressonância Nuclear Magnética NÃO está indicada:","options":{"A":"Na avaliação da função, geometria e morfologia ventricular na suspeita de miocardite aguda,\nsubaguda ou crônica.","B":"Na investigação diagnóstica de miocardite aguda, crônica ou suspeita de miocardite prévia.","C":"No acompanhamento de 4 a 12 semanas do episódio agudo.","D":"Na miocardite fulminante com instabilidade hemodinâmica."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-161289","number":"161289","sourceNumber":"161289","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Considerando as medidas de suporte no tratamento das miocardites, marque a opção\nINCORRETA.","options":{"A":"O transplante cardíaco está indicado em situação de prioridade para pacientes que não\napresentam melhora clínica ou hemodinâmica.","B":"O suporte inotrópico deve ser utilizado pelo menor tempo possível e na mínima dose necessária.","C":"A ventilação não invasiva não é uma boa opção terapêutica em pacientes pediátricos com\ninsuficiência cardíaca.","D":"Anticoagulante oral está indicado nos casos de miocardite em associação com fibrilação atrial,\ntrombos intracavitários ou fenômenos tromboembólicos."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134824","number":"134824","sourceNumber":"134824","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente com história de Infarto Agudo do Miocárdio, ocorrido há 4 anos, evolui com\nprogressiva deterioração do quadro, com edema, dispneia e agora sinais de baixa perfusão\ntecidual. Foi, então, indicado uso de Inotrópico, mas estava apenas disponível a Dobutamina.\n\nDiante de tal caso, assinale a alternativa que MELHOR define esse quadro clínico.","options":{"A":"Melhora o consumo de oxigênio pelo miocárdio (diminui).","B":"Aumenta o fluxo sanguíneo aos órgãos.","C":"Protege o coração de arritmias.","D":"Sua dose inicia-se a 15 mcg/kg/min."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134112","number":"134112","sourceNumber":"134112","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Jovem de 26 anos de idade deu entrada no hospital com queixa de muita fadiga,\nreferindo dor torácica no dia anterior que o\nobrigava a ficar de cócoras, ou até apertando o tórax\ncontra a cama. Seu exame físico mostra pulso fino e rápido, alguma dispneia e jugulares cheias.\nApesar de não ser obeso, sua ausculta cardíaca mostra-se abafada, mas sem atrito\naudível. Nesse quadro clínico, qual padrão de eletrocardiograma você, como médico, espera\nencontrar?","options":{"A":"Supra de ST de V1 a V6.","B":"Sobrecarga ventricular.","C":"Variação de amplitude de QRS na mesma derivação unipolar.","D":"Normal."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134314","number":"134314","sourceNumber":"134314","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Jovem masculino, 32 anos de idade, deu entrada no hospital após grande mal-estar,\npor uso de cocaína. Seu quadro de intoxicação\nmostra taquicardia, sudorese fria e agitação. Sua\npressão está em 210 x 120 mmHg e sua frequência cardíaca em 185 bpm, referindo, nesse\nmomento, dor torácica. Para esse caso clínico, indique a alternativa que não é adequada:","options":{"A":"Benzodiazepínicos.","B":"Betabloqueadores.","C":"Antagonistas de canal de cálcio.","D":"Oxigênio."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134277","number":"134277","sourceNumber":"134277","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quando lidamos com quadros de emergência hipertensiva, frequentemente devemos\nutilizar o Nitroprussiato de Sódio. Por se tratar de medicação potente, sua farmacologia deve ser\nbem entendida, sendo que","options":{"A":"Atua somente em artérias.","B":"Pode ser usado em todos os pacientes.","C":"Seu metabólico tóxico prejudica a respiração.","D":"Somente funciona em altas doses."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134858","number":"134858","sourceNumber":"134858","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente feminina de 60 anos de idade, hipertensa crônica inicia quadro de\nintensa dispneia após negligenciar medicações\nambulatoriais de tratamento da hipertensão. Em\nsua avaliação inicial apresenta ausculta com estertores e uma queda da saturação, estando com\n88%. Sua PA está bastante elevada, com 210 X 120 mmHg, fora edema em membros inferiores\nbilateralmente 2+/4+. Diante de tal caso, podemos AFIRMAR que","options":{"A":"Se trata de edema agudo de pulmão hipertensivo, melhor abordagem com Nitroprussiato de\nSódio por melhora pré e pós-carga.","B":"Como paciente está edemaciada, a melhor medicação seria diuréticos tiazídicos.","C":"Caso se utilize diuréticos, esses somente terão efeito na pós-carga a longo prazo.","D":"Se trata de edema agudo de pulmão hipertensivo, sendo melhor utilizar nifedipina."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134320","number":"134320","sourceNumber":"134320","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São considerados órgãos-alvo de emergência hipertensiva todos os elencados abaixo,\ncom a EXCEÇÃO de","options":{"A":"Coração.","B":"Placenta.","C":"Aorta.","D":"Córnea."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134848","number":"134848","sourceNumber":"134848","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente refere intensa cefaleia durante avaliação inicial, refere que o quadro se\niniciou após estresse emocional por discussão familiar. Não apresenta perdas segmentares\nou irritação meníngea, seu Glasgow está em 15. Porém, ao aferir sua pressão, encontramos\no valor de 190 X 110 mmHg. Assim, consideramos ADEQUADO","options":{"A":"Realizar TC de crânio de urgência, provavelmente se trata de HSA.","B":"Iniciar Nitroprussiato de Sódio por se tratar de Encefalopatia Hipertensiva.","C":"Medicar com analgésicos e ansiolíticos e, posteriormente, avaliar novamente PA.","D":"Abordagem como Urgência Hipertensiva com Nifedipina 10 mg de ação rápida."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134329","number":"134329","sourceNumber":"134329","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente idoso, 67 anos, dá entrada no hospital com mal-estar, agitação e cefaleia.\nRefere ser hipertenso, com uso irregular de\nmedicação. Sua PA se encontra em 210 x 120 mm Hg.\nNão se medica há um dia. Qual das medicações abaixo PODE levar a esse provável rebote?","options":{"A":"Nifedipina.","B":"Captopril.","C":"Metildopa.","D":"Hidroclorotiazida."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134334","number":"134334","sourceNumber":"134334","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para que ocorra o diagnóstico de emergência hipertensiva, é necessária a lesão em\nalgum dos órgãos-alvo documentado. Podemos considerar isso em","options":{"A":"Tomografia com hidrocefalia.","B":"Hemograma com anemia.","C":"Achado de células elmo.","D":"Proteinúria."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134274","number":"134274","sourceNumber":"134274","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente apresentando choque cardiogênico não-compressivo, com pressão\ncoloido-oncótica plasmática normal, não\ndesenvolverá edema pulmonar se, na manipulação da\npré-carga, conseguir manter uma pressão capilar pulmonar entre:","options":{"A":"6 a 9 mmHg.","B":"10 a 12 mmHg.","C":"15 a 18 mmHg.","D":"20 a 25 mmHg."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-131372","number":"131372","sourceNumber":"131372","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de 62 anos de idade é atendido na unidade de emergência com história de\ndor lancinante, extremamente súbita em região precordial, irradiada ao dorso. Ao chegar, estava\npálido, taquicárdico, pressão arterial de 180 x 110 mmHg; com sopro de regurgitação no foco\naórtico e estertores subcrepitantes em bases pulmonares. Pulsos periféricos diminuídos em MMIIS.\nEm relação ao caso, NÃO devemos introduzir imediatamente:","options":{"A":"Nitroprussiato de sódio.","B":"Derivados da morfina.","C":"Betabloqueadores.","D":"Nitratos.","E":"Bloqueadores da enzima conversora."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134036","number":"134036","sourceNumber":"134036","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente masculino, diabético, com 45 anos, apresenta em consulta de rotina níveis de\nPA = 150/97 mmHg. O restante do exame\nfísico é normal. O paciente refere que há anos mede a\npressão frequentemente, e que sempre apresenta esses valores de PA. Ao ECG, observa-se\nsobrecarga de câmaras esquerdas, e o PCR é igual a \"maior ou igual a\" 3 mg/l. De acordo com a\nestratificação de risco individual do paciente para hipertensão (considerar estágio), qual é o risco\ncardiovascular do paciente, sabendo que ele é diabético e já possui lesão em órgão-alvo?","options":{"A":"Risco muito alto.","B":"Risco médio.","C":"Risco alto.","D":"Risco baixo."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-109718","number":"109718","sourceNumber":"109718","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo masculino, 60 anos, apresenta medidas seriadas de pressão arterial\nem torno de 150 x 90 mmHg. Você orientará o\npaciente sobre medidas não farmacológicas de\ncontrole da pressão arterial. Assinale abaixo a medida que NÃO faz parte das orientações para\nesse paciente:","options":{"A":"Realizar atividade física regular.","B":"Estimular consumo de dieta rica em frutas, vegetais e potássio.","C":"Limitar ingestão de café.","D":"Limitar ingestão de bebidas alcoólicas."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-109986","number":"109986","sourceNumber":"109986","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual paciente que pode ser classificado como portador de insuficiência cardíaca\ncrônica em estágio C?","options":{"A":"Paciente hipertenso, assintomático e com ecocardiograma normal.","B":"Paciente hipertenso, assintomático e com hipertrofia ventricular esquerda no ecocardiograma.","C":"Paciente hipertenso, assintomático e com redução da fração de ejeção no ecocardiograma.","D":"Paciente hipertenso, com sintomas de insuficiência cardíaca e redução da fração de ejeção no\necocardiograma."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-110063","number":"110063","sourceNumber":"110063","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A contraindicação ao uso de inibidores da enzima conversora de Angiotensina na\nInsuficiência Cardíaca Crônica é","options":{"A":"a fração de ejeção abaixo de 35%.","B":"o diagnóstico de estenose de artéria renal bilateral.","C":"a creatinina plasmática acima de 1,5 mg/dl.","D":"a pressão arterial sistólica abaixo de 100 mmhg."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-109766","number":"109766","sourceNumber":"109766","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo masculino, 76 anos, com Hipertensão Arterial Sistólica Isolada, sem\noutras comorbidades. Assinale a MELHOR opção terapêutica para esse paciente.","options":{"A":"Diurético tiazídico.","B":"Beta-bloqueador.","C":"Bloqueador do receptor da angiotensina.","D":"Nitrato."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-109971","number":"109971","sourceNumber":"109971","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São alterações hemodinâmicas resultantes da administração de dobutamina, EXCETO","options":{"A":"o aumento da frequência cardíaca.","B":"o aumento do débito cardíaco.","C":"a redução do fluxo esplâncnico.","D":"a diminuição da resistência vascular sistêmica."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-110608","number":"110608","sourceNumber":"110608","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A Síndrome metabólica é descrita como:","options":{"A":"Obesidade abdominal (acima de 102 cm no homem e 88 cm na mulher),\nhipertrigliceridemia\n\n(acima de 150 mg/dl), baixos níveis de HDL-colesterol (menor que 40 mg/dl nos homens e\n50 mg/dl nas mulheres) e hipertensão arterial\n(PA maior ou igual a 130 x 85 mmHg).","B":"IMC acima de 35 nas mulheres e 38 nos homens. Associado a: hiperglicemia de jejum\n(acima de 126 mg/dl), hipertrigliceridemia (acima de\n\n150 mg/dl) e hipertensão arterial (PA maior ou igual\na 130 x 85 mmHg).","C":"Obesidade abdominal (acima de 102 cm no homem e 88 cm na mulher),\nhipertrigliceridemia\n\n(acima de 180 mg/dl), baixos níveis de HDL-colesterol (menor que 40 mg/dl nos homens e\n50 mg/dl nas mulheres), hiperglicemia de\njejum (acima de 118 mg/dl) e hipertensão arterial (PA\nmaior ou igual a 130 x 85 mmHg).","D":"Hipertensão arterial (PA maior que 130 x 85 mmHg), hipertrigliceridemia (acima de 180\nmg/dl), baixos níveis de HDL-colesterol (menor que 40 mg/dl nos homens e 50 mg/dl nas\nmulheres), hiperglicemia de jejum (acima de 118 mg/dl) e obesidade.","E":"Hiperglicemia de jejum (acima de 126 mg/dl),\n\nhipertrigliceridemia (acima de 150 mg/dl), hipertensão arterial (PA maior ou igual a 130 x 85\nmmHg) e obesidade."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-86639","number":"86639","sourceNumber":"86639","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente 52 anos, masculino, com relato de taquidispneia há três horas acompanhada\nde cefaleia importante holocraniana. Refere\nainda que observou dificuldade respiratória progressiva\na partir do início do quadro. É hipertenso há 10 anos e faz uso irregular de captopril 25 mg três\nvezes ao dia e hidroclorotiazida 25 mg/dia. Tabagista crônico há 30 anos e deixou há 5 anos. Nega\netilismo, dislipidemia e diabetes mellitus. O diagnóstico sindrômico para este paciente é:","options":{"A":"Emergência hipertensiva sem lesão órgão-alvo.","B":"Urgência hipertensiva sem lesão órgão-alvo.","C":"Emergência hipertensiva com provável lesão órgão-alvo.","D":"Urgência hipertensiva com provável lesão órgão-alvo.","E":"Apenas urgência hipertensiva."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-86864","number":"86864","sourceNumber":"86864","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual a maior anormalidade na insuficiência ventricular esquerda?","options":{"A":"Edema de MMII;","B":"Cefaleia;","C":"Hepatomegalia;","D":"Congestão vascular pulmonar;","E":"Hipertensão arterial."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-86803","number":"86803","sourceNumber":"86803","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os Inibidores da Enzima Conversora de Angiotensina (IECA), atualmente são drogas\neficazes em monoterapia nos pacientes com hipertensão arterial sistêmica. Assinale a alternativa\ncorreta sobre os efeitos adversos dessas drogas: I. Hipersensibilidade cutânea; II. Rubor facial;\nIII.\nBloqueio atrioventricular; IV. Alteração do paladar.","options":{"A":"Somente I é verdadeira.","B":"Somente I e II são verdadeiras.","C":"Somente III e IV são verdadeiras.","D":"Somente I e IV são verdadeiras.","E":"Somente II e III."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-86637","number":"86637","sourceNumber":"86637","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Rita de Cássia tem 56 anos, parda, recém chegada na Comunidade Vila das Casas.\nCasada com Antônio, 53 anos e mãe de dois\nfilhos adolescentes. Trabalha como caixa de\nsupermercado na área nobre da cidade, levando cerca de 1 hora no transporte em cada uma das\nviagens. Faz consultas regulares para planejamento familiar, rastreamento de câncer de colo de\nútero e controle da HAS. Na última consulta seu nível pressórico foi de 150 x 100 mmHg. O qual ela\natribuiu a uma semana estressante no trabalho. Atualmente está fazendo uso de Anlodipino 5\nmg/dia e Hidroclorotiazida 25 mg/dia. Foi pedido que ela realizasse uma Monitorização Residencial\nda Pressão Arterial e evidenciou uma média pressórica de 148 x 98 mmHg. Afirma que não sente\nnenhum sintoma, não tem tempo para fazer atividade física e nem fazer sua comida à parte da\nfamília e prefere resolver seus problemas de saúde com remédios. Tabagista há 36 anos. Na\nescala de Framinghan obteve resultado de 22% de chances de desenvolver um evento\ncardiovascular em 10 anos. Frente ao caso e considerando o sinergismo entre as medicações, qual\nseria conduta mais adequada:","options":{"A":"Reforçar as medidas não medicamentosas.","B":"Reforçar as medidas não medicamentosas e aumentar a dose do Antagonista dos Canais\nCálcio.","C":"Reforçar as medidas não medicamentosas e aumentar a dose da diurético.","D":"Reforçar as medidas não medicamentosas e substituir o Antagonista dos Canais Cálcio por\nIECA.","E":"Reforçar as medidas não medicamentosas e trocar as medicações por IECA e Betabloqueador."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-158414","number":"158414","sourceNumber":"158414","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente masculino, 63 anos, obeso, portador de hipertensão arterial sistêmica\ndescontrolada e em uso de hidroclorotiazida,\nanlodipino e losartana em doses máximas. Relatando\nsonolência diurna. Ao exame: pletórico. Qual a principal hipótese diagnóstica?","options":{"A":"Hiperaldosteronismo.","B":"Feocromocitoma.","C":"Síndrome da apneia, hipopneia obstrutiva do sono.","D":"Hipertensão renovascular.","E":"Hipotireoidismo."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-158398","number":"158398","sourceNumber":"158398","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Masculino de 68 anos, com antecedente pessoal de diabetes mellitus, hipertensão\narterial sistêmica e infarto do miocárdio prévio,\nem uso de AAS, enalapril 10 mg ao dia,\nhidroclorotiazida 25 mg ao dia e metformina 850 mg duas vezes ao dia. Esse quadro evoluiu com\ndispneia e ortopneia há três dias, piorando progressivamente. Ao exame físico, o paciente\napresentou: pressão arterial: 230 x 170 mmHg; frequência cardíaca: 120 bpm; frequência\nrespiratória: 36 irpm; saturação arterial de oxigênio: 94%. RX de tórax evidenciou infiltrado\npulmonar difuso, com predomínio na região peri-hilar, sugerindo quadro de congestão pulmonar.\nQual a conduta mais adequada para o caso?","options":{"A":"Noradrenalina EV + hidratação EV + culturas + antibioticoterapia.","B":"Morfina EV + midazolam EV + intubação orotraqueal.","C":"Nitroprussiato EV + furosemida EV + morfina EV + ventilação não invasiva (CPAP).","D":"Hidrocortisona EV + terbutalina SC + inalação com fenoterol e ipratrópio.","E":"Dobutamina EV + metoprolol EV + morfina EV + sildenafila VO."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-108575","number":"108575","sourceNumber":"108575","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 74 anos, hipertenso de longa data, em uso irregular de anti-hipertensivos.\nNo último ano, apresentou dispneia progressiva\naos médios esforços palpitações. Ao exame físico,\nníveis pressoricos elevados, ictus desviado e edema de extremidades. O eletrocardiograma\ndemostra hipertrofia ventricular esquerda. Qual dentre os diuréticos abaixo, é capaz de melhorar\nsintomas e modificar a história natural da doença relacionado ao caso descrito:","options":{"A":"Hidroclorotiazida.","B":"Espironolactona.","C":"Furosemida.","D":"Indapamida.","E":"Nenhuma das anteriores."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-108576","number":"108576","sourceNumber":"108576","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação aos achados na avaliação de Insuficiência Cardíaca (IC), assinale a\nCORRETA:","options":{"A":"A cardiomegalia é um achado específico de paciente com IC.","B":"A regurgitação funcional da valva mitral ou tricúspide, secundária à dilatação ventricular e\nanelar,\ncomumente leva a sopros diastólicos no paciente com IC.","C":"Na IC grave, podem ocorrer temperatura de até 39°C, secundária à vasoconstrição cutânea.","D":"A IC grave, de longa duração, pode levar à anorexia como resultado da congestão intestinal e\nhipoperfusão mesentérica.","E":"Todas estão incorretas."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-327229","number":"327229","sourceNumber":"327229","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O termo \"Insuficiência Cardíaca Crônica\" reflete a natureza progressiva e persistente da\ndoença. Embora a maioria das doenças que levam à Insuficiência Cardíaca (IC) caracterizem-se\npela presença de baixo débito cardíaco (muitas vezes compensado) no repouso ou no esforço (IC\nde baixo débito), algumas situações clínicas de alto débito também podem levar a Insuficiência\nCardíaca entre elas:","options":{"A":"Insuficiência Coronariana","B":"D. de Chagas","C":"Anemia","D":"Miocardite Viral"},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-327230","number":"327230","sourceNumber":"327230","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No diagnóstico de Hipertensão Arterial podemos encontrar Hipertensão mascarada que\né caracterizada por:","options":{"A":"Valores elevados no consultório, porém com PA normal pela MAPA ou medidas residenciais.","B":"Valores normais da PA no consultório, porém com PA elevada pela MAPA ou medidas\nresidenciais.","C":"Valores elevados da PA no consultório e pela MAPA.","D":"Valores normais da PA no consultório e pela MAPA."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-298202","number":"298202","sourceNumber":"298202","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A Insuficiência cardíaca (IC) é uma síndrome clínica complexa, na qual o coração é\nincapaz de bombear sangue de forma a atender às necessidades metabólicas tissulares, ou pode\nfazê-lo somente com elevadas pressões de enchimento. Em relação a IC assinale a alternativa\nCORRETA.","options":{"A":"São causas de IC de baixo débito: cardiopatia isquêmica, miocardiopatia dilatada, anemia e\ngravidez.","B":"IC crônica: pacientes com diagnóstico estabelecido de IC ou ocorrência dos sintomas de forma\nsúbita.","C":"IC com fração de ejeção reduzida (ICFER): FE ? 40%.","D":"A insuficiência cardíaca diastólica é definida como IC em pacientes com fração de ejeção acima\nde 25%."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-298204","number":"298204","sourceNumber":"298204","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação à Hipertensão Arterial em doentes renais. Assina a alternativa CORRETA:","options":{"A":"A Diretriz Brasileira de Hipertensão Arterial, 2020 recomenda em adultos com Hipertensão\nArterial e Doença Renal Crônica, diabéticos ou\nnão, meta de PA < 130/80 mmHg para os que\nestejam em tratamento conservador.","B":"A Diretriz Brasileira de Hipertensão Arterial, 2020 recomenda em adultos com Hipertensão\nArterial e Doença Renal Crônica, diabéticos\nou não, meta de PA < 120/75 mmHg.","C":"A Diretriz Brasileira de Hipertensão Arterial, 2020 recomenda em adultos com Hipertensão\nArterial e Doença Renal Crônica, diabéticos\nou não, meta de PA < 140/90 mmHg.","D":"A Diretriz Brasileira de Hipertensão Arterial, 2020 recomenda em adultos com Hipertensão\nArterial e Doença Renal Crônica, diabéticos\nou não, meta de PA < 120/80 mmHg."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-286703","number":"286703","sourceNumber":"286703","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quais são os sinais e sintomas mais específicos na insuficiência cardíaca:","options":{"A":"Ictus desviado para esquerda e cansaço","B":"Refluxo hepatojugular e dispnéia","C":"B3 e ortopnéia","D":"Pressão venosa jugular elevada e dispneia paroxística noturna"},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-252212","number":"252212","sourceNumber":"252212","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação a insuficiência mitral é CORRETO afirmar.","options":{"A":"A regurgitação mitral é definida pelo refluxo do sangue do Ventrículo Esquerdo ao átrio esquerdo\ndurante a sístole com achado\nauscultatório de sopro diastólico em foco mitral com irradiação para\naxila.","B":"A regurgitação mitral é definida pelo refluxo do sangue do Ventrículo Esquerdo ao átrio esquerdo\ndurante a diástole com achado\nauscultatório de sopro holossistólico ou mesossistólico.","C":"A regurgitação mitral é definida pelo refluxo do sangue do Ventrículo Esquerdo ao átrio esquerdo\ndurante a sístole com achado auscultatório\nde sopro holossistólico ou mesotelesistólico.","D":"A regurgitação mitral é definida pelo refluxo do sangue do Ventrículo Esquerdo ao átrio esquerdo\ndurante todo o ciclo cardíaco com achado\nauscultatório de sopro diastólico em foco mitral com\nirradiação para axila."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-256579","number":"256579","sourceNumber":"256579","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 72 anos, sexo masculino e diabético apresenta há 3 meses dispneia\nprogressiva para pequenos esforços e edema de\nmembros inferiores. No exame físico: Lucido\norientado, boa perfusão capilar periférica, creptantes nas bases pulmonares, B3, P2>A2, PA 90 x\n50mmHg e FC 100bpm sendo diagnosticado como insuficiência cardíaca descompensada. Qual o\nperfil clínico hemodinâmico neste caso?","options":{"A":"Perfil C","B":"Perfil A","C":"Perfil L","D":"Perfil B"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-208359","number":"208359","sourceNumber":"208359","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A insuficiência cardíaca é uma doença comum e a sua prevalência e incidência\ncontinuam a aumentar. Sobre essa patologia é CORRETO afirmar que:","options":{"A":"Na insuficiência cardíaca crônica agudizada, o padrão hemodinâmico se caracteriza por\nelevação progressiva das pressões de enchimento ventricular esquerdo por disfunção sistólica\npredominante associada a importante componente de disfunção diastólica.","B":"Na insuficiência cardíaca crônica agudizada, os principais fatores causais são infarto do\nmiocárdio, regurgitação mitral aguda por ruptura de\ncordoalha ou disfunção de músculo papilar por\nisquemia, disfunção miocárdica por miocardite.","C":"Uma das complicações da insuficiência cardíaca congestiva é o edema agudo de pulmão que se\ncaracteriza por intensa elevação das pressões de enchimento das cavidades direitas, ocasionando\nimportante transudação intersticial pulmonar para o interior dos alvéolos e bronquíolos terminais,\npodendo chegar à árvore brônquica principal.","D":"A insuficiência cardíaca direita caracteriza-se por disfunção ventricular direita com pressões de\nenchimento atrial direito elevadas associadas com baixo débito cardíaco e consequente hipotensão\narterial com congestão pulmonar."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-176014","number":"176014","sourceNumber":"176014","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O sopro de Carey Coombs está presente em qual patologia?","options":{"A":"Insuficiência pulmonar.","B":"Doença reumática em atividade.","C":"Endocardite infecciosa.","D":"Insuficiência aórtica."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-176035","number":"176035","sourceNumber":"176035","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 72 anos, sexo masculino e diabético apresenta há 3 meses dispneia\nprogressiva para pequenos esforços e edema de\nmembros inferiores. No exame físico: lúcido,\norientado, boa perfusão capilar periférica, crepitantes nas bases pulmonares, B3, P2 > A2, PA = 90\nx 50 mmHg e FC =\n\n100 bpm sendo diagnosticado como insuficiência cardíaca descompensada. Qual o perfil clínico\nhemodinâmico neste caso?","options":{"A":"Perfil A.","B":"Perfil B.","C":"Perfil C.","D":"Perfil L."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-176074","number":"176074","sourceNumber":"176074","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Davi tem 35 anos, é branco, solteiro, vive com os pais hipertensos e veio à consulta\npara fazer ?exames de rotina?. Nega doenças\nprévias e não apresenta queixas no momento. A\npressão arterial está em 154 x 96 mmHg. Podemos orientá-lo:","options":{"A":"A monitorar sua pressão arterial ao menos 2 vezes com um intervalo de 10 dias.","B":"Que está com hipertensão arterial estágio 3, sendo indicado modificações do seu estilo de vida.","C":"Que está com hipertensão arterial estágio 1 e necessita de tratamento medicamentoso no\ndiagnóstico.","D":"A monitorar sua pressão arterial ao menos 3 vezes pela manhã e 3 vezes à noite durante 7 dias."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-151883","number":"151883","sourceNumber":"151883","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 32 anos, procurou atendimento ambulatorial por apresentar dispneia aos\nesforços moderados. O exame físico do aparelho\ncardiovascular apresentava P2 > A2, primeira\nbulha mitral hiperfonética, sopro diastólico no quinto espaço intercostal esquerdo na linha\nhemiclavicular +++/6+; PA = 110 x 70 mmHg e FC 90 bpm. Neste caso, qual o principal diagnóstico,\ntratamento inicial e o exame considerado padrão-ouro no diagnóstico das valvopatias,\nrespectivamente?","options":{"A":"Estenose tricúspide, betabloqueador e cintilografia do miocárdio.","B":"Estenose mitral, betabloqueador e ecocardiograma.","C":"Estenose pulmonar, diurético e ecocardiograma.","D":"Insuficiência mitral, diurético e ecocardiograma."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-151899","number":"151899","sourceNumber":"151899","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A classificação da insuficiência cardíaca pelo perfil clínico hemodinâmico de Stevenson\né utilizado para guiar a terapêutica nos casos\nde insuficiência cardíaca, levando em consideração\nos seguintes critérios:","options":{"A":"Galope por B3 e B4.","B":"Sinais de congestão e B3.","C":"Presença de B3 na ausculta cardíaca.","D":"Sinais e sintomas de hipoperfusão e congestão."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-139123","number":"139123","sourceNumber":"139123","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em qual das situações abaixo, os betabloqueadores NÃO estão contraindicados?","options":{"A":"Crises de broncoespasmo.","B":"Doença vascular periférica sintomática.","C":"Bloqueio atrioventricular de segundo grau.","D":"Insuficiência cardíaca decorrente de miocardiopatia dilatada."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-103791","number":"103791","sourceNumber":"103791","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Cada uma das condições abaixo está associada ao desenvolvimento de edema\npulmonar, EXCETO:","options":{"A":"Aumento da pressão venosa pulmonar.","B":"Aumento da pressão oncótica do plasma.","C":"Altitude elevada.","D":"Eclâmpsia."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-81986","number":"81986","sourceNumber":"81986","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Pulsos desiguais na extremidade superior podem ser encontrados em cada um dos\nseguintes distúrbios, EXCETO:","options":{"A":"Dissecção aórtica.","B":"Doença de Takayasu.","C":"Estenose aórtica subvalvar.","D":"Estenose aórtica supravalvar.","E":"Aterosclerose da artéria subclávia."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-80961","number":"80961","sourceNumber":"80961","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Escolha a melhor droga ou combinação de drogas indicada no controle da hipertensão\nem vigência da dissecção de aorta:","options":{"A":"Furosemida + betabloqueador.","B":"Nitropussiato de sódio + betabloqueador.","C":"Nitropussiato de sódio isoladamente.","D":"Betabloqueador isoladamente.","E":"Nitropussiato de sódio + nifedipina."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-81956","number":"81956","sourceNumber":"81956","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual das seguintes condições está associada ao aumento da pré-carga ventricular\nesquerda?","options":{"A":"Sepse.","B":"Regurgitação mitral.","C":"Infarto do ventrículo direito.","D":"Desidratação.","E":"Embolia pulmonar."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-80930","number":"80930","sourceNumber":"80930","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São fatores de risco para a ocorrência tanto de doença cardiovascular quanto de\nDiabetes Mellitus:","options":{"A":"Herança genética e consumo excessivo de sal.","B":"Ocupações estressantes e baixa escolaridade.","C":"Ocupações menos qualificadas e obesidade.","D":"Hipercolesterolemia e obesidade.","E":"Sedentarismo e obesidade."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-60829","number":"60829","sourceNumber":"60829","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Compreende sinal muito sugestivo de insuficiência aórtica grave:","options":{"A":"Xantelasmas.","B":"Aracnodactilia.","C":"Sinal de Musset.","D":"Pulso parvus et tardus.","E":"Lesões de Janeway."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-60838","number":"60838","sourceNumber":"60838","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 21 anos, sexo feminino, com história de aumento de volume abdominal há\n2 anos, associado à dispneia de esforço. Ao\nexame físico, paciente em bom estado geral, corada,\nanictérica, hidratada, com estase jugular a 45 graus e sinal de Kussmaul, PA = 100 x 60 mmHg, FC\n\n= 70, RCR sem sopros, com som protodiastólico rude (\"Knock\"), abdome ascítico, fígado a 5 cm\nRCD doloroso, ausência de edema de membros\ninferiores ou estigmas de insuficiência hepática.\nAssinale a alternativa que apresenta a principal hipótese diagnóstica:","options":{"A":"Hepatopatia crônica.","B":"Pericardite constritiva.","C":"Insuficiência cardíaca esquerda.","D":"Insuficiência cardíaca congestiva.","E":"Tromboembolismo pulmonar crônico com insuficiência cardíaca direita."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-61535","number":"61535","sourceNumber":"61535","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"De acordo com as VI diretrizes de Hipertensão Arterial da SBC, as metas pressóricas\nnos pacientes em estágio 1 e 2 com risco\ncardiovascular baixo e médio são:","options":{"A":"PA < 140 x 90 mmHg.","B":"PA = 140 x 90 mmHg.","C":"PA = 130 x 80 mmHg.","D":"PA < 130 x 80 mmHg.","E":"PA = 120 x 80 mmHg."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-60837","number":"60837","sourceNumber":"60837","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação ao tratamento da Hipertensão Arterial Sistêmica, podemos afirmar:","options":{"A":"Baseia-se no tratamento medicamentoso.","B":"O consumo de álcool não deve exceder 30 ml/dia de etanol para homens e o tabagismo deve\nser abandonado.","C":"No tratamento medicamentoso, os diuréticos são a medicação que menos reduz o risco de\neventos cardiovasculares, renais e cerebrovasculares.","D":"Os diuréticos estão indicados para pacientes em estágio 2, em monoterapia e que não\nrespondam a medidas não medicamentosas.","E":"Nas modificações de estilo de vida podemos citar a redução de peso (principalmente da gordura\nperiférica), alimentação saudável, prática de atividade física."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-46731","number":"46731","sourceNumber":"46731","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Nas afirmativas é CORRETO afirmar em relação à Síndrome de Eisenmenger somente\nque:","options":{"A":"No exame clínico não há sinais que caracterizam a síndrome sendo seu achado\necocardiográfico.","B":"O termo Síndrome de Eisenmenger deve ser reservado a pacientes nos quais a doença\npulmonar obstrutiva e a resistência vascular pulmonar é diminuída e reversível.","C":"Um impulso ventricular direto proeminente é sentido na borda paraesternal esquerda ao final da\nexpiração ou na área subcostal no final da inspiração.","D":"A pressão de pulso alarga-se conforme o débito cardíaco diminui.","E":"A ausência de shunt direito-esquerdo torna o paciente inoperável."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-46725","number":"46725","sourceNumber":"46725","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No tratamento da Insuficiência Cardíaca com Fração de Ejeção reduzida é incorreto\nafirmar que:","options":{"A":"As drogas que afetam a ativação excessiva do sistema renina-angiotensina-aldosterona como os\nIECAs e BRAs podem aliviar os sintomas da Insuficiência Cardíaca.","B":"O uso combinado de hidralazina e dinitrato de isosorbida pode ser considerado uma opção\nterapêutica para pacientes com intolerância aos IECAs e BRAs.","C":"A terapia betabloqueadora representa um dos principais avanços no tratamento de pacientes\ncom IC com FE reduzida.","D":"A digoxina é recomendada para pacientes com disfunção sistólica ventricular esquerda com\nfibrilação atrial.","E":"Três betabloqueadores se mostraram efetivos na redução do risco de morte em paciente com IC\ncrônica: o carvedilol, propranolol e metoprolol."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-46718","number":"46718","sourceNumber":"46718","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 72 anos dá entrada em pronto-socorro com história de episódios de\nsíncope e dor torácica. Ao exame físico,\napresenta sopro sistólico mais audível na área aórtica que\ndesaparece sobre o esterno e reaparece sobre o ápice do VE (fenômeno de Gallavardin). O\ndiagnóstico mais provável é:","options":{"A":"Insuficiência Aórtica.","B":"Insuficiência Mitral.","C":"Estenose Mitral.","D":"Insuficiência Tricúspide.","E":"Estenose Aórtica."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-34116","number":"34116","sourceNumber":"34116","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São causas de insuficiência cardíaca com função sistólica preservada, EXCETO:","options":{"A":"Sarcoidose.","B":"Amiloidose.","C":"Cardiomiopatia periparto.","D":"Cardiomiopatia hipertrófica.","E":"Hipertensão arterial."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-34119","number":"34119","sourceNumber":"34119","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São causas de choque cardiogênico, EXCETO:","options":{"A":"Infarto Agudo do Miocárdio.","B":"Arritmias.","C":"Miocardite.","D":"Hemotórax.","E":"Contusão Miocárdica."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-34176","number":"34176","sourceNumber":"34176","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual a etiologia da insuficiência cardíaca no adolescente?","options":{"A":"Doença de Kawasaki/Anomalia de Ebstein.","B":"Coarctação da aorta/síndrome de coração esquerdo.","C":"Febre reumática/Anemia Falciforme.","D":"Doença de Kawasaki/Persistência do canal arterial.","E":"Persistência do canal arterial/Comunicação interventicular."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-34300","number":"34300","sourceNumber":"34300","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"José de 42 anos, veio a primeira consulta na Unidade Saúde da Família em que você\ntrabalha. Refere dores na nuca. Tem índice de Massa Corporal de 28, pressão Arterial de 180 X110\nmmHg. Refere outras aferições também com valores semelhantes, como consta em receituário\npreenchido pelo técnico de enfermagem de sua unidade. Os pais de José são acompanhados na\nunidade por você e a mãe tem hipertensão arterial. José é tabagista, vive com pais e trabalha como\nmotorista de táxi. Em relação ao quadro clínico apresentado por José, podemos afirmar, EXCETO:","options":{"A":"Que ele apresenta Hipertensão Arterial em estágio II.","B":"Você deve orientá-lo sobre medidas não famarcológicas bem como a iniciar terapia\nmedicamentosa para controle da pressão.","C":"José deve ser orientado a parar de fumar e iniciar abordagem breve cognitivo-comportamental\nantitabagismo.","D":"Os exames que devem ser solicitados nesta 1ª. consulta são exame de urina tipo I, potássio\nsérico, glicemia, creatinina sérica, lipidograma, hematócrito e eletroencefalograma.","E":"José deve ser encaminhado ao especialista caso sua hipertensão seja refratária ao tratamento\nou apresente importante lesão de órgão-alvo."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-26441","number":"26441","sourceNumber":"26441","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São drogas utilizadas no tratamento na Insuficiência Cardíaca (IC), que se mostraram\ncapazes de alterar o seu prognóstico,\ndiminuindo a mortalidade, principalmente nos casos mais\ngraves, EXCETO:","options":{"A":"bloqueadores de receptor de angiotensina.","B":"betabloqueadores.","C":"digital.","D":"inibidores de ECA.","E":"espironolactona."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-26442","number":"26442","sourceNumber":"26442","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Algumas situações interferem na avaliação da pressão arterial (PA). Assinale a\nalternativa INCORRETA:","options":{"A":"em pacientes com pseudo-hipertensão, os níveis pressóricos são falsamente elevados devido ao\nenrijecimento arterial","B":"o hiato auscultatório ocorre entre a fase I e II do Korotkoff e pode subestimar a PA sistólica ou\nsuperestimar a diastólica","C":"a hipertensão do avental branco ocorre quando temos medidas pressóricas elevadas no\nconsultório, porém normais à monitoração\nambulatorial da PA (MAPA) ou à monitoração residencial","D":"quando o manguito é muito pequeno para o braço do indivíduo, medidas falsamente elevadas\npodem ocorrer","E":"pseudo-hipertensão e hiato auscultatório são mais comuns em gestantes"},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-26481","number":"26481","sourceNumber":"26481","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São alterações fisiopatológicas do tamponamento cardíaco, EXCETO:","options":{"A":"choque cardiogênico por falha na contração cardíaca","B":"deslocamento da traqueia para a direita por balanço mediastinal","C":"turgência jugular por aumento da pressão venosa central","D":"abafamento de bulhas cardíacas","E":"hipotensão arterial severa sem sinais de hemorragia"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-26685","number":"26685","sourceNumber":"26685","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No diagnóstico de estenose aórtica encontramos como características clínicas e\nhemodinâmicas, exceto:","options":{"A":"angina","B":"Íctus hiperativo deslocado para baixo e para esquerda","C":"síncope","D":"Hipertrofia concêntrica do ventrículo esquerdo","E":"pulso carotídeo retardado e fraco"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-7467","number":"7467","sourceNumber":"7467","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em idosos, a lesão valvar mais frequente e a sua etiologia principal são,\nrespectivamente:","options":{"A":"insuficiência mitral pós-inflamatória.","B":"estenose aórtica por degeneração.","C":"estenose aórtica pós-inflamatória.","D":"insuficiência mitral por degeneração.","E":"insuficiência aórtica por degeneração."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-10045","number":"10045","sourceNumber":"10045","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dona Elsa faz seu tratamento de hipertensão há muitos anos na unidade de saúde da\nfamília onde você trabalha. Hoje, você irá consultar o seu filho Marcelo que acaba de chegar à\ncidade. Marcelo tem 40 anos e descobriu há 3 meses ser hipertenso. Ao exame, está com níveis\npressóricos elevados, apesar do uso correto da medicação, e sobrepeso. Ele refere que sempre\nfica nervoso quando vai ao médico. Você o orienta a, EXCETO:","options":{"A":"Investigar a síndrome do avental branco e pede o MAPA (monitorização ambulatorial da pressão\narterial).","B":"Investiga Hipertensão secundária visto o início súbito da hipertensão antes dos 55 anos de idade\ne a história familiar.","C":"Solicita alguns exames complementares como creatinina sérica, potássio sérico, lipidograma,\nsedimentocospia urinária e eletrocardiograma.","D":"Recomenda dieta com restrição calórica e de sódio.","E":"Orienta a prática regular de exercício físico para controle pressórico e redução de peso."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-7514","number":"7514","sourceNumber":"7514","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Alguns medicamentos anti-hipertensivos em mulheres não-grávidas são mais úteis em\ncondições específicas. Qual destas combinações está contraindicada?","options":{"A":"Inibidores da ECA em diabéticas.","B":"ß-bloqueadores com doenças coronariana coexistente.","C":"Bloqueadores dos canais de cálcio com insuficiência cardíaca esquerda.","D":"ß-bloqueadores com enxaqueca.","E":"Não há combinação que esteja contraindicada."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-10003","number":"10003","sourceNumber":"10003","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A causa mais comum de um derrame pericárdico crônico é:","options":{"A":"Hipotireoidismo.","B":"Neoplasias.","C":"Viral.","D":"Tuberculose.","E":"Uremia."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-10005","number":"10005","sourceNumber":"10005","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São causas de pulso paradoxal, EXCETO:","options":{"A":"Asma Brônquica.","B":"Choque hipovolêmico.","C":"Tamponamento cardíaco.","D":"DPOC crônico.","E":"Regurgitação aórtica."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-284568","number":"284568","sourceNumber":"284568","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Mulher, 60 anos de idade, é acompanhada na Unidade de Saúde da Família (USF) por\ndiabetes mellitus tipo 2 e hipertensão arterial sistêmica. Na primeira visita à USF, há cerca de 6\nmeses, a PA estava em 182 x 100 mmHg. Atualmente, assintomática. Nega outras comorbidades.\nEm uso regular de metformina 850 mg duas vezes ao dia, losartana 50 mg de 12/12h e anlodipina\n10 mg ao dia, há cerca de 6 meses. Ao exame físico, apresenta-se em bom estado geral, com FC:\n70 bpm, PA: 166 x 96 mmHg em ambos os membros superiores e glicemia capilar de 110 mg/dl.\n\nPulsos palpáveis e simétricos. Exame segmentar sem alterações. Traz monitorização residencial da\npressão arterial, com PAS entre 140 e 172 mmHg e PAD entre 90 e 96 mmHg. Indique a\nclassificação para a pressão dessa paciente na primeira visita à Unidade de Saúde da Família.","options":{"A":"Pressão arterial elevada.","B":"Hipertensão arterial sistêmica estágio 1.","C":"Hipertensão arterial sistêmica estágio 2.","D":"Hipertensão arterial sistêmica estágio 3."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-284569","number":"284569","sourceNumber":"284569","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Mulher, 60 anos de idade, é acompanhada na Unidade de Saúde da Família (USF) por\ndiabetes mellitus tipo 2 e hipertensão arterial sistêmica. Na primeira visita à USF, há cerca de 6\nmeses, a PA estava em 182 x 100 mmHg. Atualmente, assintomática. Nega outras comorbidades.\nEm uso regular de metformina 850 mg duas vezes ao dia, losartana 50 mg de 12/12h e anlodipino\n10 mg ao dia, há cerca de 6 meses. Ao exame físico, apresenta-se em bom estado geral, com FC:\n70 bpm, PA: 166 x 96 mmHg em ambos os membros superiores e glicemia capilar de 110 mg/dl.\n\nPulsos palpáveis e simétricos. Exame segmentar sem alterações. Traz monitorização residencial da\npressão arterial, com PAS entre 140 e 172 mmHg e PAD entre 90 e 96 mmHg. Indique a conduta\nmais adequada para otimizar o esquema anti-hipertensivo dessa paciente.","options":{"A":"Introdução de hidroclorotiazida.","B":"Introdução de captopril.","C":"Troca da losartana por hidralazina.","D":"Aumento das doses de losartana e anlodipino."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-284570","number":"284570","sourceNumber":"284570","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Mulher, 60 anos de idade, é acompanhada na Unidade de Saúde da Família (USF) por\ndiabetes mellitus tipo 2 e hipertensão arterial sistêmica. Na primeira visita à USF, há cerca de 6\nmeses, a PA estava em 182 x 100 mmHg. Atualmente, assintomática. Nega outras comorbidades.\nEm uso regular de metformina 850 mg duas vezes ao dia, losartana 50 mg de 12/12h e anlodipino\n10 mg ao dia, há cerca de 6 meses. Ao exame físico, apresenta-se em bom estado geral, com FC:\n70 bpm, PA: 166 x 96 mmHg em ambos os membros superiores e glicemia capilar de 110 mg/dl.\n\nPulsos palpáveis e simétricos. Exame segmentar sem alterações. Traz monitorização residencial da\npressão arterial, com PAS entre 140 e 172 mmHg e PAD entre 90 e 96 mmHg. Determine as metas\nde pressão arterial sistólica e diastólica para essa paciente, segundo a Sociedade Brasileira de\nCardiologia e a Sociedade Brasileira de Diabetes.","options":{"A":"PAS < 120 e PAS < 70 mmHg.","B":"PAS < 130 e PAD < 80 mmHg.","C":"PAS < 135 e PAD < 85 mmHg.","D":"PAS < 140 e PAD < 90 mmHg."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-49290","number":"49290","sourceNumber":"49290","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem, 25 anos de idade, vem há um mês com cãibras e fadiga muscular, as quais\natribui a início de atividade física.\nRelata níveis elevados de PA em exames anteriores. Tem história\nfamiliar de hipertensão e pai faleceu aos 42 anos de idade de AVC hemorrágico. No exame,\napresenta IMC: 25, mucosas coradas, hidratado, PA: 160 x 100 mmHg, sem variação entre os\nmembros. Ausculta cardíaca e respiratória sem alterações, abdome sem visceromegalias e\nextremidades sem edemas, sem sopros à ausculta. Traz exames: hemograma normal, creatinina:\n0,9 mg/dl, ureia: 29 mg/dl. A melhor conduta inicial para esse paciente é dosar:","options":{"A":"Cortisol sérico e urinário;","B":"Potássio sérico e urinário;","C":"Metanefrinas na urina;","D":"Sódio em urina de 24 horas;","E":"ACTH sérico."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-49296","number":"49296","sourceNumber":"49296","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem, 57 anos de idade, em revisão no ambulatório, após internamento em\nemergência por edema agudo de pulmão há 15\ndias, com dispneia aos esforços extra-habituais.\nApresenta TA: 150 x 85 mmHg, pulso radial: 84 bpm, FR: 22 ipm. Mucosas coradas, sem estase de\njugulares. Aparelho respiratório: pulmões limpos. Aparelho cardiovascular: ictus no 5º espaço\nintercostal, 2 cm fora da linha medioclavicular, impulsivo. Ausculta: bulhas rítmicas, B2\nhiperfonese\nde B2 e presença de B4. Abdomên e extremidades sem alterações. Traz ecocardiograma: fração\nde ejeção de 55%, átrio esquerdo pouco aumentado, escape sistólico mitral com diâmetro valvular\nnormal, hipertrofia concêntrica do ventrículo esquerdo com alteração de relaxamento ventricular. A\ndroga menos útil no caso é:","options":{"A":"furosemida.","B":"captopril.","C":"digoxina.","D":"amlodipina.","E":"propranolol."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-35013","number":"35013","sourceNumber":"35013","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No tratamento do paciente com ICC crônica descompensada, é importante reconhecer\nem que perfil clínico-hemodinâmico ele se\nencontra , pois isso abre algoritmos de tratamento e\nfacilita a abordagem terapêutica. Assim, o paciente no:","options":{"A":"perfil A, traduz paciente congesto e bem perfundido, devendo ser priorizado diuréticos de alça.","B":"perfil B, traduz paciente sem congestão sistêmica e bem perfundido, devendo ser priorizado\nvasodilatadores.","C":"perfil C, traduz paciente congesto e mal perfundido, devendo ser priorizado o uso de digitálicos\ne\ndiuréticos.","D":"perfil D, traduz paciente em baixo débito cardíaco, devendo ser priorizado levosimedan para\ncompensação mais rápida.","E":"perfil L, traduz paciente mal perfundido e sem evidência de congestão sistêmica, sendo\nnecessário inicialmente desafio volêmico."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-34969","number":"34969","sourceNumber":"34969","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente portadora da Síndrome de Turner vem à consulta de rotina, quando é\nobservada diminuição da amplitude dos pulsos\narteriais nos membros inferiores, associada à\npresença de pulsos amplos e hipertensão arterial nos membros superiores, hiperfonese da 2ª bulha\nnas áreas aórtica e mitral; estalido protossistólico aórtico, principalmente na área mitral, sopro\nocupando a mesotelessístole e avançando até a protomesodiástole na região do dorso esquerdo. A\nprincipal suspeita diagnóstica é de:","options":{"A":"miocardite viral.","B":"endocardite infecciosa.","C":"estenose da pulmonar.","D":"coarctação de aorta.","E":"derrame pericárdico."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27432","number":"27432","sourceNumber":"27432","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A aferição da tensão arterial pode ser subestimada quando:","options":{"A":"for realizada após ingesta de bebidas à base de cola.","B":"forem realizadas duas auferições com menos de 2 minutos de intervalo.","C":"tiver o manguito de borracha com largura de 60% da circunferência do braço.","D":"for realizada imediatamente após atividade física.","E":"a insuflação do manguito estiver acima de 50 mmHg da sistólica palpatória."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27444","number":"27444","sourceNumber":"27444","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem, 22 anos de idade, apresenta-se com dor retroesternal e dispneia aos esforços\nhabituais. Há 3 semanas iniciou febre com irritação em orofaringe, dores musculares e diarreia.\n\nApós 5 dias passou a febre, persistindo astenia. Há 1 semana iniciou dispneia ao deambular, com\ndor retroesternal e tosse seca. Surgiram dor\nabdominal à alimentação e distensão abdominal. Nega\nuso de drogas, tabagismo ou etilismo. Ao exame físico, TA: 120 x 70 mmHg, pulso radial: 122 bpm,\narrítmico com ES. Temp: 37,5°C, mucosas coradas, orofaringe sem exsudatos. Estase de jugulares\na 45°. Pulmões com crépitos em bases. Precórdio ativo, com impulsão paraesternal esquerda. Ictus\nno 6° espaço intercostal esquerdo linha hemiclavicular, duas polpas digitais. Bulhas arrítmicas à\ncusta de extrassístoles sem pausa compensatória, presença de B3 e B4 sem sopros. Abdome\ndoloroso à palpação em HD, com fígado percutível a 5 cm do RCD e 7 cm do AX. Espaço de\nTraube livre. Extremidades aquecidas e acianóticas com edema de MMII até terço médio das\npernas. Eletrocardiograma mostra taquicardia sinusal com extrassístoles supraventriculares e\nsupradesnível de ST de 3 mm em DI, DII, AVL, e precordiais esquerdas. VHS 43 mm na primeira\nhora. Proteína C reativa: 6 mg/dl (VN até 8 mg/dl). Dos exames complementares, relacionados a\nseguir, o de maior valia no manejo desse paciente é:","options":{"A":"antiestreptolisina O.","B":"ecocardiograma.","C":"teste ergométrico.","D":"troponina I.","E":"cineangiocoronariografia."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27446","number":"27446","sourceNumber":"27446","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem, 22 anos de idade, apresenta-se com dor retroesternal e dispneia aos esforços\nhabituais. Há 3 semanas iniciou febre com irritação em orofaringe, dores musculares e diarreia.\n\nApós 5 dias passou a febre, persistindo astenia. Há 1 semana iniciou dispneia ao deambular, com\ndor retroesternal e tosse seca. Surgiram dor\nabdominal à alimentação e distensão abdominal. Nega\nuso de drogas, tabagismo ou etilismo. Ao exame físico, TA: 120 x 70 mmHg, pulso radial: 122 bpm,\narrítmico com ES. Temp: 37,5°C, mucosas coradas, orofaringe sem exsudatos. Estase de jugulares\na 45°. Pulmões com crépitos em bases. Precórdio ativo, com impulsão paraesternal esquerda. Ictus\nno 6° espaço intercostal esquerdo linha hemiclavicular, duas polpas digitais. Bulhas arrítmicas à\ncusta de extrassístoles sem pausa compensatória, presença de B3 e B4 sem sopros. Abdome\ndoloroso à palpação em HD, com fígado percutível a 5 cm do RCD e 7 cm do AX. Espaço de\nTraube livre. Extremidades aquecidas e acianóticas com edema de MMII até terço médio das\npernas. Eletrocardiograma mostra taquicardia sinusal com extrassístoles supraventriculares e\nsupradesnível de ST de 3 mm em DI, DII, AVL, e precordiais esquerdas. VHS 43 mm na primeira\nhora. Proteína C reativa: 6 mg/dl (VN até 8 mg/dl). Quanto à etiologia do caso, é correto afirmar:","options":{"A":"Vírus coxsackie é o agente mais comum.","B":"Espasmo coronariano, sem lesão estrutural, é a maior possibilidade.","C":"Homocisteinemia é o fator mais provável nessa faixa etária.","D":"Tratamento com penicilina para estreptococos beta-hemolíticos está indicado.","E":"Tuberculose é uma causa frequente do processo."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27449","number":"27449","sourceNumber":"27449","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem, 22 anos de idade, apresenta-se com dor retroesternal e dispneia aos esforços\nhabituais. Há 3 semanas iniciou febre com irritação em orofaringe, dores musculares e diarreia.\n\nApós 5 dias passou a febre, persistindo astenia. Há 1 semana iniciou dispneia ao deambular, com\ndor retroesternal e tosse seca. Surgiram dor\nabdominal à alimentação e distensão abdominal. Nega\nuso de drogas, tabagismo ou etilismo. Ao exame físico, TA: 120 x 70 mmHg, pulso radial: 122 bpm,\narrítmico com ES. Temp: 37,5°C, mucosas coradas, orofaringe sem exsudatos. Estase de jugulares\na 45°. Pulmões com crépitos em bases. Precórdio ativo, com impulsão paraesternal esquerda. Ictus\nno 6° espaço intercostal esquerdo linha hemiclavicular, duas polpas digitais. Bulhas arrítmicas à\ncusta de extrassístoles sem pausa compensatória, presença de B3 e B4 sem sopros. Abdome\ndoloroso à palpação em HD, com fígado percutível a 5 cm do RCD e 7 cm do AX. Espaço de\nTraube livre. Extremidades aquecidas e acianóticas com edema de MMII até terço médio das\npernas. Eletrocardiograma mostra taquicardia sinusal com extrassístoles supraventriculares e\nsupradesnível de ST de 3 mm em DI, DII, AVL, e precordiais esquerdas. VHS 43 mm na primeira\nhora. Proteína C reativa: 6 mg/dl (VN até 8 mg/dl). Entre os achados diagnósticos no ECG relativos\nàs extrassístoles supraventriculares, nesse caso, não se encontra:","options":{"A":"complexo QRS de duração normal.","B":"vetor QRS com direção diferente dos batimentos normais.","C":"ausência de onda P.","D":"onda P de morfologia alterada.","E":"ausência de pausa após uma extrassístole."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27452","number":"27452","sourceNumber":"27452","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem, 22 anos de idade, apresenta-se com dor retroesternal e dispneia aos esforços\nhabituais. Há 3 semanas iniciou febre com irritação em orofaringe, dores musculares e diarreia.\n\nApós 5 dias passou a febre, persistindo astenia. Há 1 semana iniciou dispneia ao deambular, com\ndor retroesternal e tosse seca. Surgiram dor\nabdominal à alimentação e distensão abdominal. Nega\nuso de drogas, tabagismo ou etilismo. Ao exame físico, TA: 120 x 70 mmHg, pulso radial: 122 bpm,\narrítmico com ES. Temp: 37,5°C, mucosas coradas, orofaringe sem exsudatos. Estase de jugulares\na 45°. Pulmões com crépitos em bases. Precórdio ativo, com impulsão paraestemal esquerda. Ictus\nno 6° espaço intercostal esquerdo linha hemiclavicular, duas polpas digitais. Bulhas arrítmicas à\ncusta de extrassístoles sem pausa compensatória, presença de B3 e B4 sem sopros. Abdome\ndoloroso à palpação em HD, com fígado percutível a 5 cm do RCD e 7 cm do AX. Espaço de\nTraube livre. Extremidades aquecidas e acianóticas com edema de MMII até terço médio das\npernas. Eletrocardiograma mostra taquicardia sinusal com extrassístoles supraventriculares e\nsupradesnível de ST de 3 mm em DI, DII, AVL, e precordiais esquerdas. VHS 43 mm na primeira\nhora. Proteína C reativa: 6 mg/dl (VN até 8 mg/dl). A medida farmacológica mais importante no\ntratamento desse paciente é indicação de:","options":{"A":"digitálico.","B":"diurético de alça.","C":"penicilina benzatina.","D":"aspirina.","E":"nitrato."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27482","number":"27482","sourceNumber":"27482","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente, 12 anos de idade, vem ao ambulatório pela primeira vez, com o propósito de\nrealizar exame de rotina, pois sua mãe está preocupada com a proximidade da menarca. Ao\nexame, foi notada TA: 130 X 100 mmHg, sem qualquer outra anormalidade. A melhor conduta a ser\nadotada, nesse caso, é:","options":{"A":"solicitar sumário de urina e provas de função renal.","B":"marcar retorno, pelo menos, mais 2 vezes na mesma semana para confirmar a pressão arterial.","C":"solicitar ultrassonografia renal e sumário de urina.","D":"suspender o sal da dieta e usar diurético.","E":"prescrever captopril em dose mínima e marcar retorno após uma semana."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-11132","number":"11132","sourceNumber":"11132","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A aferição correta da tensão arterial, por técnica padronizada, vem sendo enfatizada\ncomo medida de qualidade de atenção médica. São\nrecomendações que fazem parte da\npadronização do Ministério da Saúde, exceto:","options":{"A":"uso de manguito com largura correspondente a 40% da circunferência do braço","B":"intervalo mínimo de 1 minuto entre as duas aferições","C":"registro habitual da tensão arterial diastólica no momento do desaparecimento dos sons\n(Korotkoff V)","D":"arredondamento de no máximo 5 mmHg no registro dos valores da tensão arterial","E":"tomada sistemática da tensão arterial sistólica palpatória antes da auscultatória"},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-18040","number":"18040","sourceNumber":"18040","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem, 52 anos de idade, mulato escuro, com dispneia progressiva, palpitações,\nedema de MMII ascendente há 5 meses.\nEncontra-se com dispneia aos mínimos esforços e\nortopneia. Ao exame físico, TA: 110x70mmHg. PR: 108bpm, fino, rítmico e alternante, FR: 31ipm.\nApresenta estase de jugulares a 45º até ângulo da mandíbula. Precórdio ativo, com ictus cordis 3\ncm para fora da linha hemiclavicular, no 6 espaço intercostal. Ausculta mostra ritmo em 3 tempos\ncom terceira bulha. Creptos em bases de ambos os hemitóraces. Abdome com fígado a 5 cm do\nRCD e 8 cm do AX. Edema de MMII até nível de joelhos e cianose de extremidades. Das drogas\nrelacionadas a seguir, se usada no caso, a que menos interfere na sobrevida desse paciente é:","options":{"A":"Captopril.","B":"Losartan.","C":"Digoxina.","D":"Carvedilol.","E":"Amilodipina."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-15752","number":"15752","sourceNumber":"15752","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente, sexo masculino, 38 anos de idade, com altura de 1,70m e peso de 85kg,\ntabagista, assintomático. Realizou exame de rotina,\nque incluiu dosagem de glicemia de jejum de\n110mg/dl e glicemia pós-prandial de duas horas de 145mg/dl, a avaliação posterior incluiu uma\ndosagem de HbA1C, cujo resultado foi de 6,0%. A dosagem de colesterol total foi de 239mg/dl, com\nHDL de 42mg/dl e triglicérides de 315mg/dl. A PA. foi de 130X80mmHg em três tomadas, em\nmomentos diversos. A melhor conduta para esse paciente é:","options":{"A":"iniciar metformina oral.","B":"iniciar sibutramina oral.","C":"indicar programa de redução de peso e exercícios físicos.","D":"iniciar acarbose oral.","E":"iniciar rosiglitazona oral."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-15808","number":"15808","sourceNumber":"15808","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente, 20 anos de idade, G1P0A0, vem referindo gestação de 24 semanas, diz ser\nportadora de cardiopatia tipo CIV, com dispneia a esforços, como subir ladeiras ou escadas,\nlimitação que não apresentava antes da gestação. Ao ecocardiograma, evidencia-se defeito septal\nventricular sem inversão de fluxo e hipertensão pulmonar leve com fração de ejeção de 55%.\n\nSegundo a NYHA, a paciente se encontra em classe funcional:","options":{"A":"1","B":"2","C":"3","D":"4","E":"5"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-343336","number":"343336","sourceNumber":"343336","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os inibidores da proteína co-transportadora SGLT2 (ISGLT2) inaugurou uma nova era\nno tratamento da insuficiência cardíaca IC em\npessoas com diabetes.","options":{"A":"Além de controlar efetivamente a glicemia, esses fármacos apresentam efeito importante na\nfisiopatologia da IC, reduzindo de forma expressiva as internações por insuficiência cardíaca e a\nmortalidade cardiovascular.","B":"Além de não controlar efetivamente a glicemia, esses fármacos apresentam efeito importante na\nfisiopatologia da IC, reduzindo de forma expressiva as internações por insuficiência cardíaca e a\nmortalidade cardiovascular.","C":"Além de controlar efetivamente a glicemia, esses fármacos apresentam efeito importante na\nfisiopatologia da IC, aumentando de forma expressiva as internações por insuficiência cardíaca e a\nmortalidade cardiovascular.","D":"Além de controlar efetivamente a glicemia, esses fármacos apresentam efeito importante na\nfisiopatologia da IC, reduzindo de forma expressiva as internações por insuficiência cardíaca e a\nnão a mortalidade cardiovascular."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-281849","number":"281849","sourceNumber":"281849","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Na encefalopatia hipertensiva pode, posteriormente, surgir alterações adequadamente\ndescritas no item:","options":{"A":"Nunca do estado mental e sim campimétricas, fotopsia, visão turva, alucinações visuais, crises\nconvulsivas generalizadas, hiperreflexia e sinais de hipertensão intracraniana.","B":"Do estado mental e campimétricas, fotopsia, visão turva, alucinações visuais, crises convulsivas\ngeneralizadas, hiperreflexia e nunca sinais de hipertensão intracraniana.","C":"Do estado mental e não campimétricas, fotopsia ou visão turva.","D":"Do estado mental e campimétricas, fotopsia, visão turva, alucinações visuais, crises convulsivas\ngeneralizadas, hiperreflexia e sinais de hipertensão intracraniana."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-281852","number":"281852","sourceNumber":"281852","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No contexto da Insuficiência Mitral Secundária, há uma sobrecarga adicional ao VE\npela regurgitação mitral, culminando num pior prognóstico. As principais etiologias são: doença\narterial coronária (IM isquêmica) e miocardiopatia dilatada (dilatação anular e/ou mau\nposicionamento). Sendo correto o item:","options":{"A":"Por esses motivos, o tratamento ideal é controverso, uma vez que a correção valvar não é\ncurativa.","B":"Por esses motivos, o tratamento ideal não é controverso, uma vez que a correção valvar não é\ncurativa.","C":"Por esses motivos, o tratamento ideal é controverso, uma vez que a correção valvar é curativa.","D":"Por esses motivos, o tratamento ideal nunca é controverso, uma vez que a correção valvar é\ncurativa."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-281854","number":"281854","sourceNumber":"281854","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No momento em que aparecem as manifestações neurológicas da encefalopatia\nhipertensiva, geralmente, a PAD encontra-se acima de\n125 mmHg. Podemos indicar como correto:","options":{"A":"A resolução do quadro, quer do ponto de vista clínico, mas não do ponto de vista de imagem,\ndemora, em média, várias semanas após o controle da PA.","B":"A resolução do quadro, quer do ponto de vista clínico, quer do ponto de vista de imagem,\ndemora, em média, várias semanas após o controle da PA.","C":"A resolução do quadro, quer do ponto de vista clínico, quer do ponto de vista de imagem,\ndemora, em média, várias meses após o controle da PA.","D":"A resolução do quadro, quer do ponto de vista clínico, quer do ponto de vista de imagem,\ndemora, em média, várias semanas antes do controle da PA."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-281859","number":"281859","sourceNumber":"281859","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A Ressonância Magnética é o exame diagnóstico de maior valor para o diagnóstico da\nencefalopatia hipertensiva. Sendo correto o item:","options":{"A":"Na sequência T2, evidenciam-se lesões hiperintensas na substância branca com\ncomprometimento preferencial das regiões parieto-occipitais.","B":"Na sequência T2, evidenciam-se lesões hipointensas na substância branca com\ncomprometimento preferencial das regiões parieto-occipitais.","C":"Na sequência T2, evidenciam-se lesões hiperintensas na substância branca sem o\ncomprometimento preferencial das regiões parieto-occipitais.","D":"Na sequência T2, não evidenciam-se lesões hiperintensas na substância branca com\ncomprometimento preferencial das regiões parieto-occipitais."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-283855","number":"283855","sourceNumber":"283855","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo feminino, 52 anos de idade, em investigação de alterações cardíacas.\nApós ecocardiograma, notou-se pressão arterial <\n140 x 90 mmHg em duas aferições em\nconsultório realizadas pelo médico, em ambos os braços, mas com Monitorização Ambulatorial da\nPressão Arterial (MAPA) com valores médios diurnos em torno de 146 x 92 mmHg. A alternativa\nque contém o diagnóstico CORRETO desse caso clínico é:","options":{"A":"Crise hipertensiva.","B":"Hipertensa controlada.","C":"Normotensa verdadeira.","D":"Hipertensão Arterial Sistêmica mascarada.","E":"Hipertensão Arterial Sistêmica do avental branco."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-281883","number":"281883","sourceNumber":"281883","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 52 anos, portadora de insuficiência cardíaca com fração de ejeção\npreservada compensada é submetida à correção de\nhérnia incisional após liberação do\ncardiologista e avaliação pré-anestesica. O tempo do procedimento cirúrgico foi de 2 horas, tempo\ntotal de anestesia geral balanceada de 2 horas e 30 minutos, com volume total infundido de 1.500\nml de cristaloides, sem necessidade de transfusão de hemoderivados, diurese quantificada em\ncoletor de urina por sonda de demora de 600 ml. É extubada sem intercorrências, porém na sala de\nrecuperação anestésica queixa-se de dispneia e palpitações. Nega dor torácica. Sem nenhum\nsintoma neurológico. Sinais vitais: pressão arterial: 180/70 mmHg, frequência cardíaca: 116 bpm,\nfrequência respiratória: 18 irpm, saturação periférica de oxigênio em ar ambiente: 90%, temperatura\naxilar: 36.5ºC. Foi submetida ao eletrocardiograma e à radiografia de tórax abaixo. O provável\nmotivo dos sintomas acima relatados são:","options":{"A":"Taquicardia supraventricular e atelectasia.","B":"Taquicardia supraventricular e pneumonia.","C":"Fibrilação atrial e congestão pulmonar.","D":"Fibrilação atrial e atelectasia."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/281883.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215572","number":"215572","sourceNumber":"215572","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Não é incomum que pacientes com insuficiência cardíaca crônica em classe funcional II\n(NYHA ? New York Heart Association) se encontrem autolimitados, ou seja, tenham tal classe\nfuncional subestimada, por não se submeterem a esforços no dia a dia. NÃO está correto apenas\num item. Marque-o.","options":{"A":"No momento da avaliação do paciente, um raciocínio individualizado, envolvendo fatores\nprognósticos, é fundamental.","B":"Tal raciocínio deve ir além da estimativa de classe funcional, incluindo dados de história,\netiologia, exame físico, exames complementares, avaliação hemodinâmica e tolerância às\nmedicações com impacto em mortalidade.","C":"A avaliação do desempenho físico, por meio do teste da caminhada de 6 minutos ou do teste\ncardiopulmonar, estabelece de forma menos objetiva a real situação funcional nestes cenários.","D":"A correta avaliação prognóstica implica na seleção adequada de terapias adicionais por meio do\nencaminhamento a centros especializados em IC, bem como a indicação de estratégias mais\navançadas de tratamento."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215578","number":"215578","sourceNumber":"215578","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Pacientes com Insuficiência Cardíaca (IC) e disfunção ventricular sistólica, que têm\nbloqueio atrioventricular com indicação de marca- passo, a Terapia de ressincronização cardíaca e\ncardiodesfibrilador implantável TRC (estímulo biventricular). Indique o item ERRADO nesse\ncontexto.","options":{"A":"Pacientes com FA sintomática com indicação de ablação atrioventricular não parecem ter\nbenefício sobre morbidade quando recebem estímulo biventricular.","B":"Ocorre benefício com TRC (estímulo biventricular) demonstrado.","C":"Este efeito ocorreu, prioritariamente, no desfecho clínico de visitas à emergência ou\nhospitalização por IC.","D":"A eficácia da TRC com benefícios clínicos inquestionáveis relacionados à melhora de sintomas e\nda qualidade de vida, redução de admissões\nhospitalares e melhora da sobrevida."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215589","number":"215589","sourceNumber":"215589","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Nas indicações de marca-passo convencional e/ou cardiodesfibrilador implantável, os\nestudos preliminares não randomizados sugerem que está CORRETO um item. Indique-o:","options":{"A":"Pacientes com Insuficiência Cardíaca (IC) e disfunção ventricular esquerda, que tenham\nmarca-passo convencional ou estimulação\npersistente de Cardiodesfibrilador Implantável (CDI), e\napresentem piora clínica e/ou ecocardiográfica clara não podem ter benefício com upgrade para\n(TRC) Terapia de dessincronizarão cardíaca e cardiodesfibrilador implantável (TRC) (estímulo\nbiventricular).","B":"Pacientes com Insuficiência Cardíaca (IC) e disfunção ventricular esquerda, que tenham\nmarca-passo convencional ou estimulação\npersistente de Cardiodesfibrilador Implantável (CDI), e\n\napresentem piora clínica e/ou ecocardiográfica clara podem ter benefício com upgrade para (TRC)\nTerapia de dessincronizarão cardíaca e cardiodesfibrilador implantável (TRC) (estímulo\nbiventricular).","C":"Pacientes com Insuficiência Cardíaca (IC) e disfunção ventricular esquerda, que tenham\nmarca-passo convencional ou estimulação\npersistente de Cardiodesfibrilador Implantável (CDI), e\napresentem piora clínica e/ou ecocardiográfica leve podem ter benefício com upgrade para (TRC)\nTerapia de dessincronizarão cardíaca e cardiodesfibrilador implantável (TRC) (estímulo\nbiventricular).","D":"Pacientes com Insuficiência Cardíaca (IC) e disfunção ventricular esquerda, que tenham\nmarca-passo convencional ou estimulação\npersistente de Cardiodesfibrilador Implantável (CDI), e\n\napresentem melhora ecocardiográfica clara pode ter benefício com upgrade para (TRC) Terapia de\ndessincronizarão cardíaca e cardiodesfibrilador implantável (TRC) (estímulo biventricular)."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215595","number":"215595","sourceNumber":"215595","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A MAPA pode dar informações clínicas valiosas em pacientes idosos, como nos casos\nde suspeita de hipotensão arterial ortostática,\npós-prandial, medicamentosa e situacional. É\nCORRETO que, no idoso, o descenso da PA durante o sono:","options":{"A":"Não é relacionado com a redução da resistência vascular periférica, enquanto no jovem esse\nfenômeno é relacionado com a redução do débito cardíaco.","B":"É relacionado com ao aumento da resistência vascular periférica, enquanto no jovem esse\nfenômeno é relacionado com a redução do débito cardíaco.","C":"É relacionado com a redução da resistência vascular periférica, enquanto no jovem esse\nfenômeno não é relacionado com a redução do débito cardíaco.","D":"É relacionado com a redução da resistência vascular periférica, enquanto no jovem esse\nfenômeno é relacionado com a redução do débito cardíaco."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215613","number":"215613","sourceNumber":"215613","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A hipertensão matinal atraiu atenção por causa da estreita relação com risco\ncardiovascular como condições caracterizadas por\nvalores elevados de PA, podem causar eventos\nem idosos e, por meio da MAPA, é possível identificá-los e definir a melhor forma de tratamento.\n\nEstá CORRETO que, em idosos, verificou-se que:","options":{"A":"A elevação matinal precoce da PA acima de 75 mmHg estava vinculada à maior prevalência de\nacidente vascular encefálico isquêmico.","B":"A redução matinal precoce da PA acima de 55 mmHg estava vinculada à maior prevalência de\nacidente vascular encefálico isquêmico.","C":"A elevação matinal precoce da PA acima de 55 mmHg estava vinculada à menor prevalência de\nacidente vascular encefálico isquêmico.","D":"A elevação matinal precoce da PA acima de 55 mmHg estava vinculada à maior prevalência de\nacidente vascular encefálico isquêmico."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-215615","number":"215615","sourceNumber":"215615","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A MAPA pode dar informações clínicas valiosas em pacientes idosos, como nos casos\nde suspeita de hipotensão arterial ortostática,\npós-prandial, medicamentosa e situacional, bem\ncomo na avaliação de disautonomia e síncopes. Indique a CORRETA.","options":{"A":"Nos idosos, algumas limitações devem ser salientadas. O enrijecimento arterial próprio da idade\ntende a superestimar a PA medida pelo método oscilométrico e, consequentemente, na presença\nde pseudo-hipertensão, a MAPA está sujeita a erros.","B":"A presença de hiato auscultatório, comum nos idosos, mas que sendo usado o método\noscilométrico não resultará em limitações.","C":"Não se aceitam para os idosos os mesmos valores de normalidade da MAPA adotados para os\nadultos não idosos.","D":"A redução do descenso da PA durante o sono, a pressão de pulso aumentada e a elevação\nmatinal precoce da PA, rara nos idosos, relacionam-se a aumento do risco cardiovascular."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-218190","number":"218190","sourceNumber":"218190","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Sobre a atenção à Hipertensão Arterial Sistêmica (HAS) e às doenças crônicas não\ntransmissíveis, analise as assertivas e identifique com V as verdadeiras e com F as falsas. ( ) Os\npacientes com pré-hipertensão arterial e comorbidades devem ser tratados. O grupo de\nmedicamentos com mais evidências científicas e que deve ser o tratamento de escolha são os\nBetabloqueadores, cujo uso recomendado é, exclusivo inicialmente, até que o teste terapêutico\nmostre a necessidade de associação de mais algum medicamento, que pode ser qualquer um\ndentre os Tiazídicos. inibidores da ECA ou bloqueadores do canal de cálcio. ( ) Todos os adultos\ndevem ter sua PA aferida como medida de rastreamento e uma PAS ? 130 mmHg e/ou PAD ? 80\nmmHg caracteriza HAS. A decisão do início do tratamento farmacológico deve se basear no cálculo\ndo risco cardiovascular pelo escore global de Framingham tendo como alvo terapêutico uma PA <\n120/80 mmHg. É recomendado o início de terapia combinada (2 anti-hipertensivos), se HAS estágio\n2, e/ou se a PA medida estiver acima da meta em mais de 20/10 mmHg (sistólica/diastólica). Os\nfármacos de primeira linha são os Tiazídicos; inibidores da ECA ou bloqueadores do canal de cálcio\ne Betabloqueadores. ( ) O manejo da pessoa com HAS exige a estratificação de seu risco e\nvulnerabilidade, sendo o escore de Framingham ou o QRisk2, e, também, a Pirâmide de Risco para\nanalisar a capacidade de autocuidado, grau de confiança e o apoio que as pessoas têm para cuidar\nde si mesmas, etc, ferramentas importantíssimas para a tomada de decisão junto com o usuário.\n\nNão se recomenda o início do tratamento medicamentoso, antes de se tentar as intervenções não\nmedicamentosas para pessoas com PAS em até 159 ou 99 (grau I) se não elas não tiverem risco\ncardiovascular maior que 20%, ou diabetes mellitus, ou lesão de órgão alvo ou, ainda, doença\ncardiovascular estabelecida. A alternativa que contém a sequência CORRETA, de cima para baixo,\né:","options":{"A":"V, F, V.","B":"V, F, F.","C":"F, V, F.","D":"F, F, V.","E":"F, V, V."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-181182","number":"181182","sourceNumber":"181182","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um grande número de pacientes procura serviços de Emergência devido à Hipertensão\nArterial. Considerando os conceitos de Urgência\nHipertensiva (UH), Emergência Hipertensiva (EH)\ne Crise Hipertensiva, qual item não se mostra adequado?","options":{"A":"A sobrevida de até 5 anos é significantemente maior em indivíduos com UH do que com EH.","B":"Ausência de descenso noturno associa-se a maior risco de Lesão Órgão Alvo e consequente\ndisfunção endotelial, situação envolvida na\nelevação aguda da PA.","C":"Pacientes com queixas de cefaleia, dor torácica atípica, dispneia, estresse psicológico agudo e\nsíndrome de pânico associados à PA elevada não caracterizam UH ou EH, mas, na realidade, uma\npseudocrise hipertensiva,","D":"O tratamento pseudocrise hipertensiva deve ser realizado com medicações endovenosas\npreferencialmente e conscientização da adesão ao tratamento."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-181202","number":"181202","sourceNumber":"181202","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O quadro de Hipertensão Arterial Resistente (HAR) é definido de maneira adequado por\ndiversos fatores. Para o diagnóstico de HAR é necessária medida ambulatorial de PA e verificação\nsistemática de adesão, sendo INCORRETO apenas:","options":{"A":"PA de consultório não controlada apesar do uso de três ou mais anti-hipertensivos em doses\ninadequadas, incluindo-se preferencialmente um DIU, ou em uso de quatro ou mais medicamentos\ncom controle pressórico.","B":"Quando não inclui a verificação sistemática da terapêutica e da adesão, essa situação é melhor\ndefinida como HAR aparente (pseudorresistência).","C":"A identificação da HAR verdadeira é fundamental para estabelecer abordagens específicas.","D":"Estudos populacionais estimam prevalência em 12% da população hipertensa."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-162511","number":"162511","sourceNumber":"162511","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Josefina, 56 anos, vem para consulta do HIPERDIA, na Unidade de Saúde da Família e\né atendida por um médico residente. Ela está\npreocupada e relata estar usando as medicações\n\"direitinho\" como foram prescritas, que faz uso das medicações neste dia da consulta e a\nalimentação está adequada. Está em uso de hidroclorotiazida 50mg/dia, enalapril 40 mg/dia e\nanlodipino 10mg/dia. Sua PA no momento está 168 x 90 mmHg e a média das medidas\nambulatoriais estão maiores que 150 x 90 mmHg. Em relação a este caso, é correto afirmar que","options":{"A":"é necessário aumentar a dose do enalapril para 80 mg/dia.","B":"é necessário aumentar a dose do anlodipino para 20 mg/dia.","C":"pode ser necessário encaminhar a paciente para o cardiologista.","D":"a PA de Josefina está elevada, pois a medicação de escolha, em monoterapia, seria um\nbetabloqueador.","E":"a PA de Josefina está elevada, pois não há indicação de uso de enalapril associado à\nhidroclorotiazida ou ao anlodipino."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157634","number":"157634","sourceNumber":"157634","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale a alternativa que NÃO representa uma cardiopatia que cursa com necessidade\nde pressões altas de enchimento ventricular (PVC\nelevada).","options":{"A":"Comunicação interventricular.","B":"Tetralogia de Fallot.","C":"Anastomose cavopulmonar.","D":"Shunt sistêmico-pulmonar."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157630","number":"157630","sourceNumber":"157630","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A avaliação inicial de um paciente com Hipertensão Arterial Sistêmica (HAS) inclui a\nconfirmação do diagnóstico, a suspeição e a identificação de causa secundária, além da avaliação\ndo risco CV, sendo DESNECESSÁRIO certificar-se de que o paciente não:","options":{"A":"Esteja com a bexiga cheia.","B":"Tenha praticado exercícios físicos há pelo menos 60 minutos.","C":"Tenha ingerido bebidas alcoólicas, café ou alimentos.","D":"Tenha fumado nos 60 minutos anteriores."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157629","number":"157629","sourceNumber":"157629","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Hipertensão Arterial (HA) é condição clínica multifatorial caracterizada por diversas\nalterações. Sobre isso, indique a alternativa CORRETA.","options":{"A":"Raramente se associa a distúrbios metabólicos, alterações funcionais e/ou estruturais de\nórgãos-alvo, sendo agravada pela presença de outros fatores de risco (FR), como dislipidemia,\nobesidade abdominal, intolerância à glicose e diabetes melito (DM).","B":"Hipertensão arterial (HA) é condição clínica multifatorial caracterizada por elevação eventual\ndos\nníveis pressóricos = 140 e/ou 90 mmHg.","C":"Mantém associação dependente com eventos como morte súbita, acidente vascular encefálico\n(AVE) e infarto agudo do miocárdio (IAM).","D":"Mantém associação independente com eventos como insuficiência cardíaca (IC), doença arterial\nperiférica (DAP) e doença renal crônica (DRC), fatal e não fatal."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157633","number":"157633","sourceNumber":"157633","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quando analisamos o quadro brasileiro de Hipertensão Arterial e doença\ncardiovascular, podemos considerar como ADEQUADO o\nque consta em uma das opções.\nIndique-a.","options":{"A":"Hipertensão arterial atinge mais de 60% dos idosos.","B":"Junto com DM, suas complicações (cardíacas, renais e AVE) têm impacto pequeno na perda da\nprodutividade do trabalho e da renda familiar.","C":"Hipertensão arterial no Brasil atinge 15% (36 milhões) de indivíduos adultos.","D":"Em 2013 ocorreram 1.138.670 óbitos, 339.672 dos quais (9,8%) decorrentes de DCV, a principal\ncausa de morte no país."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157577","number":"157577","sourceNumber":"157577","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro da necessidade de avaliação inicial de um paciente com Hipertensão Arterial\nSistêmica (HAS) inclui a confirmação do diagnóstico, com correta metodologia de aferição da PA,\nINADEQUADAMENTE descrita em uma das alternativas a seguir. Assinale-a:","options":{"A":"Posicionamento: o paciente deve estar sentado, com pernas descruzadas e pés apoiados no\nchão.","B":"O braço deve estar na altura do coração, apoiado, com a palma da mão voltada para baixo e as\nroupas não devem garrotear o membro.","C":"Medir a PA na posição de pé, após 3 minutos.","D":"Posicionamento: o paciente deve estar sentado, dorso recostado na cadeira e relaxado."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157581","number":"157581","sourceNumber":"157581","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentre as etapas para a realização da medição, NÃO pode ser considerada correta\numa delas. Indique-a.","options":{"A":"Determinar a circunferência do braço no ponto médio entre acrômio e olecrano.","B":"Selecionar o manguito de tamanho adequado ao braço.","C":"Colocar o manguito, sem deixar folgas, 5 cm acima da fossa cubital.","D":"Centralizar o meio da parte compressiva do manguito sobre a artéria braquial."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157584","number":"157584","sourceNumber":"157584","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentre as inter-relações entre Hipertensão Arterial e doença cardiovascular no Brasil,\naponte a alternativa em que a afirmação esteja INCORRETA.","options":{"A":"Em 2013 ocorreram 1.138.670 óbitos, 339.672 dos quais (29,8%) decorrentes de DCV, a\nprincipal causa de morte no País.","B":"As taxas de mortalidade decorrentes de DCV em geral têm apresentado redução ao longo dos\nanos, com exceção das doenças hipertensivas (DH), que aumentou entre 2002 e 2009 e mostrou\ntendência à redução desde 2010.","C":"As taxas de mortalidade têm apresentado redução das doenças hipertensivas (DH), no período\nque compreendeu entre 2002 e 2009.","D":"Dentro de nossa realidade houve redução da IC congestiva."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157587","number":"157587","sourceNumber":"157587","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro dos conceitos de Medicina Preventiva existe um importante conceito de\n\nPré-hipertensão que NÃO está adequadamente relacionado a uma das alternativas apresentadas a\nseguir. Aponte-a.","options":{"A":"Pré-hipertensão (PH) é uma condição caracterizada por PA sistólica (PAS) entre 121 e 139 e/ou\nPA diastólica (PAD) entre 81 e 89 mmHg.","B":"Cerca de um décimo dos eventos cardiovasculares (CV) atribuíveis à elevação de PA ocorrem\nem indivíduos com PH.","C":"A PH associa-se a maior risco de desenvolvimento de Hipertensão.","D":"A implicação clínica dessas evidências epidemiológicas é que a PA de indivíduos\n\nPré-hipertensos deve ser monitorada mais de perto, pois uma significativa proporção deles irá\ndesenvolver HA e suas complicações."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157589","number":"157589","sourceNumber":"157589","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação ao estudo de prevalência de Hipertensão Arterial no Brasil, aponte a\nalternativa que está em DESACORDO com as últimas diretrizes científicas.","options":{"A":"A prevalência de HA no Brasil varia de acordo com a população estudada e o método de\navaliação.","B":"No Norte, foram apresentadas as maiores taxas.","C":"Estudos transversais e de coorte incluídos mostraram tendência à diminuição da prevalência nas\núltimas três décadas.","D":"O Sudeste foi a região com maior prevalência de HA autorreferida."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157594","number":"157594","sourceNumber":"157594","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentre os fatores de risco para Hipertensão Arterial, diversos fatores relacionados a ela\npodem ser considerados como importantes. Desse modo, marque a opção INCORRETA.","options":{"A":"Não ocorre uma associação direta e linear entre envelhecimento e prevalência de Hipertensão.","B":"A prevalência de HA autorreferida foi estatisticamente diferente entre os sexos.","C":"Estudos realizados no Brasil, incluindo indivíduos idosos, mostraram 68% de prevalência de\nHipertensão.","D":"Estudos brasileiros que avaliaram o impacto de polimorfismos genéticos na população de\nquilombolas não conseguiram identificar um padrão mais prevalente."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157596","number":"157596","sourceNumber":"157596","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Acerca das estratégias para a implementação de medidas de prevenção da\nHipertensão Arterial, que englobam políticas públicas de saúde combinadas com ações das\nsociedades médicas e dos meios de comunicação, podemos considerar como NÃO efetivo o\nseguinte. Indique-o.","options":{"A":"O objetivo deve ser estimular o diagnóstico precoce, o tratamento contínuo, o controle da PA e\nde FR associados.","B":"Promover modificação do estilo de vida (MEV) e/ou uso regular de medicamentos.","C":"Consumo crônico e elevado de bebidas alcoólicas aumenta a PA de forma consistente.","D":"O impacto da dieta rica em sódio, estimada em pesquisas, indica que a maioria das pessoas\nentrevistadas reconhece conteúdo alto ou muito alto de sal nos alimentos."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157599","number":"157599","sourceNumber":"157599","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para auxiliar o diagnóstico de hipertensão, pode ser proposta a medição da PA fora do\nconsultório. A PA fora do consultório pode ser obtida através da Medição Residencial da Pressão\nArterial (MRPA), ou da MAPA de 24 horas. As medições da PA fora do consultório devem ser\nestimuladas, podendo ser realizadas por equipamento semiautomático do próprio paciente ou dos\nserviços de saúde. As principais vantagens da medição da PA fora do consultório estão listadas a\nseguir, com a EXCEÇÃO de uma delas. Aponte-a:","options":{"A":"Maior número de medidas obtidas.","B":"Refletem as atividades usuais dos examinandos.","C":"Menor engajamento dos pacientes com o diagnóstico e o seguimento.","D":"Abolição ou sensível redução do efeito de avental branco."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157602","number":"157602","sourceNumber":"157602","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente hipertenso, mal controlado por ser muito agitado e teimoso, procura seu\nconsultório pela terceira vez a fim de tentar obter o controle de sua hipertensão. Então durante a\nconsulta, diversas argumentações a esse respeito são feitas. Entre elas, uma está atualmente\nINCORRETA, e está contida em uma das opções seguintes. Indique-a.","options":{"A":"O AVE é a manifestação mais comum da lesão vascular causada pela HA.","B":"A escolha terapêutica deve ser baseada na eficácia do medicamento e na tolerabilidade ao\nmesmo.","C":"A associação de Hipertensão e Diabetes aumenta em quatro o risco Cardiovascular, e tem\naumentado a prevalência de HA.","D":"Cronicamente, a terapia anti-hipertensiva eficaz, mantendo PA menor que 130/80 mmHg, tem\ntido um papel decisivo na prevenção secundária de todos os tipos de AVE e AIT."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157598","number":"157598","sourceNumber":"157598","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O tratamento da Hipertensão tem, em última análise, a redução da morbimortalidade,\nsendo que os desfechos mostram benefícios do\ntratamento realizado com o uso de medicações,\nsendo, entretanto, de grande importância conhecer seus mecanismos de ação bem como efeitos\ncolaterais descritos. Sobre isso, aponte a alternativa INCORRETA.","options":{"A":"Os Betabloqueadores promovem diminuição inicial do débito cardíaco e da secreção de renina,\nhavendo readaptação dos barorreceptores e diminuição das catecolaminas nas sinapses nervosas.","B":"Bloqueadores dos receptores AT1 da angiotensina II, assim os BRA antagonizam a ação da\nangiotensina II por meio do bloqueio específico dos receptores AT1, responsáveis pelas ações\nvasoconstritoras, proliferativas e estimuladoras da liberação de aldosterona, próprias da\nangiotensina II.","C":"Alfa bloqueadores; os medicamentos dessa classe agem como antagonistas competitivos dos\na1-receptores pós-sinápticos, levando à redução da RVP com grande diminuição no débito\ncardíaco.","D":"Vasodilatadores diretos; os medicamentos que representam essa classe são hidralazina e\nminoxidil. Atuam, diretamente, relaxando a musculatura lisa arterial, levando à redução da RVP."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157603","number":"157603","sourceNumber":"157603","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Recentemente um antigo paciente, que você acompanha no ambulatório de clínica\nmédica, evolui mal e teve indicado o início de Hemodiálise devido à lesão causada pela\nhipertensão. Ele o procurou bastante arrependido de não ter se medicado adequadamente no\npassado, mas pediu novamente a sua orientação, apesar de já ter sido transferido de\nespecialidade. Em consideração aos anos de convívio, você o orientou ADEQUADAMENTE,\nconforme o contido em uma das alternativas a seguir. Assinale-o.","options":{"A":"A medição da PA desses pacientes deve ser feita preferencialmente fora das unidades de\ndiálise, nos intervalos interdialíticos.","B":"As decisões terapêuticas baseadas na medição de PA residencial associam-se a um pior\ncontrole pressórico interdialítico avaliado pela MAPA de 24h em comparação à medição de PA\npré-diálise.","C":"Quando utilizamos a mensuração dos níveis pressóricos pré-diálise, ocorre que a PA obtida\ndessa forma, além de apresentar grande variabilidade, está geralmente superestimada.","D":"Quando utilizamos a mensuração dos níveis pressóricos, ela é subestimada quando obtida após\na diálise."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157717","number":"157717","sourceNumber":"157717","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale a alternativa que NÃO representa uma alteração observada no ECG de uma\ncriança com miocardite.","options":{"A":"Taquicardia sinusal.","B":"Variações no segmento ST.","C":"Desvios do eixo de QRS.","D":"Infiltrados pulmonares em porções basais ou inferiores."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157610","number":"157610","sourceNumber":"157610","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente hipertenso e diabético (ambos mal controlados porque o paciente é rebelde ao\ntratamento) se recusa a se medicar diariamente, bem como não consegue mudar seu estilo de vida,\nque tem, como principais pontos, o tabagismo e a ingesta de grandes quantidades de sal nos\nchurrascos. Durante última consulta, foi constatado alteração da creatinina bem como um USG, que\ndemonstrava rins aparentemente com anatomia preservada. Acerca desse quadro, podemos\nconsiderar que:","options":{"A":"Na doença renal crônica, a redução pressórica não constitui a medida mais eficaz para a\nredução do risco CV.","B":"Após iniciada a doença renal crônica, o controle da HAS não promove mais a atenuação da\nprogressão do dano renal, independentemente do anti-hipertensivo utilizado.","C":"O achado de albuminúria elevada é determinante de evolução desfavorável da doença renal,\nmas não causa aumento do risco Cardiovascular.","D":"Pacientes idosos com doença renovascular, DAC e com risco de hipotensão postural\nfrequentemente requerem a individualização do tratamento anti-hipertensivo."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157652","number":"157652","sourceNumber":"157652","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Com relação ao quadro clínico da miocardite, julgue itens expostos a seguir. ; I. A\napresentação clínica é muito variável, desde assintomática ou levemente sintomática, com\nanormalidades eletrocardiográficas transitórias, até um quadro de choque cardiogênico.; II. Uma\ndas manifestações cardiovasculares é a taquicardia inapropriada ao estado febril. ; III. Morte\nsúbita\ncardíaca pode ser a primeira manifestação da miocardite na criança. Estão CORRETOS os itens","options":{"A":"I e II, apenas.","B":"II e III, apenas.","C":"I e III, apenas.","D":"I, II e III."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157617","number":"157617","sourceNumber":"157617","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Recentemente ocorreu um óbito em seu plantão com um paciente relativamente jovem,\n57 anos de idade, que apresentava intensa\ndor torácica e dorsal, fora pressão extremamente\nelevada. Assim, sua curiosidade levou a, novamente, a revisar os conceitos de hipertensão,\ndescobrindo que o seguinte conceito estava INCORRETO. Assinale-o.","options":{"A":"Crise hipertensiva, chamada de Emergência, é caracterizada por elevação aguda de PA\nassociada à Lesão Órgão Alvo, que pode\nincluir acometimento neurológico, renal, ocular, hepático\nou insuficiência miocárdica, manifesta como encefalopatia, convulsões, alterações visuais, achados\nanormais de eletrocardiograma ou ecocardiograma, insuficiência renal ou hepática.","B":"A Urgência é descrita como elevação da PA superior ao percentil 99 mais 5 mmHg (estágio 2),\nassociada a sintomas menos graves, em paciente sob risco de evolução para LOA progressiva,\nsem evidência de acometimento recente.","C":"Na Urgência sugere-se manejo com medicamentos, por via oral, com redução de PA em 12\nhoras, sob monitorização.","D":"A redução muito rápida de PA na Urgência é contraindicada, pois leva à hipotensão, falência de\nmecanismos autorreguladores e possibilidade de isquemia cerebral e visceral."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157621","number":"157621","sourceNumber":"157621","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Como seu avô é viúvo e participa ativamente de diversas atividades sociais da terceira\nidade, ele convidou você para ministrar uma palestra, em seu grupo de idosos, com orientações\nsobre a hipertensão, o que você prontamente atendeu. Sobre as suas orientações, aponte aquela\nque é considera a MAIS correta.","options":{"A":"A prevalência da Hipertensão aumenta progressivamente com o envelhecimento, sendo\nconsiderado o principal Fator Risco Cardiovascular não modificável na população geriátrica.","B":"São considerados idosos, sob o ponto de vista cronológico, indivíduos com 75 anos ou mais de\nidade, vivendo em países desenvolvidos, ou com 70 anos ou mais, em países em desenvolvimento.","C":"Dentro desse grupo etário, são chamados de muito idosos aqueles que já alcançaram a sétima\ndécada de vida.","D":"O envelhecimento vascular é o aspecto principal relacionado à elevação da PA nos idosos,\ncaracterizado por alterações na microarquitetura da parede dos vasos, com consequente\nenrijecimento arterial."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157626","number":"157626","sourceNumber":"157626","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro da abordagem de hipertensão na situação especial que é a do idoso, NÃO\npodemos concordar que:","options":{"A":"Existem evidências robustas do benefício de reduzir a PA com o tratamento anti-hipertensivo em\nidosos com 80 anos ou mais. Essa vantagem está limitada a indivíduos com PAS = 160 mmHg, nos\nquais a PAS foi reduzida a valores < 150 mmHg.","B":"Em indivíduos idosos com menos de 80 anos, o tratamento anti-hipertensivo pode ser\nconsiderado para aqueles com PAS > 140 mmHg,\npara uma meta de PAS < 140 mmHg, desde que\nos indivíduos apresentem uma boa condição clínica e o tratamento seja bem tolerado.","C":"Os benefícios de diferentes regimes terapêuticos em pacientes com idade superior ou inferior a\n65 anos confirmam que existem evidências de\nque diferentes classes possuam efetividades\ndiferentes em pacientes mais jovens ou mais velhos.","D":"Um aspecto que merece destaque é a possibilidade de HA secundária no idoso, cujas causas\nmais frequentes são estenose de artérias renal,\nsíndrome da apneia e hipopneia obstrutiva do sono\n(SAHOS), alterações de função tireoidiana e uso de medicamentos que podem elevar a PA."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157712","number":"157712","sourceNumber":"157712","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação ao diagnóstico de miocardite, assinale a alternativa INCORRETA.","options":{"A":"Está indicada a pesquisa de sorologias virais de forma rotineira.","B":"Para a avaliação histopatológica é utilizado o critério de Dallas.","C":"A cintilografia com 67-Gálio apresenta sensibilidade de 50%.","D":"A avaliação diagnóstica da miocardite se faz inicialmente por meio da suspeita clínica."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157738","number":"157738","sourceNumber":"157738","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Durante consulta ambulatorial de paciente cardiopata, os familiares do paciente\nquestionaram o médico assistente a respeito do\nconsumo de álcool dele. Sendo assim, assinale a\nalternativa que apresenta a orientação INCORRETA a respeito desse questionamento.","options":{"A":"Consumo crônico e elevado de bebidas alcoólicas aumenta a PA de forma consistente.","B":"Ocorre em mulheres efeito protetor com dose inferior a 40 g de álcool/dia.","C":"Ocorre em mulheres risco de HA com consumo de 30-40 g de álcool/dia.","D":"Em homens, o risco aumentado de HA tornou-se consistente a partir de 31 g de álcool/dia."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157748","number":"157748","sourceNumber":"157748","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Durante reunião da equipe de saúde, você é convidado a opinar a respeito de uma\ncampanha de aferição de pressão arterial,\nfora do ambiente médico. Assim, você fundamenta sua\nopinião, ADEQUADAMENTE, com o contido na seguinte opção. Assinale-a:","options":{"A":"Uma das vantagens de medição da PA fora do consultório seria o maior engajamento dos\npacientes com diagnóstico e seguimento.","B":"Uma das desvantagens seria a de ter relação com as atividades usuais dos examinandos.","C":"Maior chance de vezes de medida pela potencialização do efeito do avental branco.","D":"Aumenta a chance de erro diagnóstico por menor número de medidas pelo médico."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157749","number":"157749","sourceNumber":"157749","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quando da avaliação de Idosos Hipertensos, podemos considerar como característicos\ndeles as seguintes alternativas, com EXCEÇÃO de\numa delas. Assinale-a.","options":{"A":"Ocorre uma maior frequência do hiato uscultatório, que consiste no desaparecimento dos sons\ndurante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente baixos para a PAD.","B":"A grande variação da PA nos idosos ao longo das 24 horas torna a MAPA uma ferramenta\nmuitas vezes útil.","C":"A pseudo-hipertensão, que está associada ao processo aterosclerótico.","D":"Presença de arritmias, como Fibrilação Atrial, pode dificultar a medição da PA."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157753","number":"157753","sourceNumber":"157753","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O sucesso do tratamento da Hipertensão Arterial com medidas nutricionais depende da\nadoção de um plano alimentar saudável e\nsustentável, sendo que a proposta de utilização de dietas\nradicais resulta em abandono do tratamento. Podemos adequadamente orientar durante a consulta\nestes tópicos, com a EXCEÇÃO de um deles. Aponte-o.","options":{"A":"Existem evidências de que a ingestão de laticínios, em especial os com baixo teor de gordura,\nreduz a PA, sendo que o leite contém vários\ncomponentes, como cálcio, potássio e peptídeos\nbioativos que podem diminuir a PA.","B":"O café, apesar de rico em cafeína, é uma substância com efeito pressor agudo, e possui\npolifenóis que podem favorecer a redução da PA.","C":"O consumo de café em doses habituais está associado à maior incidência de Hipertensão\nArterial.","D":"O aumento do consumo de sódio está relacionado ao aumento da PA."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157655","number":"157655","sourceNumber":"157655","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente hipertenso e diabético mal controlado, 59 anos de idade, evolui com edema\nem membros inferiores e dificuldade tanto de\ncaminhada quanto de dormir. Quando inicialmente\navaliado, seu RX torácico demonstra aumento de ventrículos, congestão pulmonar, e seu ECG\ndemonstra sobrecarga esquerda. Nessa consulta inicial, você prescreve carvedilol, espironolactona,\nfurosemida e captopril. Diante de tal caso, qual das condutas a seguir pode ser considerada\nINADEQUADA e por qual motivo?","options":{"A":"Captopril, porque potencializa a lesão renal.","B":"Furosemida, porque apresenta toxicidade aumentada associada à espironolactona.","C":"Espironolactona, porque causa hipercalemia nesse caso.","D":"Carvedilol, porque necessita que inicialmente o paciente esteja compensado e sem congestão."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157705","number":"157705","sourceNumber":"157705","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Idosa cardiopata mal controlada é internada com descompensação da insuficiência\ncardíaca, mas evolui mal, sendo então transferida\npara a unidade de tratamento intensivo, onde é\nproposto tratamento com dobutamina. Assinale a alternativa que NÃO corresponde a esse caso:","options":{"A":"Melhora do débito cardíaco.","B":"Protetor para arritmias.","C":"Vasodilatador visceral.","D":"Aumenta consumo de O2 miocárdico."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-157754","number":"157754","sourceNumber":"157754","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"As ditas crises hipertensivas representam grande desafio para a prática clínica da\nmedicina de urgência, vez que se correlacionam diversos órgãos e sistemas que finalmente são\nlesados pela elevação descontrolada e lesiva da Pressão. Assinale a alternativa que NÃO está\ndentre essas lesões.","options":{"A":"Edema Cerebral.","B":"Sangramento Cerebral.","C":"Edema de Papila de Nervo Óptico.","D":"Cefaleia tipo Cluster."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134706","number":"134706","sourceNumber":"134706","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente masculino de 60 anos de idade deu entrada no hospital com quadro de dor\ntorácica, dispneia e mal-estar progressivos há 8 horas. Seu ECG demonstrava tanto áreas de\ncicatriz, quanto áreas decorrentes de lesão. Pouco após sua admissão na sala de emergência,\nevoluiu com grande piora, agora com choque e dissociação eletromecânica, sendo, também,\nsuspeitado de ruptura miocárdica. Aponte a afirmação que NÃO é compatível com esse quadro.","options":{"A":"A ecocardiografia transtorácica pode, também, mostrar sinais: pouco líquido denso e achados\nclássicos de tamponamento cardíaco.","B":"O ponto da ruptura, em geral, não é localizado pelo ecocardiograma.","C":"São necessários grandes volumes de derrame pericárdico para o tamponamento.","D":"A presença de líquido pericárdico, sem sinais de tamponamento cardíaco, não faz o diagnóstico\nde ruptura de parede ventricular."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134744","number":"134744","sourceNumber":"134744","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O nitroprussiato de sódio, potente anti-hipertensivo, é frequentemente usado no dia a\ndia do tratamento de emergências cardiovasculares, NÃO sendo verdadeiro que:","options":{"A":"Após metabolizado pelo fígado, perde a toxicidade.","B":"A insuficiência renal facilita a intoxicação.","C":"Atua de forma mista, em sistema arterial e venoso.","D":"Com o uso, frequentemente a dose deve ser aumentada."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134676","number":"134676","sourceNumber":"134676","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente com dispneia aos médios esforços, edema em membros inferiores, prostração\ne dificuldade de dormir. Refere ter problema no\ncoração e utilizar medicação para \"coração\ninchado\". Qual dos aspectos abaixo seria compatível com intoxicação digitálica?","options":{"A":"Paciente refere enxergar as coisas amareladas.","B":"Aumento da frequência cardíaca.","C":"Taquisfigmia.","D":"Cialorreia."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134691","number":"134691","sourceNumber":"134691","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente hipertenso mal controlado e cardiopata, com insuficiência cardíaca\ncongestiva. Constantemente falta às consultas de\nambulatório de cardiologia, procurando, a\nseguir, o Pronto-socorro para receber medicação \"debaixo da língua\". Deu entrada agora na\nemergência com PA 230x120mmHg, dispneico e com intensa estertoração pulmonar. A\nhipótese inicial é a de edema agudo hipertensivo, qual das opções abaixo apresenta efeito\nimportante, tanto na pré-carga, quanto na pós-carga de Ventrículo Esquerdo na emergência?","options":{"A":"Digitálico.","B":"Nitroglicerina.","C":"Nitroprussiato de sódio.","D":"Furosemida."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-134778","number":"134778","sourceNumber":"134778","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual patologia é característica da Tríade de Beck?","options":{"A":"Tamponamento cardíaco.","B":"Ruptura de aorta torácica.","C":"Infarto agudo do miocárdio.","D":"Pneumotórax hipertensivo."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-111831","number":"111831","sourceNumber":"111831","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dobutamina é uma importante ferramenta para o tratamento de pacientes cardiopatas,\nNÃO fazendo parte de suas interações o seguinte\nitem:","options":{"A":"vasodilatação.","B":"cronotrópico.","C":"inotrópico.","D":"vasopressor."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-111870","number":"111870","sourceNumber":"111870","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente dá entrada no pronto-socorro queixando-se de intensa cefaleia e mal-estar de\ninício súbito nesta manhã, quando iniciou suas atividades. Em avaliação inicial, mostrava-se lúcida,\nmas com fácies de dor e algo agitada. Sua pressão demonstrava valores elevados de 200 x 100\nmmHg. Dessa forma, qual informação podemos considerar ADEQUADA?","options":{"A":"Trata-se de emergência hipertensiva.","B":"Trata-se de AVC Hemorrágico.","C":"Está indicado Nitroprussiato de Sódio.","D":"Inicialmente devemos medicar com analgésicos e ansiolíticos."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-111901","number":"111901","sourceNumber":"111901","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual das medicações abaixo listadas apresenta a necessidade de cuidados quanto à\ninterferência de energia física, durante a sua infusão, e por isso de equipo com proteção?","options":{"A":"Furosemida.","B":"Emulsão Lipídeos.","C":"Nitroprussiato de Sódio.","D":"Glicose hipertônica."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-350864","number":"350864","sourceNumber":"350864","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 42 anos, atleta, com história recente de hipertensão de difícil controle, sem\noutras comorbidades. Faz uso de dois anti-hipertensivos (anlodipina e atenolol). O paciente\napresentou episódio de astenia e paresia de membros inferiores tendo sido internado para\ninvestigação. Exame laboratorial evidenciou hipocalemia (1,9mmol/L), dosagem de catecolaminas\nurinárias normais. Qual achado de exame complementar é mais compatível com o diagnóstico?","options":{"A":"Nódulo adrenal à tomografia com contraste.","B":"Aneurisma de artéria renal à angiotomografia.","C":"Hematúria e proteinúria no sumário de urina.","D":"Nefropatia atrófica no ultrassom de vias urinárias."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-350877","number":"350877","sourceNumber":"350877","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 45 anos procura atendimento sem queixas objetivas. Relata perda de peso\nintencional - 15Kg ao longo dos últimos 12 meses - após mudança de estilo de vida (dieta e\natividade física), motivada por diagnóstico de pré-diabetes. Persiste com o hábito de exercícios\nregulares (150min de atividade aeróbica semanal) além de dieta adequada. O exame físico está\nnormal, exceto pela pressão arterial de 140x100mmHg e discreto edema de membros inferiores\nassociado a aparente insuficiência venosa. Optou-se por uma rotina de aferições pressóricas\nambulatoriais diárias (realizadas em um ambiente próximo ao seu domicílio), além de realização de\nexames complementares. Os resultados foram: hemograma, perfil lipídico e função renal normais.\nHemoglobina glicada=5,5%, relação albumina/creatinina urinárias=450mg/g (VR < 30mg/g). A\nmédia das medidas pressóricas confirmou o valor aferido na consulta inicial. Ao ser informado da\nnecessidade de tratamento, relata ser contrário ao uso de mais de uma droga, inicialmente. Com\nbase nesses dados, qual dos itens abaixo representa a melhor escolha anti-hipertensiva?","options":{"A":"Bloqueador de canal de cálcio.","B":"Diurético tiazídico.","C":"Inibidor de ECA.","D":"Betabloqueador."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-350895","number":"350895","sourceNumber":"350895","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 60 anos, masculino, foi encaminhado da UBS para um hospital terciário\npara investigação de falta de ar de início há 4\nmeses, que piorava com esforços. Inicialmente, ainda\nconseguia trabalhar, porém, atualmente, não consegue tomar banho sozinho pelo cansaço. Relata\nque os sintomas são piores à noite, em especial, após deitar, chegando a acordar de madrugada\nvárias vezes, além de ter buscado atendimento na UPA algumas vezes no período. Comparece à\nconsulta em uso de enalapril, carvedilol e espironolactona. Histórico de hipertensão arterial,\ndislipidemia e tabagista 30 maços/ano. No momento da consulta, encontra-se acordado,\nconsciente, conversando, eupneico em ar ambiente, PA 100x60 mmHg, FC 68 bpm, FR 18 irpm,\nSpO? 93% em ar ambiente. Ausculta pulmonar com crepitações finas e esparsas, em ambas as\nbases. Abdome flácido. Edema +/4+ em membros inferiores com cacifo positivo. Trouxe\necocardiograma evidenciando fração de ejeção de 36%, com hipocinesia difusa, disfunção\ndiastólica grave. Visando maior benefício de sobrevida nesse perfil de paciente, assinale a melhor\nmedicação a ser associada.","options":{"A":"Dapaglifozina.","B":"Hidralazina.","C":"Valsartana.","D":"Digoxina."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-321308","number":"321308","sourceNumber":"321308","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente masculino, 57 anos, diagnosticado com insuficiência cardíaca de etiologia\nhipertensiva há 3 anos. Portador de\npré-diabetes. Evoluindo com dispneia progressiva, atualmente\naos mínimos esforços, em atividades simples como escovar os dentes ou pentear os cabelos.\n\nEx-tabagista há 15 anos. Apresenta boa aderência medicamentosa. Em uso de furosemida,\nlosartana, carvedilol, espironolactona em doses\notimizadas. Ao exame físico, apresenta-se com PA\n130 x 70 mmHg; FC 65 bpm; FR 18 irpm; SpO? 98% em ar ambiente. Turgência jugular leve.\n\nAusculta pulmonar com roncos em bases; edema de membros inferiores +/4+. Restante do exame\nfísico sem achados. Exames complementares:\nHb 12,4 g/dl (> 12 g/dl); leucócitos 6 mil (sem\ndesvio); plaquetas 180.000 (VR 150.000?450.000); ureia 40 mg/dl (VR até 40 mg/dl); creatinina 1,2\n\nmg/dl (VR até 1,3 mg/dl); sódio 133 mEq/L (VR 135?145 mEq/L); potássio 4 mEq/L (VR 3,5?5\nmEq/L). Restante dos exames sem nada chamativo.\nEletrocardiograma com sinais de sobrecarga\nde ventrículo esquerdo, ritmo sinusal e sem sinais de arritmia. Ecocardiograma transtorácico,\nrealizado há 15 dias, evidenciou fração de ejeção de 38%, às custas de hipocinesia difusa, sem\nsinais de lesão valvar. De acordo com o caso acima, qual a melhor conduta nesse momento?","options":{"A":"Associação de ivabradina ao esquema de tratamento.","B":"Suspensão de losartana e início de sacubitril/valsartana.","C":"Suspensão de carvedilol e introdução de dapaglifozina.","D":"Implante de CDI (cardiodesfibrilador implantável) de urgência."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-292809","number":"292809","sourceNumber":"292809","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem, 70 anos, vem em consulta ambulatorial queixando-se de dispneia progressiva\nnos últimos 2 meses e, agora, em repouso.\nRelata também edema de membros inferiores e acorda\ncom falta de ar durante a noite. É hipertenso e obeso. Fez um ECG, que revelou sinais de\nsobrecarga ventricular esquerda e um ecocardiograma, com FEVE = 65%, disfunção diastólica,\npressão sistólica na artéria pulmonar de 40 mmHg e sinais de aumento de pressões no enchimento\ndo VE (E/e' > 9). Está em uso de losartana 50 mg 2 vezes ao dia e hidroclorotiazida 25 mg cedo. Ao\nexame físico: PA = 150 x 90mmHg, FC = 80 bpm, crepitações pulmonares em terço inferior\nbilateralmente, ausência de sopros cardíacos, edema de membros inferiores de 2+/4+. LEGENDA:\nVE = Ventrículo Esquerdo; FEVE = Fração de Ejeção do VE. Qual é sua conduta inicial?","options":{"A":"Associar betabloqueador e diurético de alça e manter o restante dos medicamentos.","B":"Orientar perda de peso, associar hidralazina via oral e encaminhar ao pneumologista.","C":"Introduzir antagonista da aldosterona e diurético de alça e manter os outros remédios.","D":"Trocar tiazídico por diurético de alça e associar bloqueador de canal de cálcio à receita."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-292811","number":"292811","sourceNumber":"292811","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem de 70 anos, hipertenso de longa data, é admitido na emergência com dispneia\naguda. Ao exame físico, apresenta pressão\narterial de 220 x 120 mmHg e crepitações pulmonares\nbilaterais em dois terços inferiores. Considerando o diagnóstico mais provável, quais medicamentos\ndentre os listados abaixo, devem ser prescritos, prioritariamente.","options":{"A":"Morfina e dobutamina.","B":"Morfina e nitroglicerina.","C":"Furosemida e dobutamina.","D":"Furosemida e nitroglicerina."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-292865","number":"292865","sourceNumber":"292865","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Durante o exame físico de Edberto, você aferiu PA = 162 x 114mmHg, IMC = 38kg/m² ,\ncircunferência abdominal = 110 cm e glicemia capilar em jejum = 158 mg/dl. A ausculta cardíaca\nevidenciou frequência cardíaca de repouso de 120 bpm, ictus deslocado para o 6º espaço\nintercostal e com caráter propulsivo. Edberto ficou surpreso com o valor de sua pressão arterial,\nreferindo que, apesar de não lembrar quando fora a última vez que teve a pressão arterial aferida,\nnunca havia chegado a esse nível pressórico. Ele, então, pergunta qual significado clínico desse\nvalor. Assinale a alternativa com a conduta CORRETA.","options":{"A":"Orientar que essa aferição isolada não implica diagnóstico de HAS, mas, em próximo\natendimento, caso nível pressórico esteja maior que\n140x90, será dado o diagnóstico de HAS.","B":"Orientar que essa aferição isolada não implica diagnóstico de HAS. Solicitar diário pressórico\n(MRPA) para diagnóstico de HAS em próximo atendimento.","C":"Diagnosticar e comunicar evento de Emergência hipertensiva e encaminhar a serviço de\nUrgência e Emergência para controle parenteral.","D":"Informar que mesmo com somente essa aferição isolada, considerando dados clínicos, o\npaciente tem diagnóstico de HAS em medição única."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-259712","number":"259712","sourceNumber":"259712","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente masculino, 69 anos, em tratamento irregular para insuficiência cardíaca e\nhipertensão, procura a emergência com dispneia e edema de membros inferiores (MMII) que vem\nprogredindo na última semana. Ao ser atendido, encontrava-se com frequência respiratória = 30\nincursões/minuto, frequência cardíaca = 90 batimentos/minuto, pressão arterial = 190 x 110 mmHg ,\nestava orientado, mas verbalizava com dificuldade, observava-se turgência jugular (3+/4+) a 45\ngraus e edema de MMII (4+/4+). Ausculta pulmonar com crepitações em 2/3 inferiores de tórax\nbilateralmente, ausculta cardíaca com ritmo cardíaco regular, em 2 tempos e sopro sistólico 3+/6+\nno foco mitral. Pulsos palpáveis e simétricos. Negava dor precordial, eletrocardiograma mostrava\nritmo sinusal e não apresentava sinais de isquemia. Exames laboratoriais séricos mostravam\nfunção renal normal e não evidenciavam sinais de injúria miocárdica. Saturação de oxigênio = 89%\nem ar ambiente. Radiografia de tórax está demonstrada abaixo. Qual a melhor conduta para o caso\nem questão?","options":{"A":"Nitratos, diuréticos e betabloqueadores.","B":"Dobutamina, diuréticos endovenosos, opioides e oxigênio.","C":"Vasodilatadores, diuréticos e ventilação não invasiva com pressão positiva.","D":"Ventilação não invasiva com pressão positiva, amiodarona e betabloqueadores."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/259712.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-234025","number":"234025","sourceNumber":"234025","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem de 52 anos foi avaliado por queixa de cefaleia occipital frequente, fadiga e\nsonole?ncia diurna. Sedenta?rio, tambe?m referia dispneia aos esforc?os mais acentuados como\ncorrer ou subir escadas. Ao exame, apresentava IMC 32,5 kg/m², circunfere?ncia abdominal 102\ncm; PA: 150 x 100 mmHg; pulso 95 bpm. Abdome: globoso por adiposidade e sem estrias. Exames\nbioqui?micos: glicemia 118 mg/dl; A1C: 5,5%, colesterol: 225 mg/dl; HDL: 32 mg/dl; triglicérides:\n335 mg/dl; LDL: 126 mg/dl. Foi prescrito losartana e recomendado mudanc?as no estilo de vida.\n\nLEGENDA: IMC: Índice de Massa Corporal; PA: Pressa?o Arterial; bpm: Batimentos por Minuto;\nA1C: hemoglobina glicada. Qual conduta adicional seria a mais indicada?","options":{"A":"Solicitar polissonografia para investigar apneia do sono.","B":"Prescrever ácidos graxos de ômega 3 para promover elevação do HDL.","C":"Indicar cirurgia bariátrica para tratar a obesidade e prevenir diabetes tipo 2.","D":"Dosar microalbuminúria e proteína C-reativa para confirmar síndrome metabólica."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-234027","number":"234027","sourceNumber":"234027","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente masculino, 76 anos, com histo?rico de dispneia aos esforc?os moderados, foi\ninternado com quadro de dor tora?cica e si?ncope ao realizar esforc?o. Realizou cateterismo que\ndemonstrou 3 pontes pe?rvias de cirurgia de revascularizac?a?o corona?ria realizada ha? 2 anos,\nsem leso?es significantes. E? diabe?tico mal controlado, em uso irregular de insulina 1,6 U/kg/dia e\napresenta claudicac?a?o em membros inferiores, ao caminhar cerca de 150 metros. Ex-tabagista\nde 75 mac?os/ano, abandonou tabagismo ha? 2 anos e mante?m-se em tratamento para enfisema\npulmonar moderado. Ao exame, tem IMC: 33,1 kg/m², PA: 124 x 104mmHg, Pulso regular de 96\nbpm com ascensa?o lenta. Sopro sisto?lico ejetivo com pico telessito?lico mais audi?vel no 2o\nespac?o intercostal pro?ximo a? borda esternal direita. Creatinina se?rica de 2,3 mg/dL (VR:\n\n0,8-1,3). Eletrocardiograma com hipertrofia ventricular esquerda e padra?o de sobrecarga.\nEcocardiograma com frac?a?o de ejec?a?o de 48%,\nPressa?o sisto?lica de arte?ria pulmonar\nestimada em 50 mmHg, a?rea valvar ao?rtica de 0,7 cm² e gradiente Ventri?culo esquerdo - Aorta\nde 55 mmHg. LEGENDA: VR: valor de refere?ncia; IMC: i?ndice de massa corporal; bpm:\nbatimentos por minuto. Qual a terape?utica preferencial para o paciente nesse momento?","options":{"A":"Cirurgia de troca valvar aórtica.","B":"Plastia de valva aórtica com balão.","C":"Implante de bioprótese aórtica transcateter.","D":"Reabilitação cardiopulmonar exercícios físicos estruturados."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-199784","number":"199784","sourceNumber":"199784","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um senhor de 74 anos, sem história de doenças prévias ou uso de medicações,\nfumante de cerca de 5 cigarros por dia,\napresentou em consulta prévia registro de 2 aferições de\nPA com média de 136 x 86 mmHg. Trouxe ECG que apresenta padrão strain e evidencia derivação\naVL com onda R de 13 mm e derivação V3 com onda S de 20 mm associado a componente\nnegativo de onda P em derivação V1, de 2 mm. Ao realizar fundoscopia direta, observa-se o\nachado da foto abaixo. O médico insufla o cuff até 160 mmHg, deixando de perceber pulso radial\nentre 130 e 140 mmHg e não consegue palpar artéria radial em 160 mmHg. Após isso, faz 2\nmedidas de PA espaçadas com média de 136 x 82 mmHg. IMC = 29 kg/m². Restante do exame\nfísico sem achados relevantes. LEGENDA: PA: Pressão Arterial; ECG: Eletrocardiograma; IMC:\nÍndice de Massa Corpórea. O médico deve concluir tratar-se de qual condição?","options":{"A":"Pré-hipertensão.","B":"Pseudo-hipertensão.","C":"Hipertensão mascarada.","D":"Hiato auscultatório aumentado."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/199784.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-199737","number":"199737","sourceNumber":"199737","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente 45 anos, hipertenso, procura médico pneumologista com dispneia há 6 meses,\natualmente aos grandes esforços. Nega tabagismo ou doenças pulmonares e cardíacas prévias.\n\nExame físico é normal, exceto pela presença de segunda bulha hiperfonética à ausculta cardíaca e\nedema de membros inferiores (++/4+). Radiografia de tórax mostrava aumento de área cardíaca\ncom parênquima normal. Foi solicitado ecocardiograma que demonstrou: aumento de câmaras\ndireitas, Fração de ejeção = 56% (normal > 50%), com função diastólica de ventrículo esquerdo\ncom leve redução e pressão sistólica de artéria pulmonar = 80 mmHg (normal). Qual das opções\nabaixo seria a medida mais adequada diante dessa situação?","options":{"A":"Iniciar terapêutica com betabloqueadores, inibidores da ECA e diuréticos.","B":"Solicitar sorologia para doença de chagas e coronariografia/ventriculografia.","C":"Prescrever inibidores de fosfodiesterase (sildenafila, por exemplo) e anticoagulação.","D":"Solicitar cateterização de artéria pulmonar e cintilografia de ventilação perfusão"},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-172954","number":"172954","sourceNumber":"172954","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem de 55 anos se apresenta na sala de emergência por piora da dispneia. Vinha\nhá cerca de 1 mês com dispneia de esforços,\nprogressiva. Há 5 horas evoluiu com piora importante\nda dispneia que persistiu mesmo em repouso. Portador de hipertensão arterial sistêmica há 5 anos,\nporém sem adesão ao tratamento, e tabagista. Ao exame, observamos Pressão Arterial (PA) = 150\nx 90 mmHg, Frequência Cardíaca (FC) = 90 batimentos por minuto e turgência jugular leve. Na\nausculta, foi observado ritmo cardíaco irregular, terceira bulha e intensos sibilos expiratórios. Os\nexames de laboratório mostraram leucócitos de 13.500/mm³ (VR: 4.000?11.000/mm³), creatinina de\n1,2 mg/dl (VR: 0,8?1,3 mg/dl) e pró-BNP elevado. Qual a primeira droga que deve ser administrada\nnesse caso, ainda na sala de emergência?","options":{"A":"Amiodarona.","B":"Furosemida.","C":"Nitroprussiato.","D":"Hidrocortisona."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-150878","number":"150878","sourceNumber":"150878","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem de 62 anos, com história de doença arterial coronariana, realizou\nrevascularização miocárdica há 7 anos. Vem\nevoluindo ao longo dos dois últimos anos com piora\nda dispneia (atualmente, aos pequenos esforços), ortopneia, dispneia paroxística noturna e edema\nde membros inferiores. Nega queixas de dor torácica. Realizou há 2 meses coronariografia, que\nmostrou enxertos venosos coronários pérvios. Atualmente, em uso de AAS 100 mg/dia, sinvastatina\n80 mg/dia, carvedilol 50 mg/dia e captopril 150 mg/dia. Ecocardiograma mostra hipocinesia difusa e\nfração de ejeção do ventrículo esquerdo = 32%. Ao exame, mostra-se com FC = 55 bpm; PA = 130\nx 70 mmHg. Creatinina = 0,7 mg/dl. Qual o mecanismo de ação da medicação a ser\nnecessariamente acrescida à prescrição, considerando o benefício na redução de mortalidade?","options":{"A":"Antagonismo da aldosterona.","B":"Inibição da bomba Na/K/ATPase.","C":"Inibição da bomba Na/K/2Cl em alça de Henle.","D":"Inibição da bomba Na/Cl em túbulo contorcido distal."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-126997","number":"126997","sourceNumber":"126997","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 53 anos, diabético, com hipertensão controlada com tiazídico, apresenta\nsíndrome coronariana aguda sem alteração do\nsegmento ST e com algum grau de disfunção de\nVE. Qual das seguintes drogas será a mais eficaz no tratamento do paciente acima?","options":{"A":"Propranolol.","B":"Anlodipino.","C":"Captopril.","D":"Nifedipino."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-126941","number":"126941","sourceNumber":"126941","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, etilista, com dispneia progressiva aos\nesforços, procura ambulatório de clínica\nmédica. Na ausculta cardíaca, observa-se ritmo\ntotalmente irregular, presença de 3ª bulha e sopro sistólico (++/4) em foco mitral. ECG\nrevela fibrilação atrial e complexos QRS de baixa voltagem em derivações periféricas. Qual dos\nachados abaixo se espera encontrar no ecodopplercardiograma?","options":{"A":"No modo M, da valva mitral, aspecto de \"pinheiro tombado\".","B":"No Doppler da valva mitral, a onda A maior que a onda E.","C":"No Doppler da valva mitral, a onda E maior que a onda A.","D":"No modo bidimensional, átrio esquerdo desproporcionalmente aumentado em relação ao\nventrículo esquerdo."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-126947","number":"126947","sourceNumber":"126947","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 48 anos, motorista de ônibus, procurou unidade básica de saúde com\nqueixas de fadiga, hipersonolência diurna\nrelatando que a esposa se queixa do seu ronco à\nnoite que não a deixa dormir. Ao exame físico: índice de massa corpórea de 32 kg/m2,\ncircunferência do pescoço de 41cm, PA:145x95mmHg, Pulso:80 ppm, f:16 irpm. Auscultas\ncardíaca e pulmonar dentro da normalidade. Traz hemograma, glicemia e exames da função\nda tireoide dentro da normalidade. Qual exame deve ser solicitado para confirmação do provável\ndiagnóstico?","options":{"A":"Monitorização cardiorrespiratória de noite inteira.","B":"Endoscopia nasal com manobra de Müller.","C":"Polissonografia de noite inteira.","D":"Polissonografia diurna (nap study)."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-126993","number":"126993","sourceNumber":"126993","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dona Júlia, 50 anos, descobre em uma atividade preventiva realizada em seu Posto\nque sua pressão está alterada. Após três\nconsultas com sua médica de família (MFC), com\nintervalo de 1 semana entre elas, Dona Júlia é informada que a média de seus valores de PA foi de\n150 x 86 mmHg. A MFC solicita alguns exames para a paciente, que retorna em consulta\nsubsequente com os seguintes resultados: glicemia de jejum = 88mg/dL; K+= 4 mEq/L; creatinina=\n0,6 mg/dL; colesterol total = 180 mg/dL; HDL = 60 mg/dL; triglicerídeos = 145 mg/dL; sumário de\nurina, eletrocardiograma e fundo de olho sem alterações. A paciente nega tabagismo, etilismo,\nhistória prévia ou familiar de doença cardiovascular, tem IMC = 19,6 kg/m², peso = 55 Kg e pratica\nnatação 4 vezes por semana. Relata à médica ter uma certa resistência a tomar medicamentos.\n\nQual a conduta em relação à decisão de terapia medicamentosa para esse caso?","options":{"A":"Iniciar terapia medicamentosa com um fármaco, uma vez que a paciente apresenta hipertensão\nestágio 1.","B":"Iniciar terapia medicamentosa com um fármaco, uma vez que a paciente apresenta lesão em\nórgão-alvo.","C":"Adiar por três a seis meses a decisão por terapia medicamentosa, uma vez que a paciente\napresenta baixo risco cardiovascular.","D":"Adiar por três a seis meses a decisão por terapia medicamentosa, uma vez que a paciente\napresenta moderado risco cardiovascular."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-81254","number":"81254","sourceNumber":"81254","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo masculino, 49 anos, alcoolista, vem se queixando de dispneia a\npequenos esforços. Na ausculta cardíaca,\nobserva-se ritmo irregular por extrassístoles (1 por\nminuto), presença de terceira bulha e sopro sistólico (++/4) em foco mitral. Na ausculta pulmonar,\nouvem-se crepitações na metade inferior do tórax. O fígado é palpável a 5 cm abaixo do rebordo\ncostal direito e observa-se edema de MMII (++/4). O ECG mostra baixa voltagem do complexo QRS\nnas derivações periféricas e alteração difusa da repolarização ventricular. A radiografia do tórax\nmostra aumento da área cardíaca (++/4) e congestão pulmonar. Entre as drogas que podem ser\nprescritas para esse paciente, uma delas deverá reduzir a mortalidade em longo prazo. Essa droga\né:","options":{"A":"Digoxina.","B":"Furosemida.","C":"Carvedilol.","D":"Amiodarona."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-81239","number":"81239","sourceNumber":"81239","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo masculino, 70 anos, hipertenso e portador de dislipidemia, vem se\nqueixando de forte dor retroesternal com irradiação para o dorso. Pressão arterial medida de\n180/120 mmHg. Observa-se assimetria de pulso braquial. O ECG é normal e a radiografia de tórax\nestá abaixo (VER IMAGEM). Qual o exame mais indicado para confirmação diagnóstica, dentre as\nopções abaixo?","options":{"A":"Cintilografia do miocárdio.","B":"Ecocardiograma transtorácico.","C":"Cateterismo cardíaco com aortografia.","D":"Tomografia computadorizada do tórax."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/81239.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-81314","number":"81314","sourceNumber":"81314","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 65 anos, portador de insuficiência cardíaca congestiva, comparece ao\nacolhimento da unidade básica de saúde com queixa de dispneia em repouso. A última avaliação\nclínica ocorreu há 15 dias e o paciente não apresentava sinais e/ou sintomas. Ao exame, o médico\nobservou crepitações bilaterais em 2/3 inferiores em ambos hemitórax e ritmo irregular, não\nauscultado em consultas anteriores. Diante dessa situação, qual deverá ser a conduta mais\nadequada para o médico da atenção primária?","options":{"A":"Iniciar furosemida 40 mg/dia, enalapril 20 mg/dia e solicitar retorno em 48 horas.","B":"Encaminhá-lo ao serviço de cardiologia ambulatorial para ajuste da medicação.","C":"Encaminhá-lo ao serviço de cardiologia para realização de ecocardiografia.","D":"Coordenar o cuidado do paciente e encaminhá-lo ao serviço de urgência."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-65775","number":"65775","sourceNumber":"65775","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Considere uma paciente de 30 anos, com queixa de dispneia progressiva aos esforços.\nSua ausculta cardíaca revela B1 hiperfonética em\nfoco mitral, B2 hiperfonética em foco pulmonar,\nestalido de abertura da valva mitral e sopro diastólico em ruflar (++/4+) em foco mitral. A\nradiografia\ndo tórax mostra sinal do duplo contorno e surgimento do 4º arco na silhueta cardíaca esquerda. O\nECG mostra onda P bífida em DII. O ecocardiograma mostra folhetos mitrais espessados,\ncalcificados e com mobilidade reduzida, área valvar mitral de 0,9 cm² e escore de Block de 12. Qual\na melhor conduta para esta paciente?","options":{"A":"Tratamento clínico.","B":"Comissurotomia mitral cirúrgica.","C":"Troca de valva mitral por prótese metálica.","D":"Dilatação da valva mitral por cateter balão.","E":"Troca de valva mitral por prótese biológica."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-51246","number":"51246","sourceNumber":"51246","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Qual a alternativa correta quanto à doença cardiovascular na hipertensão arterial\nsistêmica?","options":{"A":"Diuréticos são eficazes no tratamento da hipertensão arterial, mas não têm eficácia na redução\nda morbidade e da mortalidade cardiovasculares.","B":"A hipertensão sistólica isolada e a pressão de pulso são fatores de risco importantes para\ndoença cardiovascular em pacientes de meia-idade e idosos.","C":"Metas antropométricas a serem alcançadas são o IMC menor que 25 kg/m² e a circunferência\nabdominal \"menor que\" 108 cm para os homens e \"menor que\" 80 cm para as mulheres.","D":"Há superioridade do bloqueador do receptor de angiotensina II em relação ao inibidor da enzima\nconversora da angiotensina na redução de eventos coronarianos."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-51250","number":"51250","sourceNumber":"51250","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em um indivíduo adulto normal, sem comorbidades, com que idade e intervalo é\nrecomendado solicitar perfil lipídico para avaliação de risco cardiovascular?","options":{"A":"Desde os 20 anos e a cada 5 anos.","B":"Desde os 30 anos e a cada 5 anos.","C":"Desde os 30 anos e a cada 3 anos.","D":"Desde os 40 anos e a cada ano."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-37599","number":"37599","sourceNumber":"37599","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação aos valores de pressão arterial no consultório, Monitorização Ambulatorial\nda Pressão Arterial de 24 horas (MAPA),\nAutomedida da Pressão Arterial (AMPA) e Monitorização\nResidencial da Pressão Arterial (MRPA) que caracterizam a normotensão ou hipertensão controla,\na hipertensão, a hipertensão do avental branco e a hipertensão mascarada, marque a opção\nincorreta:","options":{"A":"Normotensão ou hipertensão controla: consultório <140/90; MAPA vigília = 130/85; AMPA =\n130/85; MRPA = 130/85.","B":"Hipertensão do avental branco: consultório = 140/90; MAPA vigília < 130/85; AMPA < 130/85;\nMRPA < 130/85.","C":"Hipertensão: consultório = 140/90; MAPA vigília > 130/85; AMPA > 130/85; MRPA > 130/85.","D":"Hipertensão mascarada: consultório = 140/90; MAPA vigília < 130/85; AMPA < 130/85; MRPA <\n130/85."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-37609","number":"37609","sourceNumber":"37609","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Segundo a VI diretriz de Hipertensão Arterial, assinale a alternativa incorreta em\nrelação aos fatores de risco para a hipertensão arterial sistêmica (HAS).","options":{"A":"Em relação à cor, a HAS é duas vezes mais\nprevalente em indivíduos de cor não branca.","B":"A influência do nível socioeconômico na\nocorrência da HAS já está estabelecida, ela é\nmais frequente nos indivíduos de menor nível\nsocioeconômico.","C":"A contribuição de fatores genéticos para a\ngênese da HAS está bem estabelecida na\npopulação.","D":"Atividade física reduz a incidência de HAS,\nmesmo em indivíduos pré-hipertensos, bem\ncomo a mortalidade."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-37389","number":"37389","sourceNumber":"37389","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Correlacione os quadros clínicos com as doenças: I. Manoel, 57 anos, etilista pesado,\nhipertenso e diabético, com queixa de dispneia aos esforços, dispneia paroxística noturna,\nortopneia e edema de membros inferiores. Ao exame encontra-se ictérico (+/4), com ritmo cardíaco\nregular, em 3T (B3) e fígado palpável há 3 cm do RCD, edema MMII 2+/4. ECG com sobrecarga\nventricular esquerda. Radiografia de tórax com cardiomegalia. II. Antônio, 71 anos, tabagista\npesado, etilista e hipertenso, com queixa de dispneia aos esforços e edema de membros inferiores.\nAo exame encontra-se com pletora facial, com ritmo cardíaco regular, em 2T, B2 hiperfonética, MV\ndiminuído difusamente, edema MMII 2+/4. ECG com sobrecarga atrial direita. III. Francisca, 54\nanos, tabagista e não etilista, com queixas de dispneia aos esforços, ortopneia e edema de\nmembros inferiores. Ao exame encontra-se ictérica (++/4), com turgência jugular a 45º, com ritmo\ncardíaco regular, em 3T (B3) e fígado palpável há 4 cm do RCD, edema MMII 3+/4. ECG com\nbloqueio de ramo direito. Radiografia de tórax com cardiomegalia. IV. Raimunda, 70 anos,\ndiabética, hipertensa, obesa, tabagista e etilista social, com queixas de dispneia aos esforços,\nortopneia e edema de membros inferiores. Ao exame encontra-se com ritmo cardíaco regular, em\n2T, crepitantes em bases pulmonares bilateralmente, edema MMII 2+/4. ECG com onda Q em\nparede anterior. 1. Miocardiopatia dilatada provavelmente de etiologia chagásica; 2. Miocardiopatia\nisquêmica; 3. Miocardiopatia dilatada provavelmente de etiologia alcoólica; 4. Cor pulmonale.","options":{"A":"I-1; II-3; III-2; IV-4.","B":"I-3; II-2; III-4; IV-1.","C":"I-3; II-2; III-1; IV-4.","D":"I-3; II-4; III-1; IV-2.","E":"I-1; II-4; III-3; IV-2."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-25284","number":"25284","sourceNumber":"25284","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma jovem com 25 anos, auxiliar de farmácia, comparece ao ambulatório de cirurgia\ngeral do HUWC/UFC para submeter-se a uma\ncirurgia plástica. No exame físico é detectado um\nsopro em ruflar diastólico atribuível à válvula mitral. A válvula mitral é melhor ouvida em que\nespaço\nintercostal?","options":{"A":"Segundo espaço intercostal esquerdo, próximo ao esterno.","B":"Quinto espaço intercostal direito, próximo ao esterno.","C":"Quinto espaço intercostal esquerdo, na linha clavicular média.","D":"Segundo espaço intercostal direito, próximo ao esterno.","E":"terceiro espaço intercostal direito, próximo ao esterno."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-29446","number":"29446","sourceNumber":"29446","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São procedimentos da avaliação inicial de rotina para o paciente hipertenso, EXCETO:","options":{"A":"análise de urina","B":"ureia plasmática","C":"potássio plasmático","D":"acido úrico plasmático"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-29450","number":"29450","sourceNumber":"29450","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"São indícios de hipertensão arterial secundária, EXCETO:","options":{"A":"Início da hipertensão antes dos 30 anos ou após os 60 anos de idade.","B":"Assimetria de pulsos femorais.","C":"Exame de urina anormal (proteinúria ou hematúria).","D":"Sintomas de apneia durante o sono."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-24340","number":"24340","sourceNumber":"24340","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem de 52 anos, tabagista e alcoolista crônico, chega ao IJF com dispneia aos\nesforços, aumento do volume abdominal e edema MMII há 04 meses. Ao exame levemente\ndispneico, turgência jugular a 45º, RCI em 2T, abdome globoso com piparote positivo e fígado\npalpável 5 cm abaixo do rebordo costal direito. Presença de edema MMII com cacifo. Tem ECG\nevidenciando baixa voltagem do QRS, fibrilação atrial e inversão difusa das ondas T. A área\ncardíaca é normal ao RX de tórax. Qual a principal hipótese diagnóstica?","options":{"A":"Cirrose hepática","B":"Cor pulmonale","C":"Pericardite constrictiva crônica","D":"Miocardiopatia isquêmica"},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-24343","number":"24343","sourceNumber":"24343","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação ao tratamento da hipertensão arterial sistêmica (HAS), é CORRETO\nafirmar:","options":{"A":"Os betabloqueadores têm indicação na HAS pós-infarto agudo do miocárdio.","B":"Os diureticos devem ser usados como tratamento inicial de homens sexualmente ativos.","C":"HAS secundária à estenose bilateral da arteria renal deve ser tratada com antagonistas da\nangiotensina II.","D":"Os antagonistas do cálcio são drogas preferenciais para jovens portadores de BAV do 2º grau."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27697","number":"27697","sourceNumber":"27697","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 66 anos, sexo masculino, portador de diabetes mellitus tipo 2 e hipertensão\nhá 20 anos. Queixa-se de há seis meses\napresentar intolerância aos exercícios moderados\n(dispneia ao caminhar três quarteirões), edema de membros inferiores durante o dia e alguns\nepisódios de dispneia noturna. Exame físico mostrou leve taquicardia (105 bpm), pressão arterial de\n110 X 70 mmHg, ausculta cardíaca com discreto sopro sistólico mitral e edema de MMII (++/4).\n\nEcocardiograma evidenciou disfunção sistólica moderada (FE = 42%) e leve insuficiência mitral.\nAlém do controle do diabetes e da hipertensão, como deve ser tratado farmacologicamente este\npaciente? (Assinale o item com melhor combinação para este estágio da doença).","options":{"A":"Inibidor da ECA + Espironolactona.","B":"Betabloqueador + digitálico.","C":"Betabloqueador + Inibidor da ECA.","D":"Espironolactona + digitálico.","E":"Inibidor da ECA + digitálico."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27699","number":"27699","sourceNumber":"27699","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Assinale o item que contém a característica semiológica do sopro de estenose aórtica.","options":{"A":"Crescendo com pico tardio","B":"Crescendo-decrescendo","C":"Ruflar grave com reforço pré-sistólico","D":"Decrescendo","E":"Em maquinaria"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27701","number":"27701","sourceNumber":"27701","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 49 anos, sexo masculino, diabético há 5 anos e em uso de metformina.\nSem outras alterações relevantes. Após\nrepetidas medições, foi constatada hipertensão arterial\nsistêmica com PA = 150 x 85 mmHg. Exames de sangue e urina foram normais. Dos itens abaixo,\nselecione o que contém a medicação mais apropriada para este caso.","options":{"A":"Inibidor da ECA.","B":"Antagonista de canal de cálcio.","C":"Betabloqueador.","D":"Diurético.","E":"Antagonista do receptor da angiotensina."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-25389","number":"25389","sourceNumber":"25389","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo feminino, 20 anos de idade, queixa-se de dispneia progressiva,\natualmente a pequenos esforços. Na ausculta\ncardíaca, observa-se hiperfonese da 1ª bulha em\nfoco mitral e da 2ª bulha em foco pulmonar. Qual a doença valvar que melhor corresponde a este\ntipo de ausculta?","options":{"A":"Estenose aórtica.","B":"Insuficiência aórtica","C":"Estenose mitral","D":"Insuficiência mitral","E":"Estenose pulmonar."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27710","number":"27710","sourceNumber":"27710","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um bebê de 5 meses do sexo masculino é trazido ao pediatra porque a mãe sente uma\nvibração estranha sobre o peito do filho que parece se relacionar com o seu batimento cardíaco. A\ncriança tem síndrome de Down. No exame, um frêmito paraesternal é sentido. Atividade precordial\né acentuada e se estende sobre as áreas paraesternal e apical direitas. Uma terceira bulha\nproeminente é audível no ápice. A característica que melhor descreve o sopro ouvido no exame é:","options":{"A":"sopro sistólico em ejeção","B":"sopro holossistólico","C":"sopro diastólico precoce","D":"sopro telediastólico tardio","E":"sopro contínuo"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27750","number":"27750","sourceNumber":"27750","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um garoto de 9 anos é visto pelo médico para seu exame anual de manutenção da\nsaúde. Ele tem uma história de asma, que foi\ndiagnosticada na idade de 7 anos. Atualmente, ele\nestá passando por episódios de falta de ar e chiado a cada duas semanas. Estes episódios são\nrapidamente aliviados por salbutamol inalado. Seus pais negam qualquer uso prévio de\ncorticosteroides orais e nunca foi internado por insuficiência respiratória. O exame físico é\nnormal,\nexceto por uma pressão arterial de 145/95 mmHg. Duas medições seguintes, durante visitas\nseparadas confirmam este valor. A causa mais provável para esta pressão arterial elevada é:","options":{"A":"patologia cardiovascular.","B":"patologia do sistema nervoso central.","C":"o efeito de droga.","D":"patologia endócrina.","E":"patologia renal."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-25360","number":"25360","sourceNumber":"25360","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 55 anos é acompanhada por hipertensão arterial sistêmica (HAS) em uso\nde hidroclorotiazida há 5 anos. Nos últimos 6\nmeses, vem apresentado mau controle da pressão\narterial e decide-se associar captopril após avaliação que não detectou sinais de HAS secundária.\nApós 1 mês de uso da combinação, paciente evolui com angioedema facial. Assinale o item abaixo\nque descreve a conduta adequada nesta paciente:","options":{"A":"Deve-se suspender o captopril e reintroduzi-lo aos poucos após 4 a 6 semanas","B":"Deve-se substituir o captopril por outra droga da mesma classe","C":"Deve-se suspender permanentemente o uso de inibidores da ECA nesta paciente","D":"Deve-se manter o esquema e administrar anti-histamínicos até resolução completa","E":"Deve-se associar o captopril a outra droga que não a hidroclorotiazida"},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-7276","number":"7276","sourceNumber":"7276","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quais as classes de drogas mais indicadas na terapia da disfunção assintomática do\nventrículo esquerdo?","options":{"A":"Betabloqueadores e inibidores da ECA.","B":"Inibidores da ECA e digitálicos.","C":"Diuréticos e antagonistas da aldosterona.","D":"Diuréticos e inibidores da ECA.","E":"Não se indica terapia medicamentosa para a disfunção ventricular assintomática."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-13438","number":"13438","sourceNumber":"13438","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente candidato à cirurgia eletiva, hipertenso controlado com betabloqueador e\nbloqueador de canal de cálcio. Qual a conduta apropriada no pré--operatório?","options":{"A":"Suspender apenas o bloqueador do canal de cálcio 48 horas antes.","B":"Suspender apenas o beta-bloqueador 48 horas antes.","C":"Manter as medicações.","D":"Suspender os dois fármacos 48 horas antes.","E":"Associar diurético ao esquema em uso 48 horas antes."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-9125","number":"9125","sourceNumber":"9125","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"João, 18 anos, residente em Fortaleza, comparece à unidade de saúde após ?picada?\nde escorpião há cerca de 4 horas. Apresenta dor\nlocal. Considerando que ele tem\nmicroalbuminúria, não teve evento isquêmico coronariano e não tem insuficiência cardíaca ou renal,\nqual a classe de anti-hipertensivo de escolha?","options":{"A":"Inibidores da enzima conversora da angiotensina/antagonista do receptor da angiotensina.","B":"Beta-bloqueadores.","C":"Diuréticos de alça.","D":"Bloqueadores dos canais de cálcio."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-9049","number":"9049","sourceNumber":"9049","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Miguel tem 12 anos, estatura desproporcionalmente elevada, aracnodactilia e leve\ndeslocamento do cristalino. Seu pai faleceu subitamente durante um exercício físico. Dra. Patrícia\ndesconfiou de uma possível alteração genética no gene que codifica a fibrilina-1. Solicitou, então,\num ecocardiograma que evidenciou uma dilatação da aorta ascendente com regurgitação aórtica.\nEm que patologia Dra. Patrícia deve ter pensado?","options":{"A":"Síndrome de Marfan","B":"Acondroplasia","C":"Tetralogia de Fallot","D":"Síndrome de Klinefelter"},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-9085","number":"9085","sourceNumber":"9085","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dona Glória, 62 anos, viúva, prendas do lar procurou seu médico com queixa de\ndispneia para caminhar no plano, edema de\nmmii, ?falta de ar que piora à noite, melhorando\nquando ela se levanta e vai para janela tomar ar?. Ao exame o médico verificou pressão arterial de\n140/90 mmHg, frequência cardíaca = 105 bpm. Trouxe um RX de tórax realizado em serviço de\nurgência que revelava índice cardio-toráxico = 0,6 e edema pulmonar interticial. Segundo os\ncritérios de Boston para o diagnóstico da insuficiência cardíaca, qual a classificação para Dona\nGlória?","options":{"A":"Diagnóstico definido.","B":"Diagnóstico possível.","C":"Diagnóstico provável.","D":"Os dados fornecidos pelo caso acima não permitem fazer a classificação diagnóstica segundo\nos critérios de Boston."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-6957","number":"6957","sourceNumber":"6957","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Sobre a terceira bulha, é correto afirmar:","options":{"A":"É um som de alta frequência.","B":"É produzida nos átrios.","C":"É melhor audível com o diafragma do estetoscópio.","D":"É melhor audível com o paciente em decúbito lateral esquerdo.","E":"Ocorre no período de enchimento ventricular lento."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-6962","number":"6962","sourceNumber":"6962","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O cianeto (metabólito do nitroprussiato de sódio) é removido da corrente sanguínea\natravés da sua ligação com:","options":{"A":"A glutamina e o triptofano.","B":"A albumina e o fosfato.","C":"A meta-hemoglobina e o tiossulfato.","D":"A tiroxina e o lactato.","E":"A insulina e o cortisol."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-17809","number":"17809","sourceNumber":"17809","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente diabético tipo II, 55 anos, sexo masculino apresenta dor torácica aos médios\nesforços.Teste ergométrico foi sugestivo de isquemia miocárdica. Está em uso de AAS 81 mg/dia,\nmetformina 1,7g/dia, sinvastatina 20mg/dia, hidroclorotiazida 40mg/dia e enalapril 20mg/dia. Fará\ncateterismo coronariano em 2 dias. Qual dos seguintes procedimentos é imprescindível?","options":{"A":"Suspender AAS imediatamente","B":"Suspender metformina imediatamente","C":"Suspender sinvastatina imediatamente","D":"Suspender anti-hipertensivos imediatamente","E":"Suspender todos os medicamentos imediatamente"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-15958","number":"15958","sourceNumber":"15958","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Nos pacientes portadores de estenose mitral, é correto afirmar que:","options":{"A":"dispneia é um sintoma de importância secundária.","B":"disfagia e rouquidão não fazem parte do quadro clínico.","C":"lúpus eritematoso e artrite reumatoide são as causas mais comuns.","D":"o ecocardiograma é essencial na confirmação diagnóstica.","E":"pacientes mesmo com fibrilação atrial dispensam o uso de anticoagulantes."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-365645","number":"365645","sourceNumber":"365645","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de 7 anos de idade com aumento dos valores séricos de triglicerídeos e\ncolesterol LDL foi levado ao pronto-socorro com queixa de dor torácica tipo A e diagnosticado com\ninfarto agudo do miocárdio extenso, apresentando choque cardiogênico e disfunção renal aguda. A\ncorrelação entre as doenças cardíaca e renal desse paciente é classificada como tipo","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-349717","number":"349717","sourceNumber":"349717","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um senhor de 62 anos, portador de HAS e tabagista, comparece à UBS para trazer os\nresultados de seus exames de rotina. Ele faz uso de losartana 50 mg BID e anlodipino 5mg MID e\napresenta bom controle de pressão arterial. A seguir estão os resultados dos exames desse\npaciente: Hemoglobina: 14,3 mg/dl / Leucócitos: 7200/mm3 / Plaquetas: 230.000/mm3 / Potássio:\n5,6 mEq/L / Sódio: 143 mEq/L / Ácido Úrico: 4,3 mg/dl / Glicose: 93 mg/dl / HbA1c - 5,4% /\nCreatinina: 0,8 mg/dl. Sangue oculto nas fezes (imunohistoquímica): positivo / Colesterol total:\n122 /\nCol. HDL: 46 / Col. LDL: 68 / Relação albumina-creatinina: 3,2 mg/g. Diante desse quadro, qual é a\nconduta mais adequada?","options":{"A":"O paciente apresenta hipercalemia, sendo necessária a prescrição de diuréticos de alça para\ncontrole do potássio. Ele deve também ser referenciado para realização de colonoscopia para\nrastreio de câncer de cólon.","B":"O paciente apresenta hipercalemia, sendo necessária a prescrição de diuréticos de alça para\ncontrole do potássio. Ele deve também repetir o exame de sangue oculto nas fezes, uma vez que\nsão necessárias 3 amostras positivas.","C":"O paciente apresenta hipercalemia, sendo necessária a suspensão da losartana para controle\ndo potássio - devendo ser substituída por\natenolol, que também é um medicamento de primeira\nlinha para tratamento da HAS. Ele deve também ser referenciado para realização de colonoscopia\npara rastreio de câncer de cólon.","D":"O paciente apresenta hipercalemia, sendo necessária a suspensão da losartana para controle\ndo potássio - devendo ser substituída por\nindapamida, que também é um medicamento de primeira\nlinha para o tratamento da HAS. Ele deve também ser referenciado para realização de\ncolonoscopia para rastreio de câncer de cólon.","E":"O paciente apresenta hipercalemia, sendo necessária a suspensão da losartana para controle\ndo potássio - devendo ser substituída por\nindapamida, que também é um medicamento de primeira\nlinha para tratamento da HAS. Ele deve também repetir o exame de sangue oculto nas fezes, uma\nvez que são necessárias 3 amostras positivas."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-322147","number":"322147","sourceNumber":"322147","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação à classificação da insuficiência cardíaca, segundo a American Heart\nAssociation (AHA), é correto afirmar que:","options":{"A":"Um homem de 56 anos, com Fração de Ejeção (FE) de 36% no ecocardiograma, é considerado\nclasse A.","B":"Uma mulher caucasiana de 61 anos, com hipertensão arterial e sem alterações no ECG e/ou no\necocardiograma, é considerada classe C.","C":"Uma mulher de 42 anos, portadora de miocardiopatia puerperal, com FE de 18% e quadro\nclinico refratário ao tratamento clínico otimizado, é considerada classe D.","D":"A presença de alterações cardíacas estruturais, sem sintomas de insuficiência cardíaca, é\nconsiderada classe C.","E":"A presença de dispneia aos pequenos esforços é considerada classe III."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-322148","number":"322148","sourceNumber":"322148","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um homem de 75 anos, portador de estenose mitral grave, procura atendimento médico\ncom queixa de dispneia e lipotimia. Sobre o exame físico desse paciente, é correto afirmar que","options":{"A":"a presença de estalido de abertura precoce é frequente.","B":"a hipofonese de B1 é comum.","C":"sinais de insuficiência cardíaca esquerda são comuns.","D":"o exame físico costuma ser normal.","E":"a hipofonese de B2 é característica."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-322163","number":"322163","sourceNumber":"322163","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Sobre o carvedilol, assinale a alternativa correta.","options":{"A":"Sua dose máxima recomendada é 100 mg duas vezes ao dia.","B":"É considerado uma medicação de primeira escolha nos casos de hipertensão arterial sistêmica.","C":"Está contraindicado nos pacientes com bloqueio atrioventricular avançado.","D":"Está indicado nos casos de insuficiência cardíaca descompensada, principalmente nos\npacientes com perfil frio e úmido.","E":"Pode ser associado ao propranolol nos pacientes portadores de fibrilação arterial."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-322207","number":"322207","sourceNumber":"322207","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dona Marli queixa-se de edema de membros inferiores após iniciar uso de\nmedicamento para controlar sua pressão\narterial e procura atendimento para realizar a troca do\nremédio, pois sente-se muito incomodada. O fármaco em questão deve ser","options":{"A":"hidroclorotiazida.","B":"losartana.","C":"enalapril.","D":"anlodipino.","E":"atenolol."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-322211","number":"322211","sourceNumber":"322211","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Homem de 44 anos chega para consulta acompanhado da esposa, a qual reclama que\nele ronca muito à noite. Ao final da avaliação, o médico explica que o diagnóstico provável é de\napneia obstrutiva do sono. A orientação do profissional deve ser de que tal condição é fator de\nrisco\npara","options":{"A":"sinusopatia.","B":"hipertensão arterial sistêmica.","C":"pneumonia.","D":"asma brônquica.","E":"doença pulmonar obstrutiva crônica."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-337594","number":"337594","sourceNumber":"337594","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Roberto, um homem de 58 anos, é portador de hipertensão arterial, diabetes mellitus e\nhipotireoidismo. Há cerca de dois meses, ele sofreu um AVE isquêmico, apresentando diminuição\nde força em dimidio esquerdo, necessitando de auxílio para marcha. Desde que ocorreu o AVEi,\nRoberto não recuperou completamente a função cognitiva, apresentando dificuldade em\ncompreender fala, acalculia e diminuição da memória de curto prazo. Considerando o caso descrito\ne seus conhecimentos, julgue o item a seguir. O tratamento adequado da hipertensão arterial com\nmedicamentos de primeira linha (IECA, BRA, bloqueadores de canal de cálcio diidropiridínicos ou\ndiuréticos tiazídicos) reduz o risco de eventos como um AVEi.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-305289","number":"305289","sourceNumber":"305289","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O uso da medicação sacubitril-valsartana está indicado em qual das seguintes\ndoenças?","options":{"A":"Hipertensão arterial refratária.","B":"Miocardiopatia isquêmica.","C":"Fibrilação atrial.","D":"Insuficiência cardíaca com fração de ejeção reduzida.","E":"Hipertensão arterial sistêmica associada à diabetes mellitus."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-305301","number":"305301","sourceNumber":"305301","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma mulher de 75 anos procura atendimento médico com queixa de falta de ar aos\nmínimos esforços. Possui histórico de insuficiência cardíaca com fração de ejeção reduzida. Ao\nexame, apresenta estertores crepitantes em bases pulmonares, Pressão Arterial (PA): 160 x 100\nmmHg, perfusão distal adequada e edema de membros inferiores. Diante do exposto, assinale a\nalternativa CORRETA.","options":{"A":"O uso de dobutamina diminui o risco de morte.","B":"Apresenta perfil hemodinâmico quente e úmido.","C":"Expansão volêmica com cristaloides está indicado nesse caso.","D":"O uso de milrinone está indicado e impacta na sobrevida da paciente.","E":"O uso de garrotes em membros, para diminuir a pós-carga, está indicado."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-298950","number":"298950","sourceNumber":"298950","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Pode-se associar um\nbetabloqueador, como o propranolol, ao tratamento anti-hipertensivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-298951","number":"298951","sourceNumber":"298951","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Uma boa opção, como\nterceiro fármaco anti-hipertensivo, seria um bloqueador dos receptores de angiotensina ? (BRA),\ncomo a losartana, visto que diminuiria o risco cardiovascular, além de auxiliar na nefroproteção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-298952","number":"298952","sourceNumber":"298952","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg nos\núltimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Fatores socioeconômicos\npodem acarretar risco significativo para hipertensão arterial, como, por exemplo, baixa renda\nfamiliar e menor escolaridade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261216","number":"261216","sourceNumber":"261216","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Esse paciente apresenta estenose mitral com repercussão\nclínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-284284","number":"284284","sourceNumber":"284284","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A hipertensão arterial atinge grande parte dos brasileiros e contribui para a\nmorbimortalidade cardiovascular. Em 2016, a Sociedade\nBrasileira de Cardiologia publicou a\nSétima Diretriz Brasileira de Hipertensão Arterial. De acordo com essa diretriz, julgue o item a\nseguir. A hipotensão ortostática é definida como uma redução > 20 mmHg da pressão arterial\nsistólica ou 10 mmHg da pressão arterial diastólica em pacientes que estejam, há três minutos, na\nposição ortostática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261217","number":"261217","sourceNumber":"261217","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O reparo cirúrgico da valva com próteses metálicas é preferível\npor reduzir o risco de hemólise e a necessidade de anticoagulação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-284285","number":"284285","sourceNumber":"284285","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A hipertensão arterial atinge grande parte dos brasileiros e contribui para a\nmorbimortalidade cardiovascular. Em 2016, a Sociedade Brasileira de Cardiologia publicou a\nSétima Diretriz Brasileira de Hipertensão Arterial. De acordo com essa diretriz, julgue o item a\nseguir. Pacientes que apresentam pressão de 120 x 80 mmHG no consultório médico e de 150 x\n100 mmHg na monitorização ambulatorial de pressão arterial (MAPA) de 24 horas são definidos\ncomo portadores de hipertensão do avental branco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-284286","number":"284286","sourceNumber":"284286","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A hipertensão arterial atinge grande parte dos brasileiros e contribui para a\nmorbimortalidade cardiovascular. Em 2016, a Sociedade\nBrasileira de Cardiologia publicou a\nSétima Diretriz Brasileira de Hipertensão Arterial. De acordo com essa diretriz, julgue o item a\nseguir. A melhor combinação medicamentosa para pacientes com doença renal crônica em estágio\nIV é a de inibidores da ECA com bloqueadores do receptor de angiotensina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261219","number":"261219","sourceNumber":"261219","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A evolução da patologia descrita cursa com aumento pressórico\ndo leito vascular pulmonar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-274364","number":"274364","sourceNumber":"274364","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente, masculino, 63 anos, obeso e sedentário, vai à consulta de avaliação de rotina\npelo programa saúde da família. Durante a anamnese, o paciente se queixa de edema de membros\ninferiores, poliúria e crises de dor em hálux e tornozelos, com diagnóstico de artrite gotosa. Nega\noutras doenças ou uso de medicação contínua. Ao exame físico, apresenta-se corado, hidratado,\ncom PA: 190/110, FC: 88, FR: 16, SO2: 98% em ar ambiente, com ausculta pulmonar sem\nalterações, hiperfonese de B2 em foco aórtico e edema de membros inferiores ++/4+. Referente a\nesse caso, qual é a conduta mais adequada?","options":{"A":"Orientar sobre cuidados e hábitos de vida, diagnosticar hipertensão arterial sistêmica e iniciar\ndiurético tiazídico.","B":"Diagnosticar síndrome metabólica e iniciar hipoglicemiante biguanida.","C":"Orientar sobre cuidados e hábitos de vida e solicitar monitorização ambulatorial da pressão\narterial sistêmica.","D":"Orientar sobre cuidados e hábitos de vida, diagnosticar hipertensão arterial sistêmica e iniciar\ninibidor de enzima conversora de angiotensina.","E":"Orientar sobre cuidados e hábitos de vida e orientar retorno em 3 meses para reavaliação."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261233","number":"261233","sourceNumber":"261233","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente com história de dor torácica aos esforços comparece à consulta por estar\nmais cansado do que o normal. Refere que vem\napresentando ortopneia e dispneia paroxística\nnoturna. Foram realizados investigação laboratorial, Holter, ecocardiograma e cateterismo cardíaco.\nO ecocardiograma e o cateterismo estão representados a seguir. Tendo em vista esse caso clínico,\nas imagens apresentadas e os conhecimentos médicos correlatos, julgue o item a seguir. O\necocardiograma do paciente apresenta fração de ejeção reduzida, sendo necessária, o mais\nprecocemente possível, a introdução de sacubitril com valsartana em relação à angioplastia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/261233.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261234","number":"261234","sourceNumber":"261234","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente com história de dor torácica aos esforços comparece à consulta por estar\nmais cansado do que o normal. Refere que vem\napresentando ortopneia e dispneia paroxística\nnoturna. Foram realizados investigação laboratorial, Holter, ecocardiograma e cateterismo cardíaco.\nO ecocardiograma e o cateterismo estão representados a seguir. Tendo em vista esse caso clínico,\nas imagens apresentadas e os conhecimentos médicos correlatos, julgue o item a seguir. O\neletrocardiograma desse paciente pode apresentar alterações isquêmicas, como onda plus minus\nem derivações precordiais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/261234.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-274370","number":"274370","sourceNumber":"274370","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente, 65 anos, masculino, previamente hipertenso, em uso regular da medicação, é\nadmitido no setor de urgência com quadro de aumento pressórico de forma rápida, associado à\ncefaleia holocraniana, vômitos e confusão mental. Nega demais sintomas associados, como febre.\nNa admissão, está com PA: 210/130 mmHg, FC: 60bpm, FR: 14 ipm, SO2: 96% em ar ambiente. A\nrespeito desse o quadro, é CORRETO afirmar que:","options":{"A":"Deve-se considerar o diagnóstico de crise hipertensiva, com encefalopatia hipertensiva, e a meta\né redução da PA média em 10 a 15% na primeira\nhora e até 25% no primeiro dia de tratamento.","B":"O diagnóstico é crise de migrânea, sendo o tratamento a analgesia forte e hidratação.","C":"O diagnóstico é hipertensão intracraniana e deve ser feita imediata punção de líquido\ncefalorraquidiano.","D":"Devem ser feitos controle com medicação anti-hipertensiva via oral e solicitação de exames para\nanálise de possível lesão de órgão-alvo.","E":"Um dos diagnósticos diferenciais do quadro neurológico é hipertensão maligna e, nesse caso,\ndeve ser feita ressonância para diferenciar etiologias."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261237","number":"261237","sourceNumber":"261237","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de 35 anos de idade, com miocardiopatia isquêmica dilatada com fração\nde ejeção prévia de 30%, encaminha-se à\nemergência com dor torácica em aperto há sete horas,\ndispneia importante e sudorese. Foram solicitados exames laboratoriais que demonstram\nhemograma normal, função renal e eletrólitos normais. Seu peptídeo natriurético cerebral (BNP) era\nde 300 pg/mL (valor de referência até 150 pg/dL). Solicitou-se, então o eletrocardiograma\nrepresentado na figura a seguir. Considerando esse caso clínico, a figura apresentada e os\nconhecimentos médicos correlatos, julgue o item a seguir. Miocardiopatia isquêmica dilatada é a\nforma mais rara das miocardiopatias dilatadas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/261237.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-274392","number":"274392","sourceNumber":"274392","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A miocardiopatia hipertrófica é a doença genética cardiovascular mais comum. Assinale\na alternativa INCORRETA sobre o tema.","options":{"A":"É de grande importância por ser uma das principais causas de morte súbita nos jovens e, como\no exercício físico é um dos principais\ndesencadeantes da morte súbita, há contraindicação absoluta\npara participação em atividades esportivas competitivas.","B":"Muitos indivíduos que carregam o defeito genético só vão expressar clinicamente a doença em\nidade mais avançada. Durante a aceleração do crescimento corporal na adolescência, ocorre um\nremodelamento do ventrículo esquerdo com aparecimento da hipertrofia, sendo que, em geral, o\npico da expressão morfológica da doença instala-se entre 17 e 21 anos de idade.","C":"A ecocardiografia detecta a hipertrofia ventricular esquerda na ausência de doenças sistêmicas\nou de outras anomalias cardíacas. O\neletrocardiograma é anormal na maioria dos pacientes, com\npadrão variável, mostrando fraca correlação com a intensidade da hipertrofia vista ao\necocardiograma.","D":"Fortes fatores de risco para morte súbita incluem: história de parada cardíaca ou de taquicardia\nventricular sustentada, história familiar de morte súbita, síncope, principalmente quando recorrente\nou relacionada com exercício, hipotensão arterial em resposta ao exercício.","E":"Para prevenção de morte súbita, o tratamento que tem se mostrado mais eficaz é o uso contínuo\nde antiarrítmicos. A ablação com álcool é uma\nalternativa boa para os pacientes pediátricos que\nnão toleram a medicação."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261305","number":"261305","sourceNumber":"261305","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dl; colesterol HDL = 32 mg/dl; colesterol LDL = 192,3 mg/dl; e creatinina sérica =\n1,32 mg/dl. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92% com\nníveis tensionais confirmados em duas consultas com mais de quatro semanas entre elas.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nTrata-se de um caso de HAS estágio 2.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261306","number":"261306","sourceNumber":"261306","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dl; colesterol HDL = 32 mg/dl; colesterol LDL = 192,3 mg/dl; e creatinina sérica =\n1,32 mg/dl. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92% com\nníveis tensionais confirmados em duas consultas com mais de quatro semanas entre elas.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. O\ntratamento indicado é a realização de medidas não farmacológicas (mudanças no estilo de vida) e\nreavaliação em três meses.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261308","number":"261308","sourceNumber":"261308","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dL; colesterol HDL = 32 mg/dL; colesterol LDL = 192,3 mg/dL; e creatinina sérica\n\n= 1,32 mg/dL. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92%\ncom níveis tensionais confirmados em duas\nconsultas com mais de quatro semanas entre elas.\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nTendo em vista o histórico de IAM prévio e as demais comorbidades, além do controle pressórico,\ntambém é recomendado o controle dos fatores de risco, tais como controle glicêmico, cessar\ntabagismo, uso de AAS e estatinas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-261309","number":"261309","sourceNumber":"261309","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Determinado paciente de 58 anos de idade, tabagista, com histórico de IAM há cinco\nanos e DM2, em uso de metformina, comparece\nà consulta com os seguintes exames laboratoriais:\nglicemia = 136 mg/dL; colesterol HDL = 32 mg/dL; colesterol LDL = 192,3 mg/dL; e creatinina sérica\n\n= 1,32 mg/dL. Apresenta medida de PA = 165 mmHg x 102 mmHg. FC = 80 bpm, SatO2 = 92%\ncom níveis tensionais confirmados em duas\nconsultas com mais de quatro semanas entre elas.\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nEntre as drogas de primeira linha para tratamento da hipertensão, encontram-se os diuréticos\ntiazídicos, IECA, betabloqueadores e antagonistas dos canais de cálcio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-255786","number":"255786","sourceNumber":"255786","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No que se refere aos conhecimentos relacionados a bioética, saúde mental,\nendocrinologia, dermatologia e cardiologia, julgue o\nitem a seguir. Os digitálicos são medicamentos\nque reduzem a mortalidade por insuficiência cardíaca congestiva.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-214520","number":"214520","sourceNumber":"214520","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A paciente W. B. R., 52 anos de idade, faz acompanhamento no posto de saúde da\nrespectiva comunidade em razão do diagnóstico de insuficiência cardíaca com fração de ejeção\nreduzida. Ela levou à consulta o ECG apresentado. (Velocidade do papel = 25 mm/s; 1 cm = 1mv).\nCom relação a esse caso clínico, julgue o item a seguir. Nesse traçado eletrocardiográfico,\nobserva-se a presença de bloqueio de ramo direito associado a bloqueio posteroinferior do ramo\nesquerdo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/214520.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-214505","number":"214505","sourceNumber":"214505","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A paciente W. B. R., 52 anos de idade, faz acompanhamento no posto de saúde da\nrespectiva comunidade em razão do diagnóstico de insuficiência cardíaca com fração de ejeção\nreduzida. Ela levou à consulta o ECG apresentado. (Velocidade do papel = 25 mm/s; 1 cm = 1mv).\nCom relação a esse caso clínico, julgue o item a seguir. A pericardite constritiva deve ser\nconsiderada, em razão das alterações eletrocardiográficas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/214505.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-179174","number":"179174","sourceNumber":"179174","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Com relação à abordagem terapêutica da hipertensão arterial em paciente com\nsíndrome metabólica, é correto afirmar que","options":{"A":"o controle da pressão arterial com apenas uma droga ocorra em cerca de 2/3 dos pacientes\nhipertensos.","B":"seu objetivo seja a redução da pressão arterial para valores abaixo de 140 mmHg/ 90 mmHg,\nconsiderando-se o elevado risco cardiovascular associado.","C":"a presença de nefropatia com proteinúria importante implique em redução da pressão arterial\npara valores abaixo de 130 mmHg/85 mmHg.","D":"a pressão arterial deva ser reduzida para valores abaixo de 140 mmHg/ 90 mmHg em\nassociação com diabetes tipo 2.","E":"a associação de drogas seja indicada desde o início do tratamento anti-hipertensivo quando a\npressão arterial for \"maior ou igual\"160 mmHg/ 100 mmHg."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-177611","number":"177611","sourceNumber":"177611","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"M.C.L., sexo feminino, de 76 anos de idade, é paciente com diagnóstico de insuficiência\ncardíaca com fração de ejeção reduzida\n(40%), atualmente com classe funcional NYHA II. Como\ncomorbidades, apresenta HAS, DM e fibrilação atrial fixa. Considerando o quadro dessa paciente e\nsua patologia, julgue o item a seguir. Níveis elevados de BNP poderiam embasar a prescrição de\nespironolactona para essa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-177552","number":"177552","sourceNumber":"177552","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"M.C.L., sexo feminino, de 76 anos de idade, é paciente com diagnóstico de insuficiência\ncardíaca com fração de ejeção reduzida\n(40%), atualmente com classe funcional NYHA II. Como\ncomorbidades, apresenta HAS, DM e fibrilação atrial fixa. Considerando o quadro dessa paciente e\nsua patologia, julgue o item a seguir. A prescrição de diuréticos de alça e o controle das doses\nutilizadas têm base em parâmetros clínicos de sobrecarga de volume.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-177640","number":"177640","sourceNumber":"177640","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos Cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. A medida da\npressão arterial é indicada para a faixa etária da paciente, devendo-se realizar essa medida\nanualmente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-154361","number":"154361","sourceNumber":"154361","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"L. A. P., 42 anos de idade, bancário, comparece ao ambulatório de clínica médica para\navaliação. Ele relata ao médico residente que passa por quadro de dispneia, ortopneia, dispneia\nparoxística noturna e rouquidão há três anos, com piora recente, inclusive com um episódio\nhemoptoico. Aponta ainda que apresentou dois episódios de síncope no trabalho, após intensa\nangústia, sudorese fria e tremores em extremidades superiores. Clinicamente, apresenta discreto\nedema em membros inferiores. O exame do aparelho respiratório encontra-se dentro dos\nparâmetros de normalidade. O aparelho cardiovascular apresenta ritmo irregular, percebendo-se\nruflar diastólico após estalido de abertura e BI e PI hiperfonéticas. Com base nesse caso e nos\nexames complementares, assinale a alternativa que indica o quadro da paciente.","options":{"A":"Estenose aórtica; eletrocardiograma esboça aumento atrial esquerdo e hipertrofia ventricular\nesquerda; ecocardiograma com hipertrofia ventricular\nesquerda concêntrica, separação reduzida\ndas cúspides da valva aórtica e Doppler mostrando gradiente acentuado nos casos graves.","B":"Insuficiência mitral; eletrocardiograma esboça aumento atrial esquerdo e hipertrofia ventricular\nesquerda; ecocardiograma com aumento de ventrículo\nesquerdo, hipertrofia ventricular esquerda e\nDoppler com grande jato regurgitante.","C":"Estenose mitral; eletrocardiograma esboça aumento atrial esquerdo e hipertrofia ventricular\ndireita; ecocardiograma com movimento restrito dos\nfolhetos de valva mitral e Doppler tricúspide\npode revelar hipertensão pulmonar.","D":"Insuficiência aórtica; eletrocardiograma esboça aumento atrial esquerdo e hipertrofia ventricular\nesquerda; ecocardiograma mostra, para os casos\ncrônicos, grande aumento de ventrículo esquerdo\ne, para os agudos, ventrículo esquerdo pequeno e pré-fechamento de válvula mitral.","E":"Insuficiência pulmonar; eletrocardiograma esboça aumento atrial direito e hipertrofia ventricular\ndireita; ecocardiograma mostra, para os casos crônicos,\ngrande aumento de ventrículo direito e,\npara os agudos, ventrículo direito pequeno e pré-fechamento de válvula tricúspide."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-152147","number":"152147","sourceNumber":"152147","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente, 40 anos de idade, foi ao pronto-socorro por anasarca, espuma na urina e\nhipertensão (160 x 100 mmHg). Apresenta exames de função renal sérica normais. Fez exame de\nurina que demonstrou proteína +++. Realizou proteinúria de 24 horas, que demonstrou 5 g de\nproteínas. Considerando essa situação, julgue o item a seguir. Casos dessa síndrome geralmente\ncursam com perda de função renal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-131810","number":"131810","sourceNumber":"131810","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Segundo a Sociedade Brasileira de Cardiologia, com relação à Hipertensão Arterial\nSistêmica (HAS) e seus fatores de risco, assinale a alternativa CORRETA:","options":{"A":"Inexiste relação entre a pressão arterial e a idade do indivíduo.","B":"A prevalência global de HAS é mais elevada nas mulheres até os 50 anos de idade.","C":"Embora a população brasileira apresente uma dieta rica em sódio, carboidratos e gorduras, a\nelevação da pressão arterial não se relaciona com o consumo elevado de sódio.","D":"A ingesta de bebidas alcoólicas por um período de tempo prolongado pode aumentar os níveis\nde pressão arterial.","E":"A atividade física reduz a incidência de HAS apenas em indivíduos previamente hígidos, não\napresentando o mesmo efeito em indivíduos pré-hipertensos."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-135122","number":"135122","sourceNumber":"135122","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma paciente de cinquenta e cinco anos de idade foi internada em uma enfermaria de\nclínica médica por apresentar, havia três meses, dispneia associada a tosse seca toda noite. Esse\nquadro tende a melhorar vinte minutos após a paciente assumir posição ortostática. A paciente não\napresenta hemoptise, dor torácica, cianose, febre, sudorese ou calafrios e não há antecedentes\nmórbidos na história patológica pregressa. O exame físico mostrou PA de 180 x 100 mmHg,\nfrequência cardíaca de 110 bpm e saturação de oxigênio, ao ar ambiente, de 89%. Foi identificado\nsopro sistólico em foco mitral com a presença de B3, diminuição do murmúrio vesicular e sibilos em\nambas as regiões infraescapulares. As extremidades da paciente não apresentam edema.\n\nIdentificou-se, na radiografia de tórax, derrame pleural bilateral e aumento da cavidade cardíaca.\nCom relação a esse caso clínico, julgue o item\na seguir. Essa paciente deve ser submetida a\ntoracocentese para se investigar a ocorrência de síndrome de derrame pleural.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-135127","number":"135127","sourceNumber":"135127","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma paciente de cinquenta e cinco anos de idade foi internada em uma enfermaria de\nclínica médica por apresentar, havia três meses, dispneia associada a tosse seca toda noite. Esse\nquadro tende a melhorar vinte minutos após a paciente assumir posição ortostática. A paciente não\napresenta hemoptise, dor torácica, cianose, febre, sudorese ou calafrios e não há antecedentes\nmórbidos na história patológica pregressa. O exame físico mostrou PA de 180 x 100 mmHg,\nfrequência cardíaca de 110 bpm e saturação de oxigênio, ao ar ambiente, de 89%. Foi identificado\nsopro sistólico em foco mitral com a presença de B3, diminuição do murmúrio vesicular e sibilos em\nambas as regiões infraescapulares. As extremidades da paciente não apresentam edema.\n\nIdentificou-se, na radiografia de tórax, derrame pleural bilateral e aumento da cavidade cardíaca.\nCom relação a esse caso clínico, julgue o item\na seguir. A história clínica dessa paciente indica que\nela apresenta dispneia paroxística noturna.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-135119","number":"135119","sourceNumber":"135119","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma paciente de cinquenta e cinco anos de idade foi internada em uma enfermaria de\nclínica médica por apresentar, havia três meses, dispneia associada a tosse seca toda noite. Esse\nquadro tende a melhorar vinte minutos após a paciente assumir posição ortostática. A paciente não\napresenta hemoptise, dor torácica, cianose, febre, sudorese ou calafrios e não há antecedentes\nmórbidos na história patológica pregressa. O exame físico mostrou PA de 180 x 100 mmHg,\nfrequência cardíaca de 110 bpm e saturação de oxigênio, ao ar ambiente, de 89%. Foi identificado\nsopro sistólico em foco mitral com a presença de B3, diminuição do murmúrio vesicular e sibilos em\nambas as regiões infraescapulares. As extremidades da paciente não apresentam edema.\n\nIdentificou-se, na radiografia de tórax, derrame pleural bilateral e aumento da cavidade cardíaca.\nCom relação a esse caso clínico, julgue o item\na seguir. O nível de 89% para saturação de oxigênio\nao ar ambiente indica que a PaO2 da paciente apresenta menos de 60 mmHg, bem como quadro\nde insuficiência respiratória.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-135109","number":"135109","sourceNumber":"135109","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Com relação aos tratamentos de doenças cardiovasculares, julgue o item seguinte. O\npeso do paciente é um fator a ser\nconsiderado para definir se existe, ou não, a necessidade de ele\nrealizar tratamento contra doenças cardiovasculares, e uma das medidas físicas utilizadas para\navaliar a coerência desse procedimento é a circunferência da cintura. Considera-se, então, que\nmedidas das circunferências abdominais acima de 88 cm em mulheres e acima de 100 cm em\nhomens implicam indicação para o tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-108126","number":"108126","sourceNumber":"108126","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A hipertensão arterial, que se associa a alterações metabólicas, hormonais e a\nfenômenos tróficos, é uma doença de causa\nmultifatorial que acomete cerca de 15% a 20% da\npopulação brasileira adulta. Acerca dessa patologia, julgue o item subsecutivo. O exame de fundo\nde olho permite identificar lesões no sistema vascular de pacientes portadores de hipertensão\narterial sistêmica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-105537","number":"105537","sourceNumber":"105537","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"De acordo com o último relatório do <i>Joint National Committee</i>, o oitavo, (JNC\nVIII) publicado no início deste ano (2014), a\nrecomendação para adultos maiores de sessenta anos\nde idade é que se introduza terapêutica anti-hipertensiva para valores de pressão, em mmHg:","options":{"A":"> 120 x 80.","B":"> 135 x 85.","C":"> 139 x 85.","D":"\"Maior ou igual a\" 140 x 90.","E":"\"Maior ou igual a\" 150 x 90."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-108216","number":"108216","sourceNumber":"108216","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de setenta e dois anos de idade, com antecedente de hipertensão arterial\nhá vários anos, compareceu ao ambulatório\nrelatando dispneia decorrente de esforços maiores que\nos habituais, como subir escadas ou andar apressadamente. O paciente relatou, ainda, o uso\nirregular de um anti-hipertensivo prescrito (clortalidona). No exame físico, o idoso apresentou-se\nnormocorado, com extremidades quentes, frequência cardíaca de 108 bpm, pressão arterial de 154\nmmHg x 72 mmHg, turgência jugular a 30°, ausculta pulmonar normal, ictus cordis propulsivo no 6º\nespaço intercostal esquerdo da linha axilar anterior, ritmo cardíaco em galope (terceira bulha) e\nsem sopros. Adicionalmente, notou-se refluxo hepatojugular e edema perimaleolar bilateral. Os\nexames laboratoriais revelaram sódio de 144 mEq/L; potássio de 5,4 mEq/L; creatinina de 3,2\nmg/dl; hemoglobina de 10,4 g/dL; e hematócrito de 31%. Os demais exames bioquímicos e a\nfunção tireoidiana estavam normais. O ecocardiograma revelou fração de ejeção de 36%. Com\nreferência ao caso clínico acima apresentado, julgue o item que se segue. O captopril e a\nespironolactona devem ser acrescentados à terapêutica inicial visando melhora da qualidade de\nvida e aumento na sobrevida desse paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-88710","number":"88710","sourceNumber":"88710","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Acerca de doenças crônicas, julgue o item subsequente. Pacientes com hipertensão\narterial maligna apresentam frequentemente\ninsuficiência renal progressiva e retinopatia com\nexsudatos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-82121","number":"82121","sourceNumber":"82121","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Acerca das doenças dos cuidados de saúde em pessoas idosas, julgue o item a seguir:\nDurante a medida da pressão arterial em idosos, pode ocorrer maior frequência de hiato\nauscultatório, subestimando a verdadeira pressão sistólica ou superestimando a pressão diastólica,\ne a pseudo-hipertensão, que pode ser detectada por meio da manobra de Osler.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-88646","number":"88646","sourceNumber":"88646","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Acerca de doenças cardiovasculares e hipertensão, julgue o item a seguir. Para\npacientes hipertensos que apresentam pressão\narterial controlada, a prescrição de ácido\nacetilsalicílico em baixas doses diminuem a ocorrência de complicações cardiovasculares, desde\nque o uso deste medicamento não seja contraindicado ao paciente e gere mais benefícios que\neventuais riscos a sua saúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-45714","number":"45714","sourceNumber":"45714","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Considere que um médico assistente tenha constatado, em um paciente de 22 anos de\nidade com diagnóstico de cardiopatia reumática, entre outros achados semiológicos, a presença de\num sopro holossistólico, melhor audível na área tricúspide - com intensidade grau ll segundo a\nclassificação de Levine -, intensificado pela realização da manobra de Müller. Com base nessas\ninformações, assinale a alternativa CORRETA.","options":{"A":"A intensidade do sopro em análise sugere, com alta possibilidade de acerto, insuficiência mitral\nleve.","B":"A intensificação do sopro em estudo, pela manobra realizada, indica a presença de regurgitação\ntricúspide.","C":"A descrição do sopro permite inferir que há frêmito cardíaco associado.","D":"A manobra realizada é utilizada para induzir incremento na pós-carga de trabalho do coração.","E":"A manobra de handgrip (preensão manual) pode substituir a manobra de Müller realizada, pois\nesses procedimentos clínicos compartilham a mesma base fisiopatológica."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-45726","number":"45726","sourceNumber":"45726","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma senhora de 32 anos de idade procurou atendimento médico com relato de que há\nseis meses passou a apresentar fadiga, dispneia aos grandes esforços, edema de membros\ninferiores, dor no hipocôndrio direito e a sensação de empachamento pós-prandial. Negou doenças\nanteriores, tabagismo, e etilismo. Seu exame físico mostrou: paciente emagrecida, frequência\ncardíaca de 90 bpm, pressão arterial de 100 x 80 mmHg, com evidência de pulso paradoxal,\nturgência jugular observada com cabeceira do leito elevada a 40°, aumento da pressão venosa\njugular durante a inspiração profunda, presença de retração intercostal (simultânea com a sístole\ncardíaca) observada no décimo primeiro e décimo segundo espaços intercostais esquerdos, ritmo\ncardíaco regular em dois tempos, bulhas hipofonéticas, com presença de knock após a segunda\nbulha cardíaca em área tricúspide. Aparelho respiratório sem anormalidades. Abdome:\nhepatomegalia dolorosa sem ascite. Extremidades: edema de membros inferiores, mole, frio e\nindolor. O eletrocardiograma apresentou: ritmo sinusal, frequência ventricular média de 92 spm,\nSÂQRS = + 120°, onda P entalhada em derivação D2, baixa voltagem do complexo QRS no plano\nfrontal e alterações difusas e inespecíficas da repolarização ventricular. Com base nessa situação\nclínica hipotética, assinale a alternativa que apresenta a principal hipótese diagnóstica.","options":{"A":"Pericardite constritiva.","B":"Cor pulmonale.","C":"Mixoma atrial.","D":"Cardiomiopatia hipertrófica.","E":"Miocardite viral."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-52637","number":"52637","sourceNumber":"52637","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Julgue o item a seguir relativo a emergências cardiovasculares. \"Dissecções agudas da\naorta com envolvimento da aorta ascendente são consideradas emergências cirúrgicas devido ao\nelevado risco de ruptura aórtica, de tamponamento cardíaco, de insuficiência aórtica aguda e grave\ne de acidente vascular encefálico.\"","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-32190","number":"32190","sourceNumber":"32190","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Pedro, dezenove anos de idade, procurou atendimento médico e relatou que há uma\nsemana tem apresentado febre e dor\narticular no cotovelo direito, no tornozelo direito e no punho\nesquerdo (não simétrica e migratória). Nos últimos três dias, passou a apresentar dispneia ao\nexecutar atividades físicas menos intensas que as habituais e ortopneia, e relata sentir há dois\ndias\ndor precordial leve e continua. Seu exame clínico mostrou palidez cutânea, aceitando mal o\ndecúbito horizontal. O exame físico constatou temperatura axilar de 38,2ºC, pressão arterial de 120\nmmHg x 72 mmHg, frequência cardíaca de 110 bpm. Ictus cordis localizado no sétimo espaço\nintercostal esquerdo, na linha axilar média esquerda, com 5 cm de extensão, impulsivo, ritmo\ncardíaco regular e tríplice (por terceira bulha), bulhas hipofonéticas e taquicárdicas, presença de\nsopro holossistólico, mais bem audível no foco mitral, irradiado para região axilar, grau 3\n(classificação de Levine), que não sofreu intensificação com a manobra de Mueller; na borda\nesternal esquerda baixa, foi auscultado atrito pericárdico. Havia estertores pulmonares em terços\ninferiores de ambos os hemitórax. Abdome livre e sem visceromegalias. Dor à palpação do cotovelo\ndireito, sem sinais flogísticos. O Eletrocardiograma (ECG) mostrou taquicardia sinusal, frequência\nventricular media de 115 spm, bloqueio atrioventricular de primeiro grau, sobrecarga de câmaras\nesquerdas, extrassístoles ventriculares isoladas e alterações difusas e secundárias da\nrepolarização ventricular. O resultado das hemoculturas colhidas foi negativo. O hemograma\nevidenciou discreta leucocitose, sem anemia. Observaram-se aceleração da Velocidade de\nHemossedimentação (VHS), elevação dos níveis séricos de antiestreptolisina O e de proteína C\nreativa. No texto, foi mencionada a realização da manobra de Mueller durante a ausculta cardíaca\ndo paciente. Acerca dessa manobra propedêutica, assinale a alternativa correta.","options":{"A":"Consiste em colocar o paciente na posição chamada \"prece maometana\" e, assim, aproximar o\ncoração da parede torácica.","B":"Durante essa manobra, o paciente deve fazer uma expiração forçada com a glote fechada e, ao\nlongo da fase de expiração, busca-se induzir o aumento da pressão intratorácica e a redução da\npré-carga de trabalho do ventrículo direito.","C":"Nessa manobra, o paciente assume a posição de cócoras e com isso promove-se aumento da\npós-carga de trabalho do ventrículo esquerdo.","D":"Nesse procedimento, solicita-se ao paciente que realize uma inspiração profunda com a glote\nfechada; induzindo, assim, redução da pressão\nintratorácica e aumento da pré-carga de trabalho do\nventrículo direito.","E":"Para a realização dessa manobra, pede-se ao paciente que faça uma preensão manual (esforço\nisométrico), e dessa forma desencadeia-se uma elevação na pós-carga de trabalho do ventrículo\nesquerdo."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-37940","number":"37940","sourceNumber":"37940","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um rapaz com 18 anos de idade, em atendimento médico ambulatorial de um centro de\nsaúde, relatou inchaço no corpo, náuseas/vômitos matinais, anorexia, redução progressiva do\nvolume urinário e urina avermelhada, com início há uma semana. Relatou ter apresentado, havia\nduas semanas, infecção das vias aéreas (completamente resolvida) e negou outras doenças. No\nexame físico, ele se apresentava: normolíneo, em regular estado geral, com mucosas hipocoradas\n(+2/+4), frequência cardíaca de 105 bpm e pressão arterial de 150 mmHg x 110 mmHg (deitado,\nmedida no membro superior direito, usando-se bolsa inflável apropriada para a circunferência do\nbraço). Pulmões sem alterações. O exame cardiovascular revelou ictus cordis no quinto espaço\nintercostal e na linha hemiclavicular esquerda, com 2 cm de extensão, normoimpulsivo, ritmo\ncardíaco regular em 3 tempos (à custa de terceira bulha), sopro sistólico (+2/+6), suave, audível em\ntodos os\n\nfocos, presença de ruído compatível com atrito pericárdico, mais bem audível na borda esternal\nesquerda baixa. Abdome sem alterações. Edema\nem membros inferiores (+2/+4) até os joelhos,\nfrio, indolor, com sinal de Godet. Exames complementares evidenciaram: ureia = 130 mg/dl;\ncreatinina = 7 mg/dl; sódio plasmático = 140 mEq/L; potássio plasmático = 6,8 mEq/L; hematócrito\n\n= 28%; hemoglobina = 9,2 g/dl; leucograma normal; plaquetas = 250.000/mm³; EAS com ausência\nde glicose e de proteína; hemoglobina (++);\nhemácias = 25 por campo; leucócitos = 2 por campo;\ncilindros hemáticos (+++). Com base nas informações do quadro clínico acima, julgue o item. Nesse\nquadro clínico, durante a esfigmomanometria, como a relação entre as dimensões da bolsa inflável\ne a medida da circunferência do braço foi adequada, é correto inferir que o comprimento e a largura\ndessa bolsa inflável correspondiam a, respectivamente, 80% e 40% da medida da circunferência do\nmembro em questão.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27558","number":"27558","sourceNumber":"27558","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quanto ao tratamento para hipertensão arterial sistêmica (HAS), considere as seguintes\nafirmações, selecionando a correta.","options":{"A":"Os diuréticos tiazídicos são fármacos muito conhecidos e frequentemente utilizados no\ntratamento da HAS, devendo ser utilizados em\nbaixas doses, dado a sua capacidade de redução da\nmorbimortalidade em estudos de longo prazo.","B":"A seleção de um determinado fármaco para o tratamento da HAS deve considerar a sua\ntolerabilidade através de doses crescentes para que se possa tratar o distúrbio fisiopatológico\ncoexistente","C":"Metanálises dos estudos clínicos vêm demonstrando a importância de estabelecer metas de\npressão arterial mais baixa em pacientes idosos","D":"Os inibidores da ECA são agentes de escolha em pacientes com disfunção renal e estenose\nbilateral da artéria renal","E":"O estabelecimento de metas de pressão arterial mais baixa inclui grupos específicos de\npacientes como: diabéticos, jovens e portadores de lesão em órgão-alvo"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-27559","number":"27559","sourceNumber":"27559","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A Insuficiência Cardíaca (IC) é um importante problema de saúde pública em nosso\npaís e no mundo, responsável por relevante\ncontingente de hospitalizações e mortes na população\nadulta. Tratando-se desta questão, é CORRETO afirmar:","options":{"A":"A anemia grave pode interferir na função miocárdica ao acarretar anóxia miocárdica na presença\nde coronariopatia crônica subjacente.","B":"A IC de alto e baixo débito nem sempre são facilmente distinguíveis. A IC de baixo débito\ndecorre da redução da resistência vascular\nsistêmica e a de alto débito decorre da miocardiopatia\ndilatada, da cardiopatia isquêmica da valvopatia e da hipertensão.","C":"Dentre as causas precipitantes encontram-se a doença isquêmica, as miocardiopatias, as\ncardiopatias congênitas, valvares e hipertensivas.","D":"A fadiga e a fraqueza relacionam-se à redução da perfusão do músculo cardíaco.","E":"Na IC grave recomenda-se repouso absoluto no leito, na perspectiva de redução da carga sobre\no miocárdio e dos níveis da pressão arterial."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-7548","number":"7548","sourceNumber":"7548","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A doença de Chagas, enfermidade de caráter endêmico e com ampla distribuição no\nterritório nacional, volta a surpreender as autoridades sanitárias com a recente descoberta de casos\nagudos da doença. A respeito dessa doença, julgue os itens a seguir: I - A principal forma de\ntransmissão da doença é através da corrente sanguínea, com a inoculação do parasita através da\nsaliva do triatomíneo. II - Uma das apresentações da doença é o edema bipalpebral, conhecido\ncomo sinal de Romaña.\n\nIII - Resulta da infecção pelo protozoário Trypanosoma cruzi. IV - A forma aguda da doença de\nChagas é mais frequentemente vista em\nadultos na quarta década de vida. V - Nos pacientes\ninfectados, a reação de Machado Guerreiro é positiva. A quantidade de itens certos é igual a:","options":{"A":"1.","B":"2.","C":"3.","D":"4.","E":"5."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-7551","number":"7551","sourceNumber":"7551","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Hipertensão arterial sistêmica é a principal causa de morte no mundo. Acerca dessa\nafecção, assinale a alternativa incorreta.","options":{"A":"É fator de risco para acidente vascular cerebral, infarto do miocárdio, insuficiência cardíaca\ncongestiva e dissecção da aorta.","B":"Em sociedades menos industrializadas, nas quais o consumo de calorias e de sal é baixo, a\npressão arterial dos indivíduos não aumenta com o avançar da idade.","C":"Os níveis de pressão sistólica e diastólica de 120-139 e 80-89 mmHg, respectivamente, são\nconsiderados pré-hipertensão.","D":"Os inibidores de enzima conversora da angiotensina (ECA) e os antagonistas dos receptores\nATI da angiotensina II, apresentam perfil\nfarmacológico adequado para diabéticos hipertensos,\nespecialmente na vigência de nefropatia diabética.","E":"As anormalidades tireoidianas (hiper e hipotireoidismo) são as principais causas de hipertensão\nsecundária."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-13856","number":"13856","sourceNumber":"13856","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em uma consulta ambulatorial de clínica médica verificou-se, durante o exame físico\nem um paciente com 22 anos de idade\nassintomático cardiovascular, a presença de discreto\nabaulamento e impulsão sistólica da região paraesternal esquerda baixa, ritmo cardíaco regular em\n2 tempos, com hiperfonese e desdobramento amplo e fixo da segunda bulha cardíaca (que não\nvaria com as manobras de Rivero-Carvallo e de Valsalva) no foco pulmonar, sopro sistólico ejetivo\nno segundo espaço intercostal esquerdo, sem irradiação, ausência de cliques e estalidos. O\neletrocardiograma convencional e radiografia de tórax mostraram, respectivamente, ritmo sinusal,\neixo do QRS desviado para a direita, leve sobrecarga do ventrículo direito e bloqueio completo pelo\nramo direito do feixe de His; as imagens radiológicas evidenciaram vasos pulmonares periféricos e\ncentrais dilatados, aumento moderado da área cardíaca à custa das câmaras direitas e botão\naórtico pequeno. Nesse caso clínico, a principal hipótese diagnóstica é de:","options":{"A":"hipertensão arterial pulmonar.","B":"comunicação interatrial.","C":"estenose na valva pulmonar, grave.","D":"comunicação interventricular.","E":"persistência do canal arterial."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-334876","number":"334876","sourceNumber":"334876","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de 60 anos de idade com diagnóstico de insuficiência cardíaca congestiva\né submetido a exame ecocardiográfico que mostra\ndiminuição da fração de ejeção sistólica do\nventrículo esquerdo. Nesse caso, visando a reduzir o risco de mortalidade, a medicação mais\napropriada a ser prescrita é","options":{"A":"ácido acetilsalicílico.","B":"digoxina.","C":"diurético.","D":"bloqueador de cálcio.","E":"inibidor da enzima conversora de angiotensina."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-301251","number":"301251","sourceNumber":"301251","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. Os betabloqueadores estão indicados para\npacientes com insuficiência cardíaca associada à doença renal crônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-301252","number":"301252","sourceNumber":"301252","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. Bloqueadores do canal de cálcio e bloqueadores\ndo receptor AT1 da angiotensina II devem ser a primeira opção em pacientes transplantados renais\npor prevenirem a perda do enxerto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-301253","number":"301253","sourceNumber":"301253","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. A associação entre bloqueadores do receptor\nAT1 da angiotensina II e inibidores da enzima conversora de angiotensina é útil nos casos que\ncursam com albuminúria importante.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-301254","number":"301254","sourceNumber":"301254","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. A meta de tratamento de pacientes desse grupo\né a mesma para diabéticos e não diabéticos: pressão arterial <130 mmHg x 80 mmHg.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-301255","number":"301255","sourceNumber":"301255","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em pacientes hipertensos com doença renal crônica, existem particularidades que\ndevem ser observadas ao se propor o\ntratamento adequado. Acerca do tratamento da hipertensão\narterial sistêmica para esses indivíduos e conforme as recomendações das Diretrizes Brasileiras de\nHipertensão Arterial - 2020, julgue o item a seguir. Em pacientes hipertensos sob tratamento\ndialítico, as médias sistólicas obtidas por medidas domiciliares associam-se linearmente ao\naumento do risco cardiovascular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-291471","number":"291471","sourceNumber":"291471","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma mulher de 48 anos de idade é trazida por familiares à unidade de emergência de\nhospital de alta complexidade com quadro de confusão mental, cefaleia e amaurose bilateral.\n\nSegundo familiares, a paciente é portadora de hipertensão arterial sistêmica há 2 anos, vindo em\ninvestigação diagnóstica por ser classificada como hipertensão arterial resistente. Nas últimas 2\nsemanas, a paciente passou a não tomar seus fármacos anti-hipertensivos, em razão de acreditar\nque o tratamento não estava mais funcionando. Na véspera, a paciente começou a se queixar de\ncefaleia holocraniana, pouco responsiva a fármacos, além de turvação visual. No dia de hoje, a\npaciente tornou-se um pouco confusa e começou a se queixar de que não estava conseguindo\nenxergar nada, razão por que foi trazida, às pressas, à unidade de emergência. Ao exame físico, a\npaciente mostra-se confusa, sonolenta, atendendo com dificuldade a algumas solicitações verbais.\nSua Pressão Arterial (PA) encontra-se em 240 x 160 mmHg em ambos os membros superiores,\nenquanto a frequência cardíaca é de 96 bpm. Um sopro é auscultado no flanco direito de seu\nabdome. Iniciado tratamento anti-hipertensivo, intravenoso, a paciente é submetida a uma\ntomografia computadorizada de crânio em que foram detectadas áreas hipodensas em regiões\noccipitais. A paciente é, então, encaminhada para realização de uma ressonância magnética de\nencéfalo que, na imagem pesada em T2, revela a presença de hiperintensidade de sinal nos lobos,\noccipitais, sem limites muito bem definidos. Instituído o tratamento indicado, a paciente evolui com\nregressão completa dos déficits neurológicos previamente descritos. Acerca do tratamento da\npaciente em questão, pode-se afirmar que:","options":{"A":"O alvo terapêutico no caso seria a normalização da pressão arterial em, no máximo, 2 horas.","B":"Após compensação clínica, seria fundamental ressecar o tumor adrenal secretor presente à\ndireita.","C":"Nicardipina e labetalol por via intravenosa seriam excelentes escolhas farmacológicas para\nredução da PA da paciente.","D":"Em razão da presença de trombose da artéria basilar, deveria ser adicionada anticoagulação\nplena com heparina de baixo peso molecular."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-268899","number":"268899","sourceNumber":"268899","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de 57 anos de idade compareceu ao atendimento ambulatorial para ajuste\nde medicamento anti-hipertensivo; faz uso de\namlodipina 10 mg ao dia. Não apresentou queixas.\n\nAo exame, observam-se FC= 80 bpm, FR = 20 irpm, SatO2 = 97% e PA = 160 mmHg x100 mmHg.\nDe acordo com uma possível comorbidade\napresentada pelo paciente, assinale a alternativa que\ncorresponde a uma adequada indicação de anti-hipertensivo.","options":{"A":"Diabetes mellitus - Hidroclorotiazida.","B":"Gota - Losartana.","C":"Disfunção erétil - Clonidina.","D":"Insuficiência coronariana - Hidralazina.","E":"Asma - Propranolol."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-263362","number":"263362","sourceNumber":"263362","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma mulher com 69 anos de idade, hipertensa, em uso de enalapril 40 mg/dia e de\nhidroclorotiazida 25 mg/dia, tem palpitações, tremores de membros superiores e dispneia que\ncomeçaram há cerca de 30 minutos, logo após ter sido assaltada. Está orientada, corada, sem\ndéficits motores focais, FC = 110 bpm, PA = 200 x 120 mmHg em membros superiores. Ausculta\ncardíaca: bulhas normofonéticas, ritmo regular em 2 tempos, sem sopros. Pulsos radiais e femorais\namplos, bilateralmente, FR = 24 irpm, sem esforço respiratório. Ausculta pulmonar normal.\n\nOximetria de pulso de 99 % (em ar ambiente). O eletrocardiograma mostra taquicardia sinusal e\nsinais de sobrecarga ventricular esquerda. A abordagem inicial adequada para essa paciente é\nadministrar","options":{"A":"nifedipina de liberação rápida por via oral ou sublingual, repetindo a medicação se PA\npermanecer acima de 180 x 100 mmHg após 60 minutos.","B":"ansiolítico por via oral, mantendo-a em observação em local tranquilo e reavaliando os níveis\npressóricos num intervalo de 30 a 60 minutos.","C":"nitroglicerina por via endovenosa contínua, ajustando a dose a cada 5 minutos até alcançar\nníveis pressóricos inferiores a 160 x 90 mmHg.","D":"metoprolol em bolus por via endovenosa, repetindo a medicação se PA permanecer acima de\n180 x 100 mmHg após 10 minutos."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-273342","number":"273342","sourceNumber":"273342","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo feminino, 67 anos, hipertensa, obesa, dislipidêmica, apresenta em\nconsultas sucessivas níveis pressóricos médios de 156x104 e IMC 30,5; está em uso de losartana\n100mg/dia e atenolol 50mg/dia. Perfil laboratorial: Cr 0,7, LDL 162, HDL 33, TGL 270, Glic 110.\n\nConsidere RCV: risco cardiovascular e LOA: lesão de órgão alvo. Nesse caso, o RCV é:","options":{"A":"intermediário; a avaliação de LOA não á mandatória; a meta pressórica é < 135x85; o tratamento\né inadequado e deverá ser reformulado","B":"muito alto; deverá ser avaliada a presença de LOA; a meta pressórica é < 130x80; ao tratamento\natual deverá ser associado inicialmente um\ndiurético tiazídico","C":"intermediário; deverá ser avaliada a presença de LOA; a meta pressórica é < 140x90; ao\ntratamento atual deve ser associado um bloqueadores de canais de cálcio","D":"alto; deverá ser avaliada a presença de LOA; a meta pressórica é < 130x80; o tratamento é\ninadequado e deverá ser reformulado"},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-273343","number":"273343","sourceNumber":"273343","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um homem, de 78 anos, há 2 meses queixa-se de falta de ar, com piora progressiva.\nAos grandes esforços, sente queimação\nretroesternal e, em uma dessas ocasiões, sentiu tonturas,\nescurecimento visual e quase desmaiou, melhorando ao se deitar. Para conseguir dormir, eleva a\ncabeceira da cama e, mesmo assim, acorda com ?canseira? todas as noites, melhorando quando\nse senta. Refere, ainda, ?inchaço? nas pernas. Exame físico: PA = 128x88mmHg, FC = 108bpm,\nem bom estado geral, com extremidades quentes, jugulares túrgidas a 45ª e pulsos carotídeos\ndiminuídos. Pulmões: murmúrio vesicular presente com estertores crepitantes nas bases. Coração:\nbulhas arrítmicas normofonéticas, com desdobramento da 2ª bulha na expiração, B4 audível em\nmesocárdio e foco mitral e sopro sistólico paraesternal à direita, com irradiação para as\ncarótidas. A\nausculta cardíaca refere-se a:","options":{"A":"ausência de fibrilação atrial e estenose aórtica.","B":"presença de fibrilação atrial e insuficiência tricúspide.","C":"sobrecarga de volume e insuficiência mitral.","D":"presença de fibrilação atrial e estenose aórtica."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-291537","number":"291537","sourceNumber":"291537","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma mulher de 38 anos de idade é admitida na enfermaria de cardiologia de hospital\nde alta complexidade, em função de quadro\nde dispneia progressiva, ortopneia e dispneia\nparoxística noturna. Segundo a paciente informa, seus sintomas anteriores iniciaram-se há cerca de\n1 ano, tendo progredido ao longo do período. Procurou assistência médica em algumas ocasiões,\nsendo finalmente internada para realização de exames complementares e definição diagnóstica.\n\nEm sua história patológica pregressa, há relato de dois episódios de febre reumática na\nadolescência, num dos quais foi detectado um\n\"sopro no coração\". Fez uso de penicilina benzatina\nde forma mensal, mas irregular, até os 18 anos de idade. Nega outros dados relevantes de\nanamnese. Ao exame físico, paciente está em bom estado geral, em atitude ortopneica. Não há\nfebre. PA = 120 x 70 mmHg; FC = 87 bpm. Ritmo cardíaco é irregular, em 2 tempos, com 1.° bulha\nhiperfonética e presença de sopro diastólico (2+/6+) em ponta, melhor audível em semi-decúbito\nlateral esquerdo; um ruído protodiastólico curto, de alta frequência, é também auscultado no foco\nmitral, mas não se observa reforço do ruflar diastólico. Há anicardiosfigmia. Não é detectada\nturgência jugular a 45°. Estertores crepitantes finos são auscultados em bases. Não há congestão\nhepática, nem edema de MMII. Exames complementares iniciais (incluindo VHS) revelam-se\nnormais, sendo a pesquisa de ASLO e swab de orofaringe negativos para infecção por\nstreptococcus pyogenes. Eletrocardiograma revela ritmo de fibrilação atrial, com QT normal. Diante\ndos dados relatados, a melhor explicação para o quadro da paciente é","options":{"A":"insuficiência valvar aórtica.","B":"estenose mitral reumática.","C":"cardite reumática aguda","D":"endocardite infecciosa de septo interventricular."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-263438","number":"263438","sourceNumber":"263438","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um homem com 50 anos de idade é internado em hospital terciário para investigação\ndiagnóstica e tratamento de quadro\ncaracterizado por dispneia aos moderados esforços. Há relato,\nainda, de precordialgia em aperto, com duração de cerca de 5 minutos, precipitada por esforços e\naliviada com o repouso, além da ocorrência de 2 episódios de síncope nos últimos 12 meses. Ao\nrealizar exame físico, constatou-se que o paciente se encontra em regular estado geral, corado,\nacianótico, eupneico, com a cabeceira do leito elevada a 30 graus. Seu ritmo cardíaco é regular,\nem 3 tempos, com a presença de 4.ª bulha e a existência de um sopro mesossistólico 3+/6+ mais\naudível no 2.º espaço intercostal direito, na borda esternal; os pulsos arteriais são do tipo\nparvus et\ntardus. A ausculta pulmonar apresenta discretos estertores crepitantes em bases. Não há edema\nde membros inferiores. A radiografia de tórax (PA e perfil) mostra leve dilatação da raiz da aorta,\nárea cardíaca normal e presença de calcificações mitro-aórticas. É solicitado, então, um\necocardiograma transtorácico que revela área valvar aórtica de 0,9 cm² (normal: 3 a 4 cm²), sendo\no gradiente ventrículo esquerdo (VE) - aorta de 55 mmHg e velocidade máxima de fluxo transvalvar\nde 4,5 metros/segundo (normal = inferior a 2m/seg); fração de ejeção do VE é de 52 %. Frente ao\nprocesso de avaliação diagnóstica e ao estabelecimento de plano terapêutico neste momento, qual\né a conduta médica indicada para o paciente e sua justificativa?","options":{"A":"Indicar início de tratamento farmacológico com diurético de alça, inibidor de enzima conversora\nde angiotensina e nitrato, dada a presença de\ninsuficiência cardíaca provocada pelo aneurisma da\naorta torácica ascendente.","B":"Solicitar a complementação do ecocardiograma com infusão endovenosa de dobutamina, em\nrazão da necessidade de melhor definir o comprometimento da função diastólica causado pela\nregurgitação valvar aórtica.","C":"Proceder cateterismo cardíaco diagnóstico e possivelmente terapêutico, dada a inegável\nexistência de doença arterial coronariana como causa da angina pectoris estável e disfunção\nsistólica do VE.","D":"Solicitar avaliação do risco cirúrgico visando à realização de troca valvar aórtica, em razão da\n\nexistência de estenose aórtica grave sintomática, com indicação de substituição da valva afetada."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-230543","number":"230543","sourceNumber":"230543","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Ocorrem diversas circunstâncias que podem alterar a medida das velocidades do fluxo\ne a avaliação anatômica, sendo que a\navaliação das velocidades pode estar comprometida em\nalgumas condições que afetam as medidas da análise espectral. Podemos APENAS aceitar o item:","options":{"A":"Dentre as condições proximais à bifurcação ressaltamos as valvopatias aórticas (estenose ou\ninsuficiência), estenoses de origem aterosclerótica ou arterites com envolvimento do arco aórtico,\nramos e carótida comum.","B":"Dentre as condições distais à bifurcação ressaltamos as valvopatias aórticas (estenose),\nestenoses de origem aterosclerótica ou\narterites com envolvimento do arco aórtico, ramos e\ncarótida comum.","C":"Dentre as condições proximais à bifurcação excluímos as valvopatias aórticas (estenose ou\ninsuficiência).","D":"Dentre as condições proximais à bifurcação ressaltamos as valvopatias aórticas (estenose ou\ninsuficiência), estenoses de origem aterosclerótica ou arterites com envolvimento do arco aórtico,\nmas não dos ramos e carótida comum."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-206171","number":"206171","sourceNumber":"206171","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A Insuficiência Mitral (IM) primária crônica é uma das valvopatias mais prevalentes\nmundialmente. A etiologia reumática ainda\né predominante no Brasil, embora o prolapso da valva\nmitral tenha aumentado em frequência. Algumas das características de insuficiência mitral primária,\nimportantes ao exame físico, são listadas abaixo, indique a fora de contexto:","options":{"A":"Ictus cordis desviado para a esquerda e para baixo.","B":"Primeira bulha hiperfonética.","C":"Segunda bulha hiperfonética.","D":"Sopro sistólico regurgitativo ? +++/6+."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-206174","number":"206174","sourceNumber":"206174","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em razão do aumento da expectativa de vida e do consequente envelhecimento da\npopulação, a estenose aórtica (EAo) apresenta prevalência crescente na atualidade, o diagnóstico\nde estenose aórtica é importante e apresenta diversas características. Quanto a isso, determine o\nitem que NÃO faz parte de uma dessas características:","options":{"A":"Pulso Parvus et Tardus.","B":"Sopro sistólico ejetivo com pico protosistólico.","C":"Hipofonese de B2.","D":"Hipofonese de B1."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-206177","number":"206177","sourceNumber":"206177","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Sinais de Musset, sinal de Becker, dança das artérias, sinal de Muller, sinal de Quincke,\nsinal de Rosenbach, sinal de Gerhard,\nsinal de Traube, sinal de Duroziez, sinal de Mayne e sinal de\nHill. Podem ser entendidos ADEQUADAMENTE como:","options":{"A":"Sinais clínicos de aumento de pressão de pulso.","B":"Sinais clínicos de diminuição de pressão de pulso.","C":"Sinais clínicos de redução de pressão de pulso.","D":"Sinais clínicos de fluxo de pressão de pulso."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-212131","number":"212131","sourceNumber":"212131","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Com relação a doenças respiratórias, julgue o item a seguir. A Síndrome da Apneia\nObstrutiva do Sono (SAOS) aumenta, de forma significativa, o risco de doença coronariana;\ninsuficiência cardíaca (com ou sem redução da fração de ejeção); ocorrência de arritmias atriais e\nventriculares; aterosclerose; doença coronariana; acidente vascular encefálico e diabetes melito.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-212094","number":"212094","sourceNumber":"212094","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Procurou assistência médica uma paciente de 25 anos de idade, que apresentava\ndispneia aos médios esforços e edema nos\nmembros inferiores, o qual ficava mais acentuado no\nfinal da tarde. Ela tinha histórico de amigdalites de repetição. No exame físico, constatou-se\npressão arterial de 110 mmHg x 70 mmHg, frequência cardíaca de 92 bpm, saturação de oxigênio =\n93% (ar ambiente) e presença de estertores inspiratórios em terço inferior de ambos os hemotórax,\nà ausculta pulmonar. O exame cardiovascular evidenciou precórdio calmo, ictus cordis visível e\npalpável no 5° espaço intercostal esquerdo, na linha hemiclavicular esquerda, e discreta impulsão\nno terço inferior da região esternal (no sentido craniocaudal). A ausculta cardíaca mostrou ritmo\ncardíaco regular em 2 tempos, hiperfonese da primeira bulha em área mitral, na qual, também, foi\nconstatada a presença de sopro diastólico (tipo ruflar) ? grau 3 de Levine ? seguido de esforço\n\npré-sistólico e de ruído de abertura da mitral, e discreta hiperfonese da segunda bulha em área\npulmonar. O abdome apresentava-se livre e\nsem visceromegalias. O edema era mole, frio, indolor,\ncom sinal de Godet presente, e observado nos dois terços inferiores de ambas as pernas. Foi\nrealizado Eletrocardiograma (ECG) de 12 derivações. Considerando esse caso clínico, julgue o item\nsubsecutivo. O principal diagnóstico dessa paciente é estenose mitral pura.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-212136","number":"212136","sourceNumber":"212136","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Procurou assistência médica uma paciente de 25 anos de idade, que apresentava\ndispneia aos médios esforços e edema nos\nmembros inferiores, o qual ficava mais acentuado no\nfinal da tarde. Ela tinha histórico de amigdalites de repetição. No exame físico, constatou-se\npressão arterial de 110 mmHg x 70 mmHg, frequência cardíaca de 92 bpm, saturação de oxigênio =\n93% (ar ambiente) e presença de estertores inspiratórios em terço inferior de ambos os hemotórax,\nà ausculta pulmonar. O exame cardiovascular evidenciou precórdio calmo, ictus cordis visível e\npalpável no 5° espaço intercostal esquerdo, na linha hemiclavicular esquerda, e discreta impulsão\nno terço inferior da região esternal (no sentido craniocaudal). A ausculta cardíaca mostrou ritmo\ncardíaco regular em 2 tempos, hiperfonese da primeira bulha em área mitral, na qual, também, foi\nconstatada a presença de sopro diastólico (tipo ruflar) - grau 3 de Levine - seguido de esforço\n\npré-sistólico e de ruído de abertura da mitral, e discreta hiperfonese da segunda bulha em área\npulmonar. O abdome apresentava-se livre e\nsem visceromegalias. O edema era mole, frio, indolor,\ncom sinal de Godet presente, e observado nos dois terços inferiores de ambas as pernas. Foi\nrealizado Eletrocardiograma (ECG) de 12 derivações. Considerando esse caso clínico, julgue o item\nsubsecutivo. Com base nas manifestações clínicas observadas, ao pedir o ECG, o médico já\ndeverá inferir que devem estar presentes as seguintes alterações eletrocardiográficas: eixo elétrico\ndo complexo QRS desviado para a esquerda (acima de -30°); onda P na derivação D2, com\nduração normal apiculada, com aumento de sua amplitude que indique sobrecarga atrial esquerda;\ncomplexo QRS com aumento de tempo de ativação (deflexão intrinsecoide); e aumento de\namplitude (>30 mm) nas derivações do plano horizontal, o que indica sobrecarga ventricular\nesquerda.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-206133","number":"206133","sourceNumber":"206133","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Alterações próprias do envelhecimento determinam aspectos diferenciais na PA dessa\npopulação, sendo INADEQUADO se considerar que,","options":{"A":"o envelhecimento vascular é o aspecto principal relacionado à elevação da PA nos idosos,\ncaracterizado por alterações na microarquitetura da parede dos vasos, com consequente\nenrijecimento arterial.","B":"grandes vasos, como a aorta, perdem sua distensibilidade e, apesar de os mecanismos precisos\nnão estarem claros, envolvem\n\nprimariamente mudanças estruturais na camada média dos vasos, como fratura por fadiga da\nelastina, depósito de colágeno e calcificação.","C":"alterações próprias do envelhecimento determinam aspectos diferenciais na PA dessa\npopulação, como maior frequência de hiato\nauscultatório, que consiste no desaparecimento dos\nsons durante a deflação do manguito, geralmente entre o final da fase I e o início da fase II dos\nsons de Korotkoff, resultando em valores falsamente baixos para a PAS ou falsamente altos para a\nPAD.","D":"apesar de os indivíduos nessa faixa etária serem menos conscientes de sua condição e estarem\nmais frequentemente sob tratamento do que os\nhipertensos de meia-idade, as taxas de controle da\nPA nos idosos são inferiores, em especial após os 60 anos."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-206142","number":"206142","sourceNumber":"206142","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O diagnóstico e a avaliação do grau de envolvimento com LOA são fundamentais para\na escolha do tratamento, sendo INADEQUADO que","options":{"A":"a hipertensão renovascular (HARV) não pode ser secundária à estenose parcial, uni ou bilateral\nda artéria renal (EAR), desencadeada e mantida\npor isquemia do tecido renal.","B":"a hipertensão renovascular (HARV) tem prevalência de 5% dos pacientes hipertensos.","C":"a principal causa é a aterosclerose (90%), seguida por displasia fibromuscular, sendo a arterite\nde Takayasu a menos frequente.","D":"independentemente do fator causal, é importante determinante de morbimortalidade CV."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-206148","number":"206148","sourceNumber":"206148","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para indicação da opção terapêutica, deve-se considerar a etiologia e as condições\nclínicas associadas à Hipertensão Arterial. Sendo INCORRETO se considerar que,","options":{"A":"em pacientes com HARV por displasia fibromuscular há 82- 100% de controle da PA e\nre-estenose em 10%.","B":"evidências de benefício no tratamento mecânico percutâneo ou cirúrgico não estão restritas a\nsituações como perda progressiva da função renal, EAP e dificuldade de controle da PA, que\npromove Lesão de órgão-alvo LOA irreversível.","C":"na Hipertensão renovascular HARV aterosclerótica sem complicações, o implante de stent\ncomparado ao tratamento clínico otimizado não mostrou benefícios no controle da PA, na\nprogressão da doença renal, ou na ocorrência de eventos clínicos e mortalidade.","D":"para pacientes com EAR aterosclerótica e PA controlada por tratamento clínico, sem\ncomplicações cardíacas e função renal estável ao\nlongo de 6-12 meses, a intervenção mecânica\nnão é recomendada, sendo o tratamento clínico a primeira opção."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-206084","number":"206084","sourceNumber":"206084","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para detecção de adenoma unilateral produtor de Aldo APA ou hiperplasia, é indicada\nTC de adrenais com cortes finos ou RNM.\nSendo CORRETA a seguinte conduta:","options":{"A":"o cateterismo de veias adrenais é indicado quando, à TC, as adrenais são normais, têm\nanormalidades bilaterais (espessamento\n\nou micronódulos) ou lesão unilateral em pacientes > 60 anos.","B":"o teste de supressão com dexametasona é indicado para investigar HAP supressível por\nglicocorticoide em pacientes com hiperaldosteronismoprimário HAP e início de HA antes dos 40\nanos.","C":"o cateterismo de veias adrenais é contraindicado quando, à TC, as adrenais são normais, têm\nanormalidades bilaterais (espessamento ou micronódulos) ou lesão unilateral em pacientes > 40\nanos.","D":"o teste de supressão com dexametasona não é indicado para investigar HAP supressível por\nglicocorticoide em pacientes com hiperaldosteronismo primário HAP e início de HA antes dos 40\nanos."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175082","number":"175082","sourceNumber":"175082","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro das evoluções de diversas doenças relacionadas a dano ao miocárdio, podemos\napenas considerar como INCORRETA a alternativa,\nque demonstra inadequado conceito de\nevolução ou fisiopatologia:","options":{"A":"A sarcoidose é uma doença multissistêmica de etiologia desconhecida, caracterizada pelo\nacúmulo de linfócitos T, fagócitos mononucleares e granulomas não caseosos nos tecidos\nenvolvidos. Os pulmões são afetados em aproximadamente 90% dos pacientes, e a presença de\ndoença pulmonar contribui de forma independente para a morbimortalidade associada a essa\ndoença.","B":"A miocardite de células gigantes é uma forma autoimune de agressão miocárdica e\ncaracteriza-se histologicamente por um infiltrado de\ncélulas gigantes multinucleadas, além de\ninfiltrado inflamatório de células T, eosinófilos e histiócitos.","C":"A grande liberação de citocinas inflamatórias e mediadores do estresse oxidativo, leva a uma\nintensa agressão às células miocíticas. O que\nleva a perda de miócitos, além de uma reposição por\nneo formação de miócitos. Essa intensa agressão, promove uma evolução acelerada . Ocorre\nassim perda rápida da função ventricular e evolução clínica desfavorável.","D":"A Síndrome Hipereosinofílica pode ocorrer em associação a diversas doenças com\nmanifestação sistêmica, como Síndrome de Churg-Strauss, câncer, infecções parasitárias e\nhelmínticas, ou estar relacionada a vacinações."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175083","number":"175083","sourceNumber":"175083","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A importância do conhecimento do eletrocardiograma do atleta é muito importante\natualmente, devido à inclusão do ECG de repouso na\navaliação pré-participação esportiva, faz-se\nnecessário o entendimento do ?ECG de atleta?, sendo essas alterações eletrocardiográficas\ndecorrentes do treinamento de alta performance, sem, necessariamente, alterações anatômicas\ne/ou estruturais, considerados como parte do ?coração de atleta?. Das descrições abaixo, uma se\nmostra INCORRETA nesse contexto, assinale-a:","options":{"A":"Redução do intervalo PR.","B":"Bradicardia sinusal.","C":"Arritmia sinusal fásica ou respiratória.","D":"Aumento da voltagem de ondas R ou S entre 30 a 35 mm."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175093","number":"175093","sourceNumber":"175093","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Na miocardite induzida por drogas existem diversos aspectos em usa gênese e\nfisiopatologia que devem ser adequadamente conhecidos. Dentre os aspectos apresentados nas\nalternativas abaixo, assinale o INCORRETO:","options":{"A":"Na miocardite induzida por drogas parte da justificativa da hipersensibilidade se dá em resposta\na componentes quimicamente reativos que se ligam a\nproteínas promovendo modificações\nestruturais. Essas partículas são fagocitadas pelas células de defesa, por vezes macrófagos, os\nquais as apresentam na superfície dessas células aos linfócitos T.","B":"Na miocardite induzida por drogas, uma resposta de hipersensibilidade retardada, são liberadas\ncitocinas como interleucina 5, estimulante de eosinófilos.","C":"Na miocardite induzida por drogas o acúmulo de interleucina 5 promove um grande infiltrado\neosinofílico com aumento da resposta de hipersensibilidade e maior lesão miocárdica.","D":"Na miocardite induzida por drogas a predisposição genética não parece favorecer esse padrão\nde resposta."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175095","number":"175095","sourceNumber":"175095","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro da análise de um importante exame de imagem, o Ecocardiograma, podemos\napenas considerar como INCORRETO o seguinte\nachado relacionado com Miocardites:","options":{"A":"Os achados ecocardiográficos na miocardite são inespecíficos.","B":"As alterações ecocardiográficas espelham a agressão inflamatória miocárdica e as\nconsequências desta sobre a função e\n\nremodelagem ventricular, podendo ser encontrados trombos intraventriculares ou atriais.","C":"As alterações na contração ventricular podem ser difusas ou segmentares, completamente\ndiferentes das alterações isquêmicas.","D":"Na miocardite fulminante, usualmente encontramos importante disfunção sistólica com diâmetros\ncavitárias normais, por vezes associada a aumento da espessura da parede septal, indicando\nedema miocárdico."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175097","number":"175097","sourceNumber":"175097","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quando analisamos a importância da Biópsia Cardíaca para o correto diagnóstico,\ndevemos também analisar as complicações relacionadas\na ela. Sobre isso, assinale a alternativa\nINCORRETA:","options":{"A":"As complicações da biópsia endomiocárdica felizmente são raras.","B":"A utilização do ecocardiograma associado à fluoroscopia reduz, de forma significativa, a\npossibilidade de punção inadvertida que\n\npossa ocasionar perfuração miocárdica ou lesão de coronária.","C":"Entretanto, o pneumotórax e a perfuração do septo interventricular não são descritas como\ncomplicação.","D":"Perfuração de parede livre de VD pode ser considerada uma potencial complicação."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175099","number":"175099","sourceNumber":"175099","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Os exames de medicina nuclear têm sido aplicados há várias décadas na avaliação de\npacientes com suspeita de miocardite, somente não podemos considerar como CORRETA\nalternativa:","options":{"A":"Suas principais aplicações estão relacionadas à avaliação da função ventricular esquerda,\navaliação da presença de inflamação cardíaca, identificação de subtipos de miocardites e\nmonitoração da resposta terapêutica.","B":"Em alguns determinados tipos de miocardite como na sarcoidose, proporciona menor acurácia.","C":"A mais estudada na literatura é a cintilografia com 67-Gálio, que apresenta sensibilidade de 50%\nno diagnóstico da miocardite.","D":"A cintilografia com 67-Gálio têm sua melhor utilização diagnóstica se nos primeiros três meses\nde apresentação clínica da miocardite."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175100","number":"175100","sourceNumber":"175100","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A Biópsia Endomiocárdica (BEM), apesar de ser método invasivo, quando bem\nindicada, apresenta grande importância para o paciente, todas as alternativas abaixo se\napresentam de forma correta, com EXCEÇÃO de:","options":{"A":"A Biópsia Endomiocárdica (BEM) é o método ?padrão-ouro? para o diagnóstico da miocardite.","B":"A Biópsia Endomiocárdica (BEM) é o método ?padrão-ouro? para a pesquisa de persistência\nviral cardíaca, assim como de outras doenças\ncardiovasculares não inflamatórias.","C":"A BEM tem como objetivos estabelecer o diagnóstico de inflamação miocárdica com ou sem\npersistência viral, mas não consegue definir a necessidade e o tipo de terapêutica a ser adotada.","D":"Nas situações clínicas onde há insuficiência cardíaca de início recente (menos de 2 semanas),\ncom instabilidade hemodinâmica, sem resposta ao\ntratamento usual e/ou presença de arritmias\nventriculares ou bloqueios cardíacos de alto grau, a BEM desempenha importante papel na\ninvestigação do fator causal, com impacto na terapêutica."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175141","number":"175141","sourceNumber":"175141","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Dentro da abordagem de Jovens com Hipertensão Sistólica Isolada (HSI), podemos\nconsiderar como INCORRETO:","options":{"A":"A HSI é rara em jovens saudáveis do sexo masculino com menos de 30 anos e pode estar\nassociada à pressão central normal.","B":"A HSI em jovens saudáveis do sexo masculino com menos de 30 anos é associada à pressão\ncentral normal, o tratamento não teria benefícios significativos.","C":"A HSI em jovens saudáveis do sexo masculino, com pressão central normal, é recomendada a\nadoção de medidas não medicamentosas, com\nmonitorização de LOA.","D":"O tratamento da HSI deve ter início imediato de terapia farmacológica caso seu risco CV seja\nalto."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175170","number":"175170","sourceNumber":"175170","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Quando analisamos os aspectos relacionados aos cuidados de Hipertensão\nrelacionados na população idosa, apenas\npodemos considerar como correta a seguinte alternativa:","options":{"A":"Aspectos especiais na medição da PA na população idosa decorrem de alterações próprias do\nenvelhecimento, como a maior frequência do hiato auscultatório, que consiste no desaparecimento\ndos sons durante a deflação do manguito, resultando em valores falsamente baixos para a PAS ou\nfalsamente altos para a PAD.","B":"A grande variação da PA nos idosos ao longo das 24 horas torna a MAPA uma ferramenta\npoucas vezes útil.","C":"A pseudo-hipertensão, que está associada ao processo aterosclerótico, sendo que a manobra\nde Osler não tem capacidade de\ndiagnosticá-la, pois a artéria radial permanece ainda palpável\napós a insuflação do manguito pelo menos 30 mmHg acima do desaparecimento do pulso radial.","D":"Maior ocorrência de hipertensão pós-prandial e, finalmente, a presença de arritmias, como\nfibrilação atrial, podem impossibilitar a medição da PA."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183923","number":"183923","sourceNumber":"183923","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A respeito da hipertensão arterial sistêmica (HAS), considerada o principal fator de\nrisco\npara ocorrência de acidente vascular cerebral (AVC) e de infarto agudo do miocardio (IAM), julgue o\nitem a seguir. A avaliação do paciente hipertenso deverá incluir a realização de exame físico e de\nexames laboratoriais, entre eles o exame de urina para avaliação de proteinúria.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183936","number":"183936","sourceNumber":"183936","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A respeito da hipertensão arterial sistêmica (HAS), considerada o principal fator de\nrisco\npara ocorrência de acidente vascular cerebral (AVC) e de infarto agudo do miocárdio (IAM), julgue o\nitem a seguir. Apesar de o tabagismo ser uma prática social mundialmente relacionada a doenças\npulmonares, não existe relação comprovada entre o uso do cigarro e a ocorrência de infarto agudo\ndo miocárdio entre fumantes, independentemente da faixa etária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-175179","number":"175179","sourceNumber":"175179","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Hoje, em seu ambulatório, um antigo paciente em seguimento para Doença Chagásica\nsolicitou que lhe fosse explicado quais as interações que seus exames mais recentes tinham\ndemonstrado a respeito de seu prognóstico, então você o orientou adequadamente com diversos\ndados epidemiológicos e clínicos, sendo apenas um dos abaixo inadequado, indique-o:","options":{"A":"Nos pacientes com etiologia chagásica, a presença de taquicardia ventricular sustentada é\npreditor de prognóstico reservado.","B":"Nos pacientes com etiologia chagásica, a presença de taquicardia ventricular não sustentada é\npreditor de prognóstico reservado.","C":"A Fração de Ejeção de Ventrículo Esquerdo (FEVE) < 40% é o único preditor independente de\nmortalidade.","D":"Pacientes chagásicos em lista de espera para transplante cardíaco também apresentam melhor\nprognóstico em relação a outras etiologias."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-183954","number":"183954","sourceNumber":"183954","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"A respeito da hipertensão arterial sistêmica (HAS), considerada o principal fator de\nrisco\npara ocorrência de acidente vascular cerebrla (AVC) e de infarto agudo do miocardio (IAM), julgue o\nitem a seguir. As medidas para o tratamento da HAS demandam elevado custo financeiro,\nconsistindo grande desafio em todo mundo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-154510","number":"154510","sourceNumber":"154510","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo masculino com história de etilismo importante, cessado há dois anos\napós o diagnóstico de miocardiopatia\ndilatada de etiologia provavelmente alcoólica, com fração de\nejeção ventricular esquerda estimada em 34%. Comparece à consulta ambulatorial de rotina, em\nuso de Enalapril 10 mg 12/12h, Espironolactona 25 mg/dia e Furosemida 40 mg/dia,\napresentando-se com dispneia apenas aos grandes esforços (consegue caminhar mais de 200 m\n\nem região plana, com leve limitação das atividades físicas). Ao exame físico: Pressão arterial = 100\nx 60 mmHg; Frequência de pulso = 100 bpm;\nritmo regular; Ausculta pulmonar; murmúrio vesicular\nfisiológico, sem ruídos adventícios. Ausculta cardíaco regular, em 2 tempos, sem sopros; Sem\noutras alterações dignas de nota. Segundo a classificação da New York Heart Association (NYHA)\npara Insuficiência Cardíaca, qual seria a classe funcional (CF) deste paciente?","options":{"A":"I.","B":"II.","C":"III.","D":"IV.","E":"V."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-154514","number":"154514","sourceNumber":"154514","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente do sexo masculino com história de etilismo importante cessado há dois anos\napós o diagnóstico de miocardiopatia\ndilatada de etiologia provavelmente alcoólica, com fração de\nejeção ventricular esquerda estimada em 34%. Comparece à consulta ambulatorial de rotina, em\nuso de enalapril 10 mg 12/12h, espironolactona 25 mg/dia e furosemida 40 mg/dia,\n\napresentando-se com dispneia apenas aos grandes esforços (consegue caminhar mais de 200 m\nem região plana, com leve limitação das\natividades físicas). Ao exame físico: pressão arterial = 100\nx 60 mmHg; frequência de pulso = 100 bpm, ritmo regular; ausculta pulmonar; murmúrio vesicular\nfisiológico, sem ruídos adventícios; ausculta cardíaca regular, em 2 tempos, sem sopros; sem\noutras alterações dignas de nota. Na consulta, inicia-se terapia betabloqueadora com carvedilol\n3,125 mg de 12/12h e, após uma semana, o paciente retorna. Refere piora da dispneia, agravada\nao deitar-se (relata que precisa dormir com a cabeceira mais elevada), e surgindo aos mínimos e\nmoderados esforços, gerando limitação das atividades cotidianas. Ao exame físico neste momento:\npressão arterial = 98 x 60 mmHg; frequência de pulso = 84 bpm, ritmo regular; ausculta pulmonar\ncom estertores bibasais, estase jugular a 45º; edema de membros inferiores +2/+4; sem outras\nalterações. Neste momento, qual é a conduta médica mais adequada?","options":{"A":"Suspender o carvedilol.","B":"Trocar o carvedilol por ivabradina.","C":"Reduzir dose do carvedilol pela metade e associar diurético tiazídico.","D":"Manter carvedilol em mesma dose, e aumentar dose de furosemida.","E":"Aumentar a dose do carvedilol e trocar enalapril por losartana."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-158066","number":"158066","sourceNumber":"158066","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente de 13 anos de idade, obeso, mas sem outras comorbidades conhecidas,\napresenta-se à consulta acompanhado da mãe a\nfim de solicitar atestado para liberação para\natividade física, exigido para participação das aulas de educação física na respectiva escola. Ao\nexame físico, apresenta: PA MSD = 200 mmHg x 120 mmHg; PA MSE = 120 mmHg x 80 mmHg;\nAC = BNF; RR; 2T, presença de sopro sistólico 2+/6+ em todo o precórdio; AP = normal; ABD =\nnormal; Ext = pulsos pediosos presentes, mas de baixa amplitude. O ECG foi realizado com\npresteza pela equipe de ambulatório, revelando sinais de sobrecarga de ventrículo esquerdo. Em\nrelação ao caso apresentado, quanto ao provável diagnóstico do paciente e considerando as\nDiretrizes de Hipertensão da Sociedade Brasileira de Cardiologia, assinale a alternativa CORRETA.","options":{"A":"As formas mais severas dessa patologia costumam causar insuficiência cardíaca entre o final da\nadolescência e o início da idade adulta.","B":"Caso haja condições clínicas de postergação do tratamento cirúrgico, realizá-lo após os 14 anos\nde idade diminui a recorrência.","C":"O quadro clínico é compatível com coarctação de aorta na topografia de aorta torácica\ndescendente.","D":"O tratamento é sempre intervencionista.","E":"Essa patologia representa a segunda maior causa de hipertensão secundária na população\nbrasileira."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-159586","number":"159586","sourceNumber":"159586","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de quarenta e oito anos de idade procurou atendimento médico\nqueixando-se de sonolência diurna excessiva,\nronco alto, pausas respiratórias testemunhadas,\nengasgos e sono agitado. O exame físico revelou pressão arterial de 150 mmHg x 100 mmHg;\nfrequência cardíaca de 85 bpm; 1,70 m de altura; peso corporal de 118 kg; e palato ogival, sem\noutras alterações. O exame de polissonografia mostrou índice de apneia-hipopneia por hora (IAH)\nigual a 25 eventos/hora. Tendo como referência esse caso clínico, julgue o item que se segue. No\ncaso em apreço, a pressão arterial elevada decorre da inibição absoluta da atividade do sistema\nnervoso parassimpático (vagal) do paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-159590","number":"159590","sourceNumber":"159590","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de quarenta e oito anos de idade procurou atendimento médico\nqueixando-se de sonolência diurna excessiva,\nronco alto, pausas respiratórias testemunhadas,\nengasgos e sono agitado. O exame físico revelou pressão arterial de 150 mmHg x 100 mmHg;\nfrequência cardíaca de 85 bpm; 1,70 m de altura; peso corporal de 118 kg; e palato ogival, sem\noutras alterações. O exame de polissonografia mostrou Índice de Apneia-hipopneia por Hora (IAH)\nigual a 25 eventos/hora. Tendo como referência esse caso clínico, julgue o item que se segue. No\ncaso em consideração, recomenda-se, como principal tratamento, a realização de pressão positiva\ncontínua nas vias respiratórias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-159594","number":"159594","sourceNumber":"159594","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente de quarenta e oito anos de idade procurou atendimento médico\nqueixando-se de sonolência diurna excessiva,\nronco alto, pausas respiratórias testemunhadas,\nengasgos e sono agitado. O exame físico revelou pressão arterial de 150 mmHg x 100 mmHg;\nfrequência cardíaca de 85 bpm; 1,70 m de altura; peso corporal de 118 kg; e palato ogival, sem\noutras alterações. O exame de polissonografia mostrou índice de apneia-hipopneia por hora (IAH)\nigual a 25 eventos/hora. Tendo como referência esse caso clínico, julgue o item que se segue. O\nprincipal diagnóstico para o paciente em questão é síndrome de apneia obstrutiva do sono (SAOS).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-159573","number":"159573","sourceNumber":"159573","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Julgue o próximo item, relativo à síndrome de apneia obstrutiva do sono (SAOS). As\nvariáveis com maior valor preditivo positivo para diagnóstico de SAOS são circunferência de\npescoço, roncos e índice de massa corporal (IMC).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-133927","number":"133927","sourceNumber":"133927","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"De acordo com o documento VI Diretrizes Brasileiras de Hipertensão, a aferição da\npressão arterial dever ser feita a partir de","options":{"A":"Dois minutos de repouso em ambiente calmo.","B":"Doze horas de abstinência sexual.","C":"Deflação do manguito na velocidade de 10 mmHg por segundo.","D":"Sessenta minutos sem atividade física.","E":"Duas horas sem uso de tabaco."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-133935","number":"133935","sourceNumber":"133935","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Paciente feminina de 36 anos de idade, sedentária e obesa, agenda uma consulta por\nestar preocupada com a pressão arterial em razão\nde recente óbito familiar. Mostra-se ansiosa para\nfazer \"todos os exames de pressão\", mas se queixa de dificuldade financeira e pede somente os\nexames com maior nível de evidência. Considerando essa situação hipotética, é CORRETO afirmar\nque a paciente foi adequadamente orientada, caso tenha sido informada de que, entre os exames\niniciais, os que têm nível de evidência B, de acordo com VI Diretrizes Brasileiras de Hipertensão,\nsão os seguintes:","options":{"A":"De ureia e de potássio.","B":"Ecocardiograma e de glicemia de jejum.","C":"De glicemia pós-prandial e de creatinina.","D":"De curva glicêmica e de colesterol total.","E":"De creatinina e de eletrocardiograma."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-133942","number":"133942","sourceNumber":"133942","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Preocupado com o recente diagnóstico de insuficiência cardíaca, um nutricionista de 58\nanos de idade indaga acerca das adequações\ndietéticas com maior nível de evidência, dizendo-se\ndisposto a seguir qualquer terapêutica com recomendação Classe 1 da III Diretriz Brasileira de\nInsuficiência Cardíaca Crônica. Considerando essa situação hipotética, a referida recomendação é\nrestrição","options":{"A":"Hídrica de 1.000-1.500 mL em pacientes sintimáticos com risco de hipervolemia.","B":"Do consumo de sódio a 2-3 gramas por dia, desde que não comprometa a ingesta calórica e na\nausência de hiponatremia.","C":"Do consumo de sódio a menos de 10 gramas por dia, desde que não comprometa a ingesta\ncalórica e na ausência de hiponatremia.","D":"Hídrica menor que 1.000 mL em pacientes sintomáticos com risco de hipervolemia.","E":"Do consumo de sódio a menos de 2 gramas por dia, desde que não comprometa a ingesta\ncalórica e na ausência de hiponatremia."},"answer":"B","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-104742","number":"104742","sourceNumber":"104742","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Para a avaliação da pressão arterial em consulta ambulatorial ser adequada, deve ser\nfeita em:","options":{"A":"duas medidas espaçadas em cinco minutos.","B":"duas medidas seguidas.","C":"uma medida, em decúbito dorsal, seguida de outra em posição ortostática.","D":"uma medida no braço direito e, cinco minutos após, na perna direita,","E":"três medidas seguidas."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-80694","number":"80694","sourceNumber":"80694","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Insuficiência cardíaca é uma situação clínica comum no Brasil e tem etiologias diversas.\nAlgumas condições gerais devem ser identificadas precocemente pelo clínico assistente como\nfatores causais. Com base nessa informação, assinale a alternativa que apresenta um desses\nfatores.","options":{"A":"Contratilidade miocárdica prejudicada, levando à função sistólica reduzida, geralmente com\naumento da fração de ejeção.","B":"Função diastólica alterada, com função sistólica mantida, causando geralmente diminuição da\nfração de ejeção.","C":"Shunts arteriovenosos na circulação esplâncnica.","D":"Insuficiência valvular.","E":"Arritmias quando são do tipo em salvas."},"answer":"C","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-80723","number":"80723","sourceNumber":"80723","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação a pericardites é correto afirmar que a:","options":{"A":"Dor pré-cordial está presente em todos os pacientes independentemente da etiologia.","B":"Dor é típica e aumenta à expiração.","C":"Dor é aliviada na posição deitada (supino).","D":"Dor é muito diferente da que ocorre no infarto agudo do miocárdio e não entra em seu\ndiagnóstico diferencial.","E":"Pericardite que acontece na artrite reumatoide geralmente é assintomática."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-97795","number":"97795","sourceNumber":"97795","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Uma paciente com 19 anos de idade, primípara, na 24ª semana de gestação, vem à\nconsulta pré-natal com queixa de dispneia progressiva há duas semanas, inicialmente aos grandes\nesforços e, atualmente, aos médios esforços. Ao exame físico, apresenta altura uterina compatível\ncom a idade gestacional, edema de membros inferiores ++/4+, estertores crepitantes em bases\npulmonares. Frequência respiratória = 24 irpm; frequência cardíaca = 106 bpm; ausculta com ritmo\ncardíaco regular e sopro diastólico (++/4) mais audível no ápice, acompanhado de hiperfonese de\nB1. Assinale a alternativa que apresenta corretamente a hipótese diagnóstica e a etiologia:","options":{"A":"Estenose mitral, provavelmente de origem reumática.","B":"Insuficiência mitral, provavelmente de origem reumática.","C":"Prolapso da válvula mitral, como parte de síndrome de Marfan.","D":"Sopro funcional, como parte do estado hipercinético da gravidez."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-97810","number":"97810","sourceNumber":"97810","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um paciente com 50 anos de idade, com diagnóstico de hipertensão pulmonar\nidiopática, com antecedente de internação\nprévia há um ano, devido à dispneia aos esforços e\nanasarca, deu entrada no pronto-socorro por ter apresentado episódio de síncope durante a\nrelação sexual. Refere fazer uso de diltiazem regularmente e informa que nos últimos dois meses\nhouve evolução da dispneia para pequenos esforços e surgimento de letargia. Nas últimas duas\nsemanas, vem evoluindo com dor abdominal em hipocôndrio direito e edema de membros inferiores\ne apresentou ainda três episódios de dor precordial em aperto, sem irradiação, desencadeados por\ngrandes esforços. Ao exame físico, mostra-se com estado geral regular, eupneico em repouso,\norientado, sem déficits neurológicos. A ausculta cardíaca revela ritmo regular, com hiperfonese de\nB2 , sem sopros, frequência cardíaca = 92 bpm, pressão arterial = 100 x 65 mmHg. Observa-se\nturgência jugular a 45° e ausculta pulmonar é normal. A palpação da borda hepática, a cerca de 5\ncm do rebordo costal direito, é levemente dolorosa. Há edema de membros inferiores, atingindo até\na coxa e parede abdominal, +++/4+, frio e indolor. Foram realizados radiografia de tórax (incidência\nposteroanterior) e Eletrocardiograma (ECG), mostrados a seguir (VER ANEXO).","options":{"A":"Radiografia do tórax: abaulamento do tronco da artéria pulmonar e redução da trama vascular\nperiférica pulmonar; ECG: bloqueio de ramo\ndireito, desvio do eixo cardíaco para a direita e padrão\nde repolarização ventricular do tipo strain.","B":"Radiografia do tórax: abaulamento do tronco da artéria pulmonar e redistribuição da trama\nvascular para os ápices pulmonares; ECG:\nbloqueio de ramo esquerdo, desvio de eixo cardíaco\npara a direita e padrão de repolarização ventricular do tipo strain.","C":"Radiografia do tórax: aumento de ambos os ventrículos cardíacos e redução da trama vascular\nperiférica pulmonar; ECG: bloqueio de ramo esquerdo, desvio do eixo cardíaco para a direita e\nalterações inespecíficas da repolarização ventricular.","D":"Radiografia do tórax: aumento de ambos os ventrículos cardíacos e redistribuição da trama\nvascular para os ápices pulmonares; ECG:\nbloqueio de ramo direito, desvio do eixo cardíaco para a\ndireita e alterações inespecíficas da repolarização ventricular."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":["question_bank/media/medcurso/medcurso-cardiologia-car-2/97810.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-80744","number":"80744","sourceNumber":"80744","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"O alcoolismo é um grave problema de saúde pública. Além de estar relacionado\ndiretamente a mortes violentas, pode gerar\nimportantes agravos orgânicos de saúde, sendo um\ndeles a miocardiopatia alcoólica. Com base nessa informação, assinale a alternativa em que a\nbebida apresenta, além do álcool, um componente que age sinergicamente na gênese daquela\npatologia.","options":{"A":"Aguardente, apresenta chumbo em sua composição.","B":"Vodka, apresenta mercúrio em sua composição.","C":"Conhaque, apresenta manganês em sua composição.","D":"Uísque, apresenta metais pesados em sua composição.","E":"Cerveja, apresenta cobalto em sua espuma."},"answer":"E","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-97839","number":"97839","sourceNumber":"97839","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Um homem, com 45 anos de idade, professor do ensino médio, é atendido em\nambulatório para tratamento de hipertensão\narterial diagnosticada há três anos como de natureza\nessencial (primária). Refere que nos últimos meses, mesmo fazendo uso regular de inibidores da\nenzima conversora de angiotensina, de bloqueador de canal de cálcio e de diurético, os seus níveis\npressóricos mantêm-se elevados. Tem história familiar de hipertensão arterial. Não refere\nantecedentes patológicos. Não é submetido a acompanhamento dietético ou à prática de exercícios\nfísicos regulares. Não utiliza outros medicamentos. Ao exame físico, apresenta-se em bom estado\ngeral, com índice de massa corporal = 30,6 kg/m², frequência respiratória = 22 irpm, frequência\ncardíaca = 112 bpm e pressão arterial = 160 x 110 mmHg; ausculta pulmonar normal; ritmo\ncardíaco regular em 2T, bulhas normofonéticas, sem sopros ou arritmias; exame abdominal e de\nmembros sem alterações. Exame de fundo de olho: tortuosidade e espessamento de arteríolas,\npresença de alguns cruzamentos patológicos. Eletrocardiograma com sinais de sobrecarga\nventricular esquerda e alterações difusas de repolarização. Radiografia de tórax com aumento da\nárea cardíaca por aumento do ventrículo esquerdo. Bioquímica sérica: glisose = 116 mg/dl (Valor\nde referência = 75-99 mg/dl), ureia = 70 mg/dl (Valor de referência = 20-35 mg/dl), creatinina = 1,8\nmg/dl (Valor de referência = 0,7-1,2 mg/dl). O quadro apresentado é demonstrativo de:","options":{"A":"hipertensão maligna instalada.","B":"insuficiência renal decorrente do uso de agentes hipertensivos.","C":"evolução natural da hipertensão essencial ligada à história familiar.","D":"comprometimento dos órgãos-alvos na hipertensão arterial sistêmica."},"answer":"D","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-2-64443","number":"64443","sourceNumber":"64443","collectionBlock":"medcurso:medcurso-cardiologia-car-2","collectionLabel":"Medcurso · CAR 2","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 2","subtopic":"","stem":"Em relação ao uso de betabloqueadores na Insuficiência Cardíaca (IC) é correto\nafirmar:","options":{"A":"Metoprolol e carvedilol comprovadamente reduzem a mortalidade na IC crônica.","B":"A meta para a dose de carvedilol é atingir dose diária de 12,5 mg/dia.","C":"Doses devem ser reajustadas a cada dois dias até se chegar aos níveis desejados.","D":"Não devem ser empregados em associação com diuréticos.","E":"Há contraindicação absoluta para o seu uso em diabéticos."},"answer":"A","source":"Cardiologia/CAR 2/CAR 2.txt","sourceLabel":"Medcurso · CAR 2","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
